window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["规定"] = {"shanghaihangyunjiaoyisuoguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对上海航运交易所的管理，维护航运交易秩序，促进水路货物运输业的发展，制定本规定。"},{"i":2,"n":"第二条","txt":"上海航运交易所（以下简称航运交易所）是不以营利为目的，为航运业务提供交易场所、设施、信息的事业法人。"},{"i":3,"n":"第三条","txt":"国务院交通主管部门和上海市人民政府，依照本规定对航运交易所进行管理和监督。"},{"i":4,"n":"第四条","txt":"航运交易所应当提供公开、公平、公正的交易环境和便利的交易条件，保证航运交易的正常进行。"},{"i":5,"n":"第五条","txt":"航运交易所实行理事会领导下的总裁负责制。"},{"i":6,"n":"第六条","txt":"理事会是航运交易所的权力机构。"},{"i":7,"n":"第七条","txt":"理事会行使下列职权："},{"i":8,"n":"第八条","txt":"理事会会议由理事长召集；理事长因故不能召集会议时，由其指定的副理事长代为召集。"},{"i":9,"n":"第九条","txt":"航运交易所设总裁一人、副总裁若干人。"},{"i":10,"n":"第十条","txt":"取得会员资格，应当具备下列条件："},{"i":11,"n":"第十一条","txt":"申请取得会员资格，应当经航运交易所审查批准，并按照航运交易所章程办理入会手续。"},{"i":12,"n":"第十二条","txt":"会员分为正式会员和临时会员。"},{"i":13,"n":"第十三条","txt":"会员享有下列权利："},{"i":14,"n":"第十四条","txt":"会员应当履行下列义务："},{"i":15,"n":"第十五条","txt":"会员可以通过会员会议对航运交易所的工作提出批评和建议。"},{"i":16,"n":"第十六条","txt":"会员在航运交易所内从事交易的人员为出市代表，出市代表须经航运交易所培训。"},{"i":17,"n":"第十七条","txt":"航运交易所的交易范围："},{"i":18,"n":"第十八条","txt":"会员的出市代表，只能代表本企业进行交易；但是，从事水路货物运输代理业务、船舶代理业务的会员除外。"},{"i":19,"n":"第十九条","txt":"非会员企业可以委托从事水路货物运输代理或者船舶代理业务的会员代表本企业进场交易。"},{"i":20,"n":"第二十条","txt":"会员不得有下列行为："},{"i":21,"n":"第二十一条","txt":"以竞价方式进行交易和以协商方式进行船舶买卖交易的，交易双方应当向航运交易所提供信用保证。"},{"i":22,"n":"第二十二条","txt":"从事国际班轮运输的会员应当将本企业的运价报航运交易所备案。"},{"i":23,"n":"第二十三条","txt":"交易双方成交后，应当向航运交易所缴纳手续费。"},{"i":24,"n":"第二十四条","txt":"除国家另有规定外，航运交易所内的交易价格由交易双方自主决定。"},{"i":25,"n":"第二十五条","txt":"航运交易所应当及时、准确地向会员发布航运交易信息。"},{"i":26,"n":"第二十六条","txt":"航运交易所工作人员应当廉洁自律、奉公守法，不得以任何方式从航运交易所会员或者其他有关单位获取利益，不得泄露内幕信息。"},{"i":27,"n":"第二十七条","txt":"因突发事件导致航运交易所停市时，理事会应当及时向上海市人民政府和国务院交通主管部门报告。"},{"i":28,"n":"第二十八条","txt":"会员和出市代表违反本规定、航运交易所章程和交易规则的，航运交易所有权责令当事人停止违法行为，并可以视情节给予警告、暂停进场交易或者取消会员资格的处理。"},{"i":29,"n":"第二十九条","txt":"交易双方在交易过程中发生争议，可以自行协商解决或者申请航运交易所调解，也可以依照有关法律、行政法规的规定申请仲裁或者提起诉讼。"},{"i":30,"n":"第三十条","txt":"会员有本规定第二十条第（一）、（二）项所列行为之一的，由上海市人民政府交通主管部门根据不同情况给予警告、没收违法所得；情节严重的，并处2万元以下的罚款。"},{"i":31,"n":"第三十一条","txt":"违反本规定第二十二条规定，不将运价报备案或者不执行报备案的运价的，由上海市人民政府交通主管部门根据情节给予警告、责令停开航线，处5万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"航运交易所违反本规定，接收不符合会员条件的企业入会的，随意开除会员的，或者明知会员超经营范围从事交易而不予制止的，由国务院交通主管部门给予警告；情节严重的，处2万元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"航运交易所违反本规定第十七条规定，擅自扩大交易范围的，由国务院交通主管部门给予警告；情节严重的，处5万元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"航运交易所违反本规定第二十七条规定，停市时不报告的，由国务院交通主管部门处2万元以下的罚款。"},{"i":35,"n":"第三十五条","txt":"航运交易所违反本规定，给会员造成经济损失的，应当依法承担赔偿责任。"},{"i":36,"n":"第三十六条","txt":"本规定自发布之日起施行。"}],"gerencunkuanzhanghushimingzhiguiding":[{"i":1,"n":"第一条","txt":"为了保证个人存款账户的真实性，维护存款人的合法权益，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的金融机构和在金融机构开立个人存款账户的个人，应当遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定所称金融机构，是指在境内依法设立和经营个人存款业务的机构。"},{"i":4,"n":"第四条","txt":"本规定所称个人存款账户，是指个人在金融机构开立的人民币、外币存款账户，包括活期存款账户、定期存款账户、定活两便存款账户、通知存款账户以及其他形式的个人存款账户。"},{"i":5,"n":"第五条","txt":"本规定所称实名，是指符合法律、行政法规和国家有关规定的身份证件上使用的姓名。"},{"i":6,"n":"第六条","txt":"个人在金融机构开立个人存款账户时，应当出示本人身份证件，使用实名。"},{"i":7,"n":"第七条","txt":"在金融机构开立个人存款账户的，金融机构应当要求其出示本人身份证件，进行核对，并登记其身份证件上的姓名和号码。代理他人在金融机构开立个人存款账户的，金融机构应当要求其出示被代理人和代理人的身份证件，进行核对，并登记被代理人和代理人的身份证件上的姓名和号码。"},{"i":8,"n":"第八条","txt":"金融机构及其工作人员负有为个人存款账户的情况保守秘密的责任。"},{"i":9,"n":"第九条","txt":"金融机构违反本规定第七条规定的，由中国人民银行给予警告，可以处1000元以上5000元以下的罚款；情节严重的，可以并处责令停业整顿，对直接负责的主管人员和其他直接责任人员依法给予纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":10,"n":"第十条","txt":"本规定施行前，已经在金融机构开立的个人存款账户，按照本规定施行前国家有关规定执行；本规定施行后，在原账户办理第一笔个人存款时，原账户没有使用实名的，应当依照本规定使用实名。"},{"i":11,"n":"第十一条","txt":"本规定由中国人民银行组织实施。"},{"i":12,"n":"第十二条","txt":"本规定自2000年4月1日起施行。"}],"guowuyuanguanyuguanliwaiguoqiyechangzhudaibiaojigo589073":[{"i":1,"n":"第一条","txt":"为了有利于发展国际经济贸易交往，管理外国公司、企业和其它经济组织（以下简称外国企业）常驻中国的代表机构，特制订本规定。"},{"i":2,"n":"第二条","txt":"外国企业确有需要在中国设立常驻代表机构的，必须提出申请，经过批准，办理登记手续。"},{"i":3,"n":"第三条","txt":"外国企业申请在中国设立常驻代表机构时，应当提交以下证件和材料："},{"i":4,"n":"第四条","txt":"外国企业设立常驻代表机构的申请，分别由下列机关批准："},{"i":5,"n":"第五条","txt":"外国企业设立常驻代表机构的申请获得批准后，应当在批准之日起的三十天内，持批准证件向中华人民共和国工商行政管理总局办理登记手续，填写登记表，缴纳登记费，领取登记证。逾期没有办理登记手续的，应当缴回原批准证件。"},{"i":6,"n":"第六条","txt":"常驻代表机构按照第四条规定获得批准后，其人员和家属应当持批准证件向当地公安机关申请办理居留手续，领取居留证件。"},{"i":7,"n":"第七条","txt":"常驻代表机构要求变更机构名称、负责人员、业务范围、驻在期限、驻在地点时，应当向原批准机关提出申请，获得批准后，持批准证件向中华人民共和国工商行政管理总局办理变更登记手续，缴纳变更登记费，并向当地公安机关申请办理居留证件的变更手续。"},{"i":8,"n":"第八条","txt":"常驻代表机构应当持登记证，按照中国银行的有关规定，在中国银行或者中国银行指定的银行开立帐户。"},{"i":9,"n":"第九条","txt":"常驻代表机构及其人员，应当遵照中国税法规定，向当地税务机关办理纳税登记手续，照章纳税。"},{"i":10,"n":"第十条","txt":"常驻代表机构及其人员进口所需要的办公、生活用品和交通工具，应当向中国海关申报，并照章缴纳关税和工商统一税。"},{"i":11,"n":"第十一条","txt":"常驻代表机构租用房屋、聘请工作人员，应当委托当地外事服务单位或者中国政府指定的其它单位办理。"},{"i":12,"n":"第十二条","txt":"中华人民共和国政府依法保护常驻代表机构及其人员的合法权益，并对其正常业务活动提供方便。"},{"i":13,"n":"第十三条","txt":"常驻代表机构不得在中国境内架设电台。对于业务需要的商业性电信线路、通信设备等，应当向当地电信局申请租用。"},{"i":14,"n":"第十四条","txt":"常驻代表机构的人员及其家属在中国的一切活动和进出中国国境，都应当遵守中国的法律、法令和有关规定。"},{"i":15,"n":"第十五条","txt":"常驻代表机构及其人员违反本规定或者有其它违法活动，中国有关主管机关有权进行检查和依法处理。"},{"i":16,"n":"第十六条","txt":"常驻代表机构驻在期限届满或者提前终止业务活动，应当在终止业务活动的三十天前以书面通知原批准机关，并于债务、税务和其它有关事宜清理完毕后，向原发登记证机关办理注销登记，缴销登记证。"},{"i":17,"n":"第十七条","txt":"已经批准设立的常驻代表机构，应当在本规定公布之日起的三十天内，持批准证件，向中华人民共和国工商行政管理总局补办登记手续。"},{"i":18,"n":"第十八条","txt":"本规定未尽事宜，应当根据中国有关法律、法令和规定办理。"},{"i":19,"n":"第十九条","txt":"外国企业在中国设立常驻代表，都比照设立常驻代表机构，适用本规定。"},{"i":20,"n":"第二十条","txt":"本规定自公布之日起施行。"}],"guojihuowuyunshudailiyeguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范国际货物运输代理行为，保障进出口货物收货人、发货人和国际货物运输代理企业的合法权益，促进对外贸易的发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国际货物运输代理业，是指接受进出口货物收货人、发货人的委托，以委托人的名义或者以自己的名义，为委托人办理国际货物运输及相关业务并收取服务报酬的行业。"},{"i":3,"n":"第三条","txt":"国际货物运输代理企业必须依法取得中华人民共和国企业法人资格。"},{"i":4,"n":"第四条","txt":"国务院对外贸易经济合作主管部门负责对全国的国际货物运输代理业实施监督管理。"},{"i":5,"n":"第五条","txt":"对国际货物运输代理业实施监督管理，应当遵循下列原则："},{"i":6,"n":"第六条","txt":"从事国际货物运输代理业务的企业，应当遵守中华人民共和国的法律、行政法规、接受有关行业主管机关依照有关法律、行政法规规定实施的监督管理。"},{"i":7,"n":"第七条","txt":"设立国际货物运输代理企业，根据其行业特点，应当具备下列条件："},{"i":8,"n":"第八条","txt":"国际货物运输代理企业的注册资本最低限额应当符合下列要求："},{"i":9,"n":"第九条","txt":"申请设立国际货物运输代理企业，申请人应当向拟设立国际货物运输代理企业所在地的地方对外贸易主管部门提出申请，由地方对外贸易主管部门提出意见后，转报国务院对外贸易经济合作主管部门审查批准。"},{"i":10,"n":"第十条","txt":"申请设立国际货物运输代理企业，应当报送下列文件："},{"i":11,"n":"第十一条","txt":"地方对外贸易主管部门应当自收到申请设立国际货物运输代理企业的申请书和其他文件之日起45天内提出意见，并转报国务院对外贸易经济合作主管部门。"},{"i":12,"n":"第十二条","txt":"国际货物运输代理企业应当凭国务院对外贸易经济合作主管部门颁发的批准证书，依照有关法律、行政法规的规定，办理企业登记、税务登记手续。"},{"i":13,"n":"第十三条","txt":"申请人自收到批准证书之日起180天内无正当理由未开始营业的，国务院对外贸易经济合作主管部门应当撤销批准证书。"},{"i":14,"n":"第十四条","txt":"批准证书的有效期为3年。"},{"i":15,"n":"第十五条","txt":"国际货物运输代理企业终止营业，应当依照本规定第九条规定的设立申请批准程序，报告所在地的地方对外贸易主管部门或者国务院对外贸易经济合作主管部门并缴销批准证书。"},{"i":16,"n":"第十六条","txt":"国际货物运输代理企业申请设立从事国际货物运输代理业务的分支机构，应当依照本章规定的程序办理。"},{"i":17,"n":"第十七条","txt":"国际货物运输代理企业可以接受委托，代为办理下列部分或者全部业务："},{"i":18,"n":"第十八条","txt":"国际货物运输代理企业应当遵循安全、迅速、准确、节省、方便的经营方针，为进出口货物的收货人、发货人提供服务。"},{"i":19,"n":"第十九条","txt":"国际货物运输代理企业，必须依照国家有关规定确定收费标准，并在其营业地点予以公布。"},{"i":20,"n":"第二十条","txt":"国际货物运输代理企业从事国际货物运输代理业务，必须使用经税务机关核准的发票。"},{"i":21,"n":"第二十一条","txt":"国际货物运输代理企业应当于每年3月底前，向其所在地的地方对外贸易主管部门报送上一年度的经营情况资料。"},{"i":22,"n":"第二十二条","txt":"国际货物运输代理企业不得有下列行为："},{"i":23,"n":"第二十三条","txt":"国际货物运输代理企业违反本规定第十九条、第二十一条规定的，由国务院对外贸易经济合作主管部门予以警告并责令限期改正；未在限期内改正的，可以撤销其批准证书。"},{"i":24,"n":"第二十四条","txt":"国际货物运输代理企业违反本规定第十七条第二款、第二十条、第二十二条规定的，由国务院对外贸易经济合作主管部门予以警告、责令停业整顿直至撤销其批准证书；工商行政管理、海关、税务等有关主管机关并可依照有关法律、行政法规的规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"违反本规定的规定，擅自从事本规定第十七条规定的国际货物运输代理业务的，由国务院对外贸易经济合作主管部门取缔非法经营活动，并由工商行政管理机关依照有关法律、行政法规的规定予以处罚。"},{"i":26,"n":"第二十六条","txt":"违反本规定，构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"国际货物运输代理企业可以依法设立国际货物运输代理业协会，协会依照其章程对会员进行协调指导，提供服务。"},{"i":28,"n":"第二十八条","txt":"本规定自发布之日起施行。"}],"jingneiwaiguorenzongjiaohuodongguanliguiding":[{"i":1,"n":"第一条","txt":"为了保障中华人民共和国境内外国人的宗教信仰自由，维护社会公共利益，根据宪法，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国尊重在中国境内的外国人的宗教信仰自由，保护外国人在宗教方面同中国宗教界进行的友好往来和文化学术交流活动。"},{"i":3,"n":"第三条","txt":"外国人可以在中国境内的寺院、宫观、清真寺、教堂等宗教活动场所参加宗教活动。经省、自治区、直辖市以上宗教团体的邀请，外国人可以在中国宗教活动场所讲经、讲道。"},{"i":4,"n":"第四条","txt":"外国人可以在县级以上人民政府宗教事务部门认可的场所举行外国人参加的宗教活动。"},{"i":5,"n":"第五条","txt":"外国人在中国境内，可以邀请中国宗教教职人员为其举行洗礼、婚礼、葬礼和道场法会等宗教仪式。"},{"i":6,"n":"第六条","txt":"外国人进入中国国境，可以携带本人自用的宗教印刷品、宗教音像制品和其他宗教用品；携带超出本人自用的宗教印刷品、宗教音像制品和其他宗教用品入境，按照中国海关的有关规定办理。"},{"i":7,"n":"第七条","txt":"外国人在中国境内招收为培养宗教教职人员的留学人员或者到中国宗教院校留学和讲学，按照中国的有关规定办理。"},{"i":8,"n":"第八条","txt":"外国人在中国境内进行宗教活动，应当遵守中国的法律、法规，不得在中国境内成立宗教组织、设立宗教办事机构、设立宗教活动场所或者开办宗教院校，不得在中国公民中发展教徒、委任宗教教职人员和进行其他传教活动。"},{"i":9,"n":"第九条","txt":"外国人违反本规定进行宗教活动的，县级以上人民政府宗教事务部门和其他有关部门应当予以劝阻、制止；构成违反外国人入境出境管理行为或者治安管理行为的，由公安机关依法进行处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":10,"n":"第十条","txt":"外国组织在中华人民共和国境内的宗教活动适用本规定。"},{"i":11,"n":"第十一条","txt":"侨居国外的中国公民在中国境内，台湾居民在大陆，香港、澳门居民在内地进行宗教活动，参照本规定执行。"},{"i":12,"n":"第十二条","txt":"本规定由国务院宗教事务部门负责解释。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。"}],"waiguojichuanbohangxingchangjiangshuiyuguanliguidi158cbf":[{"i":1,"n":"第一条","txt":"长江是中华人民共和国内河。为维护中华人民共和国主权，保障船舶安全，维持长江水域及其港口秩序，依据《中华人民共和国对外国籍船舶管理规则》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国长江水域及其港口航行、停泊的外国籍机动船、非机动船和其他水上运输工具（以下简称船舶），必须遵守本规定和中华人民共和国的一切有关法律、行政法规和规章。"},{"i":3,"n":"第三条","txt":"本规定所称长江水域，是指浏河口下游的浏黑屋（北纬31°30′、东经121°18′）与崇明岛施翘河口下游的施信杆（北纬31°37′、东经121°22′）联线沿长江向上至长江中游的北岸窑咀（北纬29°29′、东经113°6′）与南岸七洲（北纬29°28′、东经113°6′）联线及洞庭湖口湘江的南岸七里山（北纬29°24′、东经113°7′）与北岸芦席洲（北纬29°25′、东经113°6′）联线之间的干线水域。"},{"i":4,"n":"第四条","txt":"本规定由中华人民共和国港务监督负责实施，任何船舶都必须接受港务监督的监督管理。"},{"i":5,"n":"第五条","txt":"船舶进入长江水域及其港口，必须经中华人民共和国港务监督批准。"},{"i":6,"n":"第六条","txt":"进入长江水域的船舶，不得经营沿长江各港口之间以及长江各港口与上海港之间的运输或者其他未经批准的业务。"},{"i":7,"n":"第七条","txt":"进入长江港口的船舶，必须遵守下列规定："},{"i":8,"n":"第八条","txt":"船舶在长江水域及其港口航行或移泊，必须向中华人民共和国长江港口港务监督申请指派引航员引航；途经上海港水域必须向中华人民共和国上海港务监督申请指派引航员引航。"},{"i":9,"n":"第九条","txt":"船舶抵港后，应即呈报进口报告书及其他有关表报，同时交验船舶证书及有关文件，并接受检查。船舶出港前，应当通过外轮代理公司向港务监督预报开航时间、驶往港等情况，并办理出口手续，取得出口许可证后，方可出港。"},{"i":10,"n":"第十条","txt":"船舶在长江水域及其港口航行、停泊，白天应当在前桅顶部悬挂中华人民共和国国旗，船尾悬挂船籍国国旗，有引航员在船时应当加挂“H”旗。进出港口或在港内移泊，应当加挂船名呼号旗和其他规定的信号。"},{"i":11,"n":"第十一条","txt":"船舶在长江水域及其港口使用甚高频无线电话，按《中华人民共和国交通部关于外轮使用甚高频无线电话暂行办法》办理。"},{"i":12,"n":"第十二条","txt":"船舶的无线电报、无线电话发射机，在长江水域期间只准与中华人民共和国江岸、海岸电台通讯；在港口期间只有在危急情况下才可以使用，并且使用后必须向港务监督报告。"},{"i":13,"n":"第十三条","txt":"船舶在长江水域及其港口航行、停泊时，禁止进行下列活动："},{"i":14,"n":"第十四条","txt":"船舶在长江水域航行，如遇恶劣气象、洪峰等特殊情况需要临时停泊，应当尽量靠航道一侧的边缘停泊，不得占用主航道，并应及时向就近港务监督报告抛锚时间、位置和驶离时间，未经当地公安部门批准，船上的人员不得登陆。"},{"i":15,"n":"第十五条","txt":"船舶不得以危及其他船舶和两岸设施安全的速度航行。"},{"i":16,"n":"第十六条","txt":"船舶在长江水域及其港口期间，有关航行、停泊和避让事宜，按照中华人民共和国交通部颁布的《内河避碰规则》执行。"},{"i":17,"n":"第十七条","txt":"船舶使用信号应当遵守中华人民共和国交通部颁布的《内河避碰规则》和其他有关信号的规定；未作规定的依照有关国际信号规则办理。"},{"i":18,"n":"第十八条","txt":"船舶在长江水域及其港口期间，不得任意排放和抛弃油类、油性混合物，以及其他污染物质和废弃物。"},{"i":19,"n":"第十九条","txt":"本规定已列事项按照本规定执行；未列事项按照《中华人民共和国对外国籍船舶管理规则》及其他有关规定执行。"},{"i":20,"n":"第二十条","txt":"本规定自发布之日起施行。"}],"souxunyuanjiuminyonghangkongqiguiding":[{"i":1,"n":"第一条","txt":"为了及时有效地搜寻援救遇到紧急情况的民用航空器，避免或者减少人员伤亡和财产损失，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国领域内以及中华人民共和国缔结或者参加的国际条约规定由中国承担搜寻援救工作的公海区域内搜寻援救民用航空器的活动。"},{"i":3,"n":"第三条","txt":"海上搜寻援救民用航空器，除适用本规定外，并应当遵守国务院有关海上搜寻援救的规定。"},{"i":4,"n":"第四条","txt":"搜寻援救民用航空器按照下列规定分工负责："},{"i":5,"n":"第五条","txt":"民航局搜寻援救协调中心和地区管理局搜寻援救协调中心承担陆上搜寻援救民用航空器的协调工作。"},{"i":6,"n":"第六条","txt":"中华人民共和国领域内以及中华人民共和国缔结或者参加的国际条约规定由中国承担搜寻援救工作的公海区域内为中华人民共和国民用航空搜寻援救区，该区域内划分若干地区民用航空搜寻援救区，具体地区划分范围由民航局公布。"},{"i":7,"n":"第七条","txt":"使用航空器执行搜寻援救任务，以民用航空力量为主，民用航空搜寻援救力量不足的，由军队派出航空器给予支援。"},{"i":8,"n":"第八条","txt":"为执行搜寻援救民用航空器的紧急任务，有关地方、部门、单位和人员必须积极行动，互相配合，努力完成任务；对执行搜寻援救任务成绩突出的单位和个人，由其上级机关给予奖励。"},{"i":9,"n":"第九条","txt":"各地区管理局应当拟定在陆上使用航空器搜寻援救民用航空器的方案，经民航局批准后，报有关省、自治区、直辖市人民政府备案。"},{"i":10,"n":"第十条","txt":"沿海省、自治区、直辖市海上搜寻援救组织，应当拟定在海上使用船舶、航空器搜寻援救民用航空器的方案，经国家海上搜寻援救组织批准后，报省、自治区、直辖市人民政府和民航局备案，同时抄送有关地区管理局。"},{"i":11,"n":"第十一条","txt":"搜寻援救民用航空器方案应当包括下列内容："},{"i":12,"n":"第十二条","txt":"地区管理局和沿海省、自治区、直辖市海上搜寻援救组织应当按照批准的方案定期组织演习。"},{"i":13,"n":"第十三条","txt":"搜寻援救民用航空器的通信联络，应当符合下列规定："},{"i":14,"n":"第十四条","txt":"地区管理局搜寻援救协调中心应当同有关省、自治区、直辖市海上搜寻援救组织建立直接的通信联络。"},{"i":15,"n":"第十五条","txt":"向遇险待救人员空投救生物品，由执行搜寻援救任务的单位按照下列规定负责准备："},{"i":16,"n":"第十六条","txt":"发现或者收听到民用航空器遇到紧急情况的单位或者个人，应当立即通知有关地区管理局搜寻援救协调中心；发现失事的民用航空器，其位置在陆地的，并应当同时通知当地政府；其位置在海上的，并应当同时通知当地海上搜寻援救组织。"},{"i":17,"n":"第十七条","txt":"地区管理局搜寻援救协调中心收到民用航空器紧急情况的信息后，必须立即做出判断，分别按照本规定第十九条、第二十条、第二十一条的规定，采取搜寻援救措施，并及时向民航局搜寻援救协调中心以及有关单位报告或者通报。"},{"i":18,"n":"第十八条","txt":"本规定所指民用航空器的紧急情况分为以下三个阶段："},{"i":19,"n":"第十九条","txt":"对情况不明阶段的民用航空器，地区管理局搜寻援救协调中心应当："},{"i":20,"n":"第二十条","txt":"对告警阶段的民用航空器，地区管理局搜寻援救协调中心应当："},{"i":21,"n":"第二十一条","txt":"对遇险阶段的民用航空器，地区管理局搜寻援救协调中心应当："},{"i":22,"n":"第二十二条","txt":"省、自治区、直辖市人民政府或者沿海省、自治区、直辖市海上搜寻援救组织收到关于民用航空器迫降或者失事的报告或者通报后，应当立即组织有关方面和当地驻军进行搜寻援救，并指派现场负责人。"},{"i":23,"n":"第二十三条","txt":"现场负责人的主要职责是："},{"i":24,"n":"第二十四条","txt":"指派的现场负责人未到达现场的，由第一个到达现场的援救单位的有关人员担任现场临时负责人，行使本规定第二十三条规定的职责，并负责向到达后的现场负责人移交工作。"},{"i":25,"n":"第二十五条","txt":"对处于紧急情况下的民用航空器，地区管理局搜寻援救协调中心应当设法将已经采取的援救措施通报该民用航空器机组。"},{"i":26,"n":"第二十六条","txt":"执行搜寻援救任务的航空器与船舶、遇险待救人员、搜寻援救工作组之间，应当使用无线电进行联络。条件不具备或者无线电联络失效的，应当依照本规定附录规定的国际通用的《搜寻援救的信号》进行联络。"},{"i":27,"n":"第二十七条","txt":"民用航空器的紧急情况已经不存在或者可以结束搜寻援救工作的，地区管理局搜寻援救协调中心应当按照规定程序及时向有关单位发出解除紧急情况的通知。"},{"i":28,"n":"第二十八条","txt":"对违反本规定，有下列行为之一的人员，由其所在单位或者上级机关给予行政处分；构成犯罪的，依法追究刑事责任："},{"i":29,"n":"第二十九条","txt":"航空器执行搜寻援救任务所需经费，国家可以给予一定补贴。具体补贴办法由有关部门会同财政部门协商解决。"},{"i":30,"n":"第三十条","txt":"本规定由民航局负责解释。"},{"i":31,"n":"第三十一条","txt":"本规定自发布之日起施行。"}],"wuxiandianguanzhiguiding":[{"i":1,"n":"第一条","txt":"为了保障无线电管制的有效实施，维护国家安全和社会公共利益，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称无线电管制，是指在特定时间和特定区域内，依法采取限制或者禁止无线电台（站）、无线电发射设备和辐射无线电波的非无线电设备的使用，以及对特定的无线电频率实施技术阻断等措施，对无线电波的发射、辐射和传播实施的强制性管理。"},{"i":3,"n":"第三条","txt":"根据维护国家安全、保障国家重大任务、处置重大突发事件等需要，国家可以实施无线电管制。"},{"i":4,"n":"第四条","txt":"实施无线电管制，应当遵循科学筹划、合理实施的原则，最大限度地减轻无线电管制对国民经济和人民群众生产生活造成的影响。"},{"i":5,"n":"第五条","txt":"国家无线电管理机构和军队电磁频谱管理机构，应当根据无线电管制需要，会同国务院有关部门，制定全国范围的无线电管制预案，报国务院和中央军事委员会批准。"},{"i":6,"n":"第六条","txt":"决定实施无线电管制的机关应当在开始实施无线电管制10日前发布无线电管制命令，明确无线电管制的区域、对象、起止时间、频率范围以及其他有关要求。但是，紧急情况下需要立即实施无线电管制的除外。"},{"i":7,"n":"第七条","txt":"国务院和中央军事委员会决定在全国范围内或者跨省、自治区、直辖市实施无线电管制的，由国家无线电管理机构和军队电磁频谱管理机构会同国务院公安等有关部门组成无线电管制协调机构，负责无线电管制的组织、协调工作。"},{"i":8,"n":"第八条","txt":"无线电管制协调机构应当根据无线电管制命令发布无线电管制指令。"},{"i":9,"n":"第九条","txt":"实施无线电管制期间，无线电管制区域内拥有、使用或者管理无线电台（站）、无线电发射设备和辐射无线电波的非无线电设备的单位或者个人，应当服从无线电管制命令和无线电管制指令。"},{"i":10,"n":"第十条","txt":"实施无线电管制期间，有关地方人民政府，交通运输、铁路、广播电视、气象、渔业、通信、电力等部门和单位，军队、武装警察部队的有关单位，应当协助国家无线电管理机构和军队电磁频谱管理机构或者省、自治区、直辖市无线电管理机构和军区电磁频谱管理机构实施无线电管制。"},{"i":11,"n":"第十一条","txt":"无线电管制结束，决定实施无线电管制的机关应当及时发布无线电管制结束通告；无线电管制命令已经明确无线电管制终止时间的，可以不再发布无线电管制结束通告。"},{"i":12,"n":"第十二条","txt":"违反无线电管制命令和无线电管制指令的，由国家无线电管理机构或者省、自治区、直辖市无线电管理机构责令改正；拒不改正的，可以关闭、查封、暂扣或者拆除相关设备；情节严重的，吊销无线电台（站）执照和无线电频率使用许可证；违反治安管理规定的，由公安机关依法给予处罚。"},{"i":13,"n":"第十三条","txt":"本规定自2010年11月1日起施行。"}],"haishanghangxingjinggaohehangxingtonggaoguanliguid7aa700":[{"i":1,"n":"第一条","txt":"为了加强海上航行警告和航行通告的管理，保障船舶、设施的航行和作业安全，根据《中华人民共和国海上交通安全法》有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国沿海水域从事影响或者可能影响海上交通安全的各种活动的船舶、设施和人员，以及负责发布海上航行警告、航行通告的有关单位和人员。"},{"i":3,"n":"第三条","txt":"中华人民共和国港务监督机构（以下简称国家主管机关）主管全国海上航行警告和航行通告的统一发布工作。"},{"i":4,"n":"第四条","txt":"海上航行警告由国家主管机关或者其授权的机关以无线电报或者无线电话的形式发布。"},{"i":5,"n":"第五条","txt":"在中华人民共和国沿海水域从事下列活动，必须事先向所涉及的海区的区域主管机关申请发布海上航行警告、航行通告："},{"i":6,"n":"第六条","txt":"组织或者从事本规定第五条第一款所列各项活动的单位，应当在活动开始之日的七天前向该项活动所涉及海区的区域主管机关递交发布海上航行警告、航行通告的书面申请。但是，有特殊情况，经区域主管机关认定，需要立即发布海上航行警告、航行通告的除外。从事本规定第五条第一款第（九）项所列活动的，依照本规定第七条执行。"},{"i":7,"n":"第七条","txt":"船舶从事本规定第五条第（九）项所列活动的，应当在启拖开始之日的三天前向启拖地所在海区的区域主管机关递交发布海上航行警告、航行通告的书面申请。"},{"i":8,"n":"第八条","txt":"海上航行警告、航行通告发布后，申请人必须在国家主管机关或者区域主管机关核准的时间和区域内进行活动；需要变更活动时间或者改换活动区域的，应当依照本规定，重新申请发布海上航行警告、航行通告。"},{"i":9,"n":"第九条","txt":"船舶、设施在海上发现下列情形，应当尽快向就近的区域主管机关报告："},{"i":10,"n":"第十条","txt":"区域主管机关收到有碍海上航行安全的报告或者发布海上航行警告、航行通告的申请后，应当立即核实有关资料，根据实际需要和接收范围，决定发布海上航行警告、航通告。"},{"i":11,"n":"第十一条","txt":"区域主管机关对本管辖区域内的下列情形，应当发布海上航行警告、航行通告："},{"i":12,"n":"第十二条","txt":"国家主管机关或者区域主管机关在发布海上航行警告、航行通告以及收到本规定第九条规定的各项报告时，应当及时向海军航海保证部门提供有关资料并通报有关情况。"},{"i":13,"n":"第十三条","txt":"海岸电台负责并按照规定的时间、频率和要求播发海上航行警告。播发的程序和办法由国务院交通主管部门另行制定。"},{"i":14,"n":"第十四条","txt":"船舶、设施的有关人员必须按照规定抄收海岸电台播发的海上航行警告。"},{"i":15,"n":"第十五条","txt":"有关单位收到海上航行通告后，必须采取有效手段，及时通知所属船舶、设施。"},{"i":16,"n":"第十六条","txt":"对于执行本规定做出显著成绩的单位和个人，由国家主管机关或者区域主管机关给予奖励。"},{"i":17,"n":"第十七条","txt":"违反本规定第五条第一款、第八条规定的，由国家主管机关或者区域主管机关责令其停止活动，并可以处二千元以下罚款。"},{"i":18,"n":"第十八条","txt":"未依照本规定第六条、第七条规定的时间申请发布海上航行警告、航行通告的，国家主管机关或者区域主管机关可以给予警告，可以并处八百元以下罚款。"},{"i":19,"n":"第十九条","txt":"对违反本规定第十四条规定的责任人员，根据情节，国家主管机关或者区域主管机关可以给予警告、扣留职务证书或者吊销职务证书。"},{"i":20,"n":"第二十条","txt":"违反本规定，造成海上交通事故的，除依法承担民事赔偿责任外，国家主管机关或者区域主管机关可以根据情节给予罚款、扣留职务证书或者吊销职务证书；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"当事人对罚款、扣留职务证书或者吊销职务证书的处罚决定不服的，可以自接到处罚决定通知之日起十五日内向中华人民共和国港务监督机构申请复议，可也以直接向人民法院提起诉讼；期满不申请复议也不提起诉讼又不履行的，作出处罚决定的主管机关可以申请人民法院强制执行。"},{"i":22,"n":"第二十二条","txt":"在渔港水域内新建、改建、扩建各种设施或者进行其他施工作业，由渔政渔港监督管理机关根据本规定和国家其他有关规定发布海上航行通告。"},{"i":23,"n":"第二十三条","txt":"军事单位涉及海上航行警告、航行通告事宜的管理办法。根据《中华人民共和国海上交通安全法》有关规定，另行制定。"},{"i":24,"n":"第二十四条","txt":"本规定由交通部负责解释。"},{"i":25,"n":"第二十五条","txt":"本规定自一九九三年二月一日起施行。"}],"haiguanzongshuguanyuwaiguozhuzhongguoshiguanheshig68c76c":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国外交特权与豁免条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"外国驻中国使馆（以下简称使馆）运进运出公务用品，使馆人员运进运出自用物品，除有双边协议按协议执行外，应当按照本规定办理。"},{"i":3,"n":"第三条","txt":"使馆运进运出公务用品，外交代表以托运或者邮寄方式运进运出自用物品，应当书面向海关申报。"},{"i":4,"n":"第四条","txt":"使馆申报运进的公务用品和外交代表申报运进的自用物品，经海关审核在直接需用数量范围内的，予以免税。"},{"i":5,"n":"第五条","txt":"使馆和使馆人员不得携运中华人民共和国法律和规章禁止进出口的物品进出境。因特殊情况需要运进运出上述物品，必须事先得到中国政府有关部门的批准，并按中国政府有关规定办理。"},{"i":6,"n":"第六条","txt":"使馆和使馆人员申报属于中国法律和规章禁止进出口的物品，除经中国政府有关部门批准的以外，海关予以扣留，有关使馆或者使馆人员应当在90天内退运。逾期未退运的，由海关变价上缴国库。"},{"i":7,"n":"第七条","txt":"使馆和使馆人员免税运进的物品，不得转让。确有特殊原因需要转让的，必须报经海关批准。"},{"i":8,"n":"第八条","txt":"使馆发送或者收受的外交邮袋，海关予以免验放行。外交邮袋应予加封，附有可资识别的外部标记，并以装载外交文件或者公务用品为限。"},{"i":9,"n":"第九条","txt":"使馆的行政技术人员和服务人员，如非中国公民或者在中国的永久居留者，携运进境自用物品，包括到任后半年内运进安家物品，应当书面向海关申报。上述物品经海关审核在直接需用数量范围内（其中汽车每户限1辆）的，海关予以查验免税放行。申报携运出境的自用物品，海关予以审核查验放行。"},{"i":10,"n":"第十条","txt":"联合国及其专门机构和其他国际组织驻中国代表机构运进运出公务用品和邮袋，代表机构的代表、行政技术人员、服务人员和与其共同生活的配偶及未成年子女运进运出自用物品，海关根据中国已加入的有关国际公约和中国与有关国际组织签订的协议办理；遇有公约和协议未涉及的情况，参照本规定有关条款办理。"},{"i":11,"n":"第十一条","txt":"外国驻中国领事馆运进运出公务用品和领事邮袋，领事官员、领馆工作人员和与其共同生活的配偶及未成年子女运进运出自用物品，海关根据中国已加入的有关国际公约和中国与有关国家签订的协议办理；遇有公约和协议未涉及的情况，根据互惠的原则，参照本规定有关条款办理。"},{"i":12,"n":"第十二条","txt":"本规定自发布之日起施行。"}],"shewaihaiyangkexueyanjiuguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对在中华人民共和国管辖海域内进行涉外海洋科学研究活动的管理，促进海洋科学研究的国际交流与合作，维护国家安全和海洋权益，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国际组织、外国的组织和个人（以下简称外方）为和平目的，单独或者与中华人民共和国的组织（以下简称中方）合作，使用船舶或者其他运载工具、设施，在中华人民共和国内海、领海以及中华人民共和国管辖的其他海域内进行的对海洋环境和海洋资源等的调查研究活动。但是，海洋矿产资源（包括海洋石油资源）勘查、海洋渔业资源调查和国家重点保护的海洋野生动物考察等活动，适用中华人民共和国有关法律、行政法规的规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国国家海洋行政主管部门（以下简称国家海洋行政主管部门）及其派出机构或者其委托的机构，对在中华人民共和国管辖海域内进行的涉外海洋科学研究活动，依照本规定实施管理。"},{"i":4,"n":"第四条","txt":"在中华人民共和国内海、领海内，外方进行海洋科学研究活动，应当采用与中方合作的方式。在中华人民共和国管辖的其他海域内，外方可以单独或者与中方合作进行海洋科学研究活动。"},{"i":5,"n":"第五条","txt":"外方与中方合作进行海洋科学研究活动的，中方应当在海洋科学研究计划预定开始日期6个月前，向国家海洋行政主管部门提出书面申请，并按照规定提交海洋科学研究计划和其他有关说明材料。"},{"i":6,"n":"第六条","txt":"经批准进行涉外海洋科学研究活动的，申请人应当在各航次开始之日2个月前，将海上船只活动计划报国家海洋行政主管部门审批。国家海洋行政主管部门应当自收到海上船只活动计划之日起1个月内作出批准或者不批准的决定，并书面通知申请人，同时通报国务院有关部门。"},{"i":7,"n":"第七条","txt":"有关中外双方或者外方应当按照经批准的海洋科学研究计划和海上船只活动计划进行海洋科学研究活动；海洋科学研究计划或者海上船只活动计划在执行过程中需要作重大修改的，应当征得国家海洋行政主管部门同意。"},{"i":8,"n":"第八条","txt":"进行涉外海洋科学研究活动的，不得将有害物质引入海洋环境，不得擅自钻探或者使用炸药作业。"},{"i":9,"n":"第九条","txt":"中外合作使用外国籍调查船在中华人民共和国内海、领海内进行海洋科学研究活动的，作业船舶应当于格林威治时间每天00时和08时，向国家海洋行政主管部门报告船位及船舶活动情况。外方单独或者中外合作使用外国籍调查船在中华人民共和国管辖的其他海域内进行海洋科学研究活动的，作业船舶应当于格林威治时间每天02时，向国家海洋行政主管部门报告船位及船舶活动情况。"},{"i":10,"n":"第十条","txt":"中外合作在中华人民共和国内海、领海内进行海洋科学研究活动所获得的原始资料和样品，归中华人民共和国所有，参加合作研究的外方可以依照合同约定无偿使用。"},{"i":11,"n":"第十一条","txt":"外方单独或者中外合作进行的海洋科学研究活动结束后，所使用的外国籍调查船应当接受国家海洋行政主管部门或者其派出机构、其委托的机构检查。"},{"i":12,"n":"第十二条","txt":"中外合作进行的海洋科学研究活动结束后，中方应当将研究成果和资料目录抄报国家海洋行政主管部门和国务院有关部门。"},{"i":13,"n":"第十三条","txt":"违反本规定进行涉外海洋科学研究活动的，由国家海洋行政主管部门或者其派出机构、其委托的机构责令停止该项活动，可以没收违法活动器具、没收违法获得的资料和样品，可以单处或者并处5万元人民币以下的罚款。"},{"i":14,"n":"第十四条","txt":"中华人民共和国缔结或者参加的国际条约与本规定有不同规定的，适用该国际条约的规定；但是，中华人民共和国声明保留的条款除外。"},{"i":15,"n":"第十五条","txt":"本规定自1996年10月1日起施行。"}],"gangkoujianhaishanglvkeyunshupeichangzerenxianegui0cc8c5":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国海商法》第一百一十七条、第二百一十一条的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国港口之间海上旅客运输。"},{"i":3,"n":"第三条","txt":"承运人在每次海上旅客运输中的赔偿责任限额，按照下列规定执行："},{"i":4,"n":"第四条","txt":"海上旅客运输的旅客人身伤亡赔偿责任限制，按照4万元人民币乘以船舶证书规定的载客定额计算赔偿限额，但是最高不超过2100万元人民币。"},{"i":5,"n":"第五条","txt":"向外籍旅客、华侨和港、澳、台胞旅客给付的赔偿金，可以兑换成该外国或者地区的货币。其汇率按照赔偿金给付之日中华人民共和国外汇管理部门公布的外汇牌价确定。"},{"i":6,"n":"第六条","txt":"本规定由中华人民共和国交通部负责解释。"},{"i":7,"n":"第七条","txt":"本规定自一九九四年一月一日起施行。"}],"jisuanjixinxiwangluoguojilianwangguanlizanxingguid15cecf-2":[{"i":1,"n":"第一条","txt":"为了加强对计算机信息网络国际联网的管理，保障国际计算机信息交流的健康发展，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的计算机信息网络进行国际联网，应当依照本规定办理。"},{"i":3,"n":"第三条","txt":"本规定下列用语的含义是："},{"i":4,"n":"第四条","txt":"国家对国际联网实行统筹规划、统一标准、分级管理、促进发展的原则。"},{"i":5,"n":"第五条","txt":"国务院信息化工作领导小组（以下简称领导小组），负责协调、解决有关国际联网工作中的重大问题。"},{"i":6,"n":"第六条","txt":"计算机信息网络直接进行国际联网，必须使用国家公用电信网提供的国际出入口信道。"},{"i":7,"n":"第七条","txt":"已经建立的互联网络，根据国务院有关规定调整后，分别由国务院电信主管部门、教育行政部门和中国科学院管理。"},{"i":8,"n":"第八条","txt":"接入网络必须通过互联网络进行国际联网。"},{"i":9,"n":"第九条","txt":"从事国际联网经营活动的和从事非经营活动的接入单位都必须具备下列条件："},{"i":10,"n":"第十条","txt":"个人、法人和其他组织（以下统称用户）使用的计算机或者计算机信息网络，需要进行国际联网的，必须通过接入网络进行国际联网。"},{"i":11,"n":"第十一条","txt":"国际出入口信道提供单位、互联单位和接入单位，应当建立相应的网络管理中心，依照法律和国家有关规定加强对本单位及其用户的管理，做好网络信息安全管理工作，确保为用户提供良好、安全的服务。"},{"i":12,"n":"第十二条","txt":"互联单位与接入单位，应当负责本单位及其用户有关国际联网的技术培训和管理教育工作。"},{"i":13,"n":"第十三条","txt":"从事国际联网业务的单位和个人，应当遵守国家有关法律、行政法规，严格执行安全保密制度，不得利用国际联网从事危害国家安全、泄露国家秘密等违法犯罪活动，不得制作、查阅、复制和传播妨碍社会治安的信息和淫秽色情等信息。"},{"i":14,"n":"第十四条","txt":"违反本规定第六条、第八条和第十条的规定的，由公安机关责令停止联网，给予警告，可以并处15000元以下的罚款；有违法所得的，没收违法所得。"},{"i":15,"n":"第十五条","txt":"违反本规定，同时触犯其他有关法律、行政法规的，依照有关法律、行政法规的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"与台湾、香港、澳门地区的计算机信息网络的联网，参照本规定执行。"},{"i":17,"n":"第十七条","txt":"本规定自发布之日起施行。"}],"jisuanjixinxiwangluoguojilianwangguanlizanxingguid15cecf":[{"i":1,"n":"第一条","txt":"为了加强对计算机信息网络国际联网的管理，保障国际计算机信息交流的健康发展，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的计算机信息网络进行国际联网，应当依照本规定办理。"},{"i":3,"n":"第三条","txt":"本规定下列用语的含义是："},{"i":4,"n":"第四条","txt":"国家对国际联网实行统筹规划、统一标准、分级管理、促进发展的原则。"},{"i":5,"n":"第五条","txt":"国务院信息化工作领导小组（以下简称领导小组），负责协调、解决有关国际联网工作中的重大问题。"},{"i":6,"n":"第六条","txt":"计算机信息网络直接进行国际联网，必须使用国家公用电信网提供的国际出入口信道。"},{"i":7,"n":"第七条","txt":"已经建立的互联网络，根据国务院有关规定调整后，分别由国务院电信主管部门、教育行政部门和中国科学院管理。"},{"i":8,"n":"第八条","txt":"接入网络必须通过互联网络进行国际联网。"},{"i":9,"n":"第九条","txt":"从事国际联网经营活动的和从事非经营活动的接入单位都必须具备下列条件："},{"i":10,"n":"第十条","txt":"个人、法人和其他组织（以下统称用户）使用的计算机或者计算机信息网络，需要进行国际联网的，必须通过接入网络进行国际联网。"},{"i":11,"n":"第十一条","txt":"国际出入口信道提供单位、互联单位和接入单位，应当建立相应的网络管理中心，依照法律和国家有关规定加强对本单位及其用户的管理，做好网络信息安全管理工作，确保为用户提供良好、安全的服务。"},{"i":12,"n":"第十二条","txt":"互联单位与接入单位，应当负责本单位及其用户有关国际联网的技术培训和管理教育工作。"},{"i":13,"n":"第十三条","txt":"从事国际联网业务的单位和个人，应当遵守国家有关法律、行政法规，严格执行安全保密制度，不得利用国际联网从事危害国家安全、泄露国家秘密等违法犯罪活动，不得制作、查阅、复制和传播妨碍社会治安的信息和淫秽色情等信息。"},{"i":14,"n":"第十四条","txt":"违反本规定第六条、第八条和第十条的规定的，由公安机关责令停止联网，给予警告，可以并处15000元以下的罚款；有违法所得的，没收违法所得。"},{"i":15,"n":"第十五条","txt":"违反本规定，同时触犯其他有关法律、行政法规的，依照有关法律、行政法规的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"与台湾、香港、澳门地区的计算机信息网络的联网，参照本规定执行。"},{"i":17,"n":"第十七条","txt":"本规定自发布之日起施行。"}],"hulianwangpingtaiqiyesheshuixinxibaosongguiding":[{"i":1,"n":"第一条","txt":"为了规范互联网平台企业向税务机关报送平台内经营者和从业人员涉税信息，提升税收服务与管理效能，保护纳税人合法权益，营造公平统一的税收环境，促进平台经济规范健康发展，根据《中华人民共和国税收征收管理法》、《中华人民共和国电子商务法》，制定本规定。"},{"i":2,"n":"第二条","txt":"互联网平台企业应当依照本规定向其主管税务机关报送平台内经营者和从业人员的身份信息、收入信息等涉税信息。"},{"i":3,"n":"第三条","txt":"互联网平台企业应当自本规定施行之日起30日内或者自从事互联网经营业务之日起30日内向其主管税务机关报送平台域名、业务类型、相关运营主体的统一社会信用代码以及名称等信息。"},{"i":4,"n":"第四条","txt":"互联网平台企业应当于季度终了的次月内，按照国务院税务主管部门规定的身份信息、收入信息的具体类别和内容，向其主管税务机关报送平台内经营者和从业人员的身份信息以及上季度收入信息。"},{"i":5,"n":"第五条","txt":"互联网平台企业应当按照国务院税务主管部门规定的涉税信息报送的数据口径和标准，通过网络等方式报送涉税信息。"},{"i":6,"n":"第六条","txt":"互联网平台企业应当核验平台内经营者和从业人员涉税信息，对其真实性、准确性、完整性负责。税务机关可以根据税收监管需要，对互联网平台企业报送的涉税信息进行核查。互联网平台企业已对其报送的涉税信息尽到核验义务，因平台内经营者或者从业人员过错导致涉税信息不真实、不准确或者不完整的，不追究互联网平台企业责任。"},{"i":7,"n":"第七条","txt":"税务机关依法开展税务检查或者发现涉税风险时，可以要求互联网平台企业和相关方提供涉嫌违法的平台内经营者和从业人员的合同订单、交易明细、资金账户、物流等涉税信息，互联网平台企业和相关方应当按照税务机关要求的期限、方式和内容如实提供。"},{"i":8,"n":"第八条","txt":"工业和信息化、人力资源社会保障、交通运输、市场监管、网信等部门应当与税务机关加强涉税信息共享。通过信息共享能够获取的涉税信息，税务机关不得要求互联网平台企业重复报送。"},{"i":9,"n":"第九条","txt":"互联网平台企业应当依照法律、行政法规和国家有关规定，规范保存平台内经营者和从业人员涉税信息。"},{"i":10,"n":"第十条","txt":"互联网平台企业有下列行为之一的，由税务机关责令限期改正；逾期不改正的，处2万元以上10万元以下的罚款；情节严重的，责令停业整顿，并处10万元以上50万元以下的罚款："},{"i":11,"n":"第十一条","txt":"税务机关及其工作人员在互联网平台企业涉税信息报送管理工作中有违法行为的，依照有关法律、行政法规的规定追究法律责任。"},{"i":12,"n":"第十二条","txt":"平台内经营者和从业人员在本规定施行前的涉税信息，互联网平台企业不需要报送。"},{"i":13,"n":"第十三条","txt":"国务院税务主管部门根据本规定制定实施办法。"},{"i":14,"n":"第十四条","txt":"本规定自公布之日起施行。"}],"jiageweifaxingweixingzhengchufaguiding":[{"i":1,"n":"第一条","txt":"为了依法惩处价格违法行为，维护正常的价格秩序，保护消费者和经营者的合法权益，根据《中华人民共和国价格法》（以下简称价格法）的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上各级人民政府价格主管部门依法对价格活动进行监督检查，并决定对价格违法行为的行政处罚。"},{"i":3,"n":"第三条","txt":"价格违法行为的行政处罚由价格违法行为发生地的地方人民政府价格主管部门决定；国务院价格主管部门规定由其上级价格主管部门决定的，从其规定。"},{"i":4,"n":"第四条","txt":"经营者违反价格法第十四条的规定，有下列行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处10万元以上100万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照："},{"i":5,"n":"第五条","txt":"经营者违反价格法第十四条的规定，相互串通，操纵市场价格，造成商品价格较大幅度上涨的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处10万元以上100万元以下的罚款，情节较重的处100万元以上500万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。"},{"i":6,"n":"第六条","txt":"经营者违反价格法第十四条的规定，有下列推动商品价格过快、过高上涨行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处5万元以上50万元以下的罚款，情节较重的处50万元以上300万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照："},{"i":7,"n":"第七条","txt":"经营者违反价格法第十四条的规定，利用虚假的或者使人误解的价格手段，诱骗消费者或者其他经营者与其进行交易的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处5万元以上50万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。"},{"i":8,"n":"第八条","txt":"经营者违反价格法第十四条的规定，采取抬高等级或者压低等级等手段销售、收购商品或者提供服务，变相提高或者压低价格的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处2万元以上20万元以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。"},{"i":9,"n":"第九条","txt":"经营者不执行政府指导价、政府定价，有下列行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处5万元以上50万元以下的罚款，情节较重的处50万元以上200万元以下的罚款；情节严重的，责令停业整顿："},{"i":10,"n":"第十条","txt":"经营者不执行法定的价格干预措施、紧急措施，有下列行为之一的，责令改正，没收违法所得，并处违法所得5倍以下的罚款；没有违法所得的，处10万元以上100万元以下的罚款，情节较重的处100万元以上500万元以下的罚款；情节严重的，责令停业整顿："},{"i":11,"n":"第十一条","txt":"本规定第四条、第七条至第九条规定中经营者为个人的，对其没有违法所得的价格违法行为，可以处10万元以下的罚款。"},{"i":12,"n":"第十二条","txt":"经营者违反法律、法规的规定牟取暴利的，责令改正，没收违法所得，可以并处违法所得5倍以下的罚款；情节严重的，责令停业整顿，或者由工商行政管理机关吊销营业执照。"},{"i":13,"n":"第十三条","txt":"经营者违反明码标价规定，有下列行为之一的，责令改正，没收违法所得，可以并处5000元以下的罚款："},{"i":14,"n":"第十四条","txt":"拒绝提供价格监督检查所需资料或者提供虚假资料的，责令改正，给予警告；逾期不改正的，可以处10万元以下的罚款，对直接负责的主管人员和其他直接责任人员给予纪律处分。"},{"i":15,"n":"第十五条","txt":"政府价格主管部门进行价格监督检查时，发现经营者的违法行为同时具有下列三种情形的，可以依照价格法第三十四条第（三）项的规定责令其暂停相关营业："},{"i":16,"n":"第十六条","txt":"本规定第四条至第十三条规定中的违法所得，属于价格法第四十一条规定的消费者或者其他经营者多付价款的，责令经营者限期退还。难以查找多付价款的消费者或者其他经营者的，责令公告查找。"},{"i":17,"n":"第十七条","txt":"经营者有《中华人民共和国行政处罚法》第二十七条所列情形的，应当依法从轻或者减轻处罚。"},{"i":18,"n":"第十八条","txt":"本规定中以违法所得计算罚款数额的，违法所得无法确定时，按照没有违法所得的规定处罚。"},{"i":19,"n":"第十九条","txt":"有本规定所列价格违法行为严重扰乱市场秩序，构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"经营者对政府价格主管部门作出的处罚决定不服的，应当先依法申请行政复议；对行政复议决定不服的，可以依法向人民法院提起诉讼。"},{"i":21,"n":"第二十一条","txt":"逾期不缴纳罚款的，每日按罚款数额的3%加处罚款；逾期不缴纳违法所得的，每日按违法所得数额的2‰加处罚款。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人有本规定所列价格违法行为，情节严重，拒不改正的，政府价格主管部门除依照本规定给予处罚外，可以公告其价格违法行为，直至其改正。"},{"i":23,"n":"第二十三条","txt":"有关法律对价格法第十四条所列行为的处罚及处罚机关另有规定的，可以依照有关法律的规定执行。"},{"i":24,"n":"第二十四条","txt":"价格执法人员泄露国家秘密、经营者的商业秘密或者滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":25,"n":"第二十五条","txt":"本规定自公布之日起施行。"}],"qiyemingchengdengjiguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范企业名称登记管理，保护企业的合法权益，维护社会经济秩序，优化营商环境，制定本规定。"},{"i":2,"n":"第二条","txt":"县级以上人民政府市场监督管理部门（以下统称企业登记机关）负责中国境内设立企业的企业名称登记管理。"},{"i":3,"n":"第三条","txt":"企业登记机关应当不断提升企业名称登记管理规范化、便利化水平，为企业和群众提供高效、便捷的服务。"},{"i":4,"n":"第四条","txt":"企业只能登记一个企业名称，企业名称受法律保护。"},{"i":5,"n":"第五条","txt":"企业名称应当使用规范汉字。民族自治地方的企业名称可以同时使用本民族自治地方通用的民族文字。"},{"i":6,"n":"第六条","txt":"企业名称由行政区划名称、字号、行业或者经营特点、组织形式组成。跨省、自治区、直辖市经营的企业，其名称可以不含行政区划名称；跨行业综合经营的企业，其名称可以不含行业或者经营特点。"},{"i":7,"n":"第七条","txt":"企业名称中的行政区划名称应当是企业所在地的县级以上地方行政区划名称。市辖区名称在企业名称中使用时应当同时冠以其所属的设区的市的行政区划名称。开发区、垦区等区域名称在企业名称中使用时应当与行政区划名称连用，不得单独使用。"},{"i":8,"n":"第八条","txt":"企业名称中的字号应当由两个以上汉字组成。"},{"i":9,"n":"第九条","txt":"企业名称中的行业或者经营特点应当根据企业的主营业务和国民经济行业分类标准标明。国民经济行业分类标准中没有规定的，可以参照行业习惯或者专业文献等表述。"},{"i":10,"n":"第十条","txt":"企业应当根据其组织结构或者责任形式，依法在企业名称中标明组织形式。"},{"i":11,"n":"第十一条","txt":"企业名称不得有下列情形："},{"i":12,"n":"第十二条","txt":"企业名称冠以“中国”、“中华”、“中央”、“全国”、“国家”等字词，应当按照有关规定从严审核，并报国务院批准。国务院市场监督管理部门负责制定具体管理办法。"},{"i":13,"n":"第十三条","txt":"企业分支机构名称应当冠以其所从属企业的名称，并缀以“分公司”、“分厂”、“分店”等字词。境外企业分支机构还应当在名称中标明该企业的国籍及责任形式。"},{"i":14,"n":"第十四条","txt":"企业集团名称应当与控股企业名称的行政区划名称、字号、行业或者经营特点一致。控股企业可以在其名称的组织形式之前使用“集团”或者“（集团）”字样。"},{"i":15,"n":"第十五条","txt":"有投资关系或者经过授权的企业，其名称中可以含有另一个企业的名称或者其他法人、非法人组织的名称。"},{"i":16,"n":"第十六条","txt":"企业名称由申请人自主申报。"},{"i":17,"n":"第十七条","txt":"在同一企业登记机关，申请人拟定的企业名称中的字号不得与下列同行业或者不使用行业、经营特点表述的企业名称中的字号相同："},{"i":18,"n":"第十八条","txt":"企业登记机关对通过企业名称申报系统提交完成的企业名称予以保留，保留期为2个月。设立企业依法应当报经批准或者企业经营范围中有在登记前须经批准的项目的，保留期为1年。"},{"i":19,"n":"第十九条","txt":"企业名称转让或者授权他人使用的，相关企业应当依法通过国家企业信用信息公示系统向社会公示。"},{"i":20,"n":"第二十条","txt":"企业登记机关在办理企业登记时，发现企业名称不符合本规定的，不予登记并书面说明理由。"},{"i":21,"n":"第二十一条","txt":"企业认为其他企业名称侵犯本企业名称合法权益的，可以向人民法院起诉或者请求为涉嫌侵权企业办理登记的企业登记机关处理。"},{"i":22,"n":"第二十二条","txt":"利用企业名称实施不正当竞争等行为的，依照有关法律、行政法规的规定处理。"},{"i":23,"n":"第二十三条","txt":"使用企业名称应当遵守法律法规，诚实守信，不得损害他人合法权益。"},{"i":24,"n":"第二十四条","txt":"申请人登记或者使用企业名称违反本规定的，依照企业登记相关法律、行政法规的规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"农民专业合作社和个体工商户的名称登记管理，参照本规定执行。"},{"i":26,"n":"第二十六条","txt":"本规定自2021年3月1日起施行。"}],"baohuhaididianlanguiding":[],"gonganbuduibufendaojushixingguanzhidezanxingguidince8aa4":[{"i":1,"n":"第一条","txt":"为了保障公民人身安全，防止不法分子利用刀具作为凶器进行犯罪活动，特制订本规定。"},{"i":2,"n":"第二条","txt":"本规定所管制的刀具是：匕首、三棱刀（包括机械加工用的三棱刮刀）、带有自锁装置的弹簧刀（跳刀）以及其它相类似的单刃、双刃、三棱尖刀。"},{"i":3,"n":"第三条","txt":"匕首，除中国人民解放军和人民警察作为武器、警械配备的以外，专业狩猎人员和地质、勘探等野外作业人员必须持有的，须由县以上主管单位出具证明，经县以上公安机关批准，发给《匕首佩带证》，方准持有佩带。"},{"i":4,"n":"第四条","txt":"机械加工使用的三棱刮刀，只限工作人员在工作场所使用，不得随意带出工作场所。"},{"i":5,"n":"第五条","txt":"制造上述管制范围内刀具的工厂、作坊，必须经县、市以上主管部门审查同意和所在地县、市公安局批准，发给《特种刀具生产许可证》，方准生产。刀具样品及其说明（名称、规格、型号、用途、产量）须送所在地县、市公安局备案。产品须铸刻商标和号码（顺序号或批号）。"},{"i":6,"n":"第六条","txt":"经销上述管制范围内刀具的商店，必须经县、市以上主管部门审查同意和所在地县、市公安局批准。购销要建立登记制度，备公安机关检查。"},{"i":7,"n":"第七条","txt":"购买上述管制范围内刀具的单位和个人，必须符合第三、四条关于持有和使用的规定。军队和警察，由县、团以上单位凭上一级主管部门批准的函件，向指定单位定购。专业狩猎人员和地质、勘探等野外作业人员，由所属单位向所在地县、市公安局（公安分局）申请《特种刀具购买证》，凭证购买。三棱刮刀，凭单位介绍信向批准经销的商店购买。"},{"i":8,"n":"第八条","txt":"使用上述管制范围内刀具的单位，必须建立健全使用保管制度，加强刀具的管理和检查，确保安全。持有上述刀具的个人，对刀具应妥善保管，不得随意赠送、转借他人使用。发现丢失、被盗，要及时报告公安保卫部门。凡因保管不当，造成丢失、被盗，而酿成严重后果的，要追究有关人员和单位领导的责任。"},{"i":9,"n":"第九条","txt":"严禁任何单位和个人非法制造、销售和贩卖匕首、三棱刀、弹簧刀等属于管制范围内的各种刀具。严禁非法携带上述刀具进入车站、码头、机场、公园、商场、影剧院、展览馆或其它公共场所和乘坐火车、汽车、轮船、飞机。"},{"i":10,"n":"第十条","txt":"本规定下达后，凡制造、销售上述管制范围内各种刀具的单位和持有匕首的专业狩猎人员和地质、勘探等野外作业人员，须向公安机关补办登记许可手续。非因生产、工作需要持有上述刀具的，应一律自动送交当地公安机关。"},{"i":11,"n":"第十一条","txt":"《特种刀具生产许可证》、《匕道佩带证》和《特种刀具购买证》，样式由公安部统一规定，各省、市、自治区公安厅、局统一印制．"},{"i":12,"n":"第十二条","txt":"少数民族由于生活习惯需要佩带的刀具，由民族自治区制订办法管理。"},{"i":13,"n":"第十三条","txt":"违反本规定，非法制造、销售、携带和私自保存管制范围刀具的，公安机关应予取缔，没收其刀具，并按照《中华人民共和国治安管理处罚条例》有关条款予以治安处罚；有妨害公共安全行为，情节严重，触犯刑律的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"各省、市、自治区人民政府可根据本规定，制订具体管理办法，报公安部备案。"}],"guanyubuman300zongdunchuanbojiyanhaiyunshuyanhaizub6668b":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国海商法》第二百一十条规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于超过20总吨、不满300总吨的船舶及300总吨以上从事中华人民共和国港口之间货物运输或者沿海作业的船舶。"},{"i":3,"n":"第三条","txt":"除本规定第四条另有规定外，不满300总吨船舶的海事赔偿责任限制，依照下列规定计算赔偿限额："},{"i":4,"n":"第四条","txt":"从事中华人民共和国港口之间货物运输或者沿海作业的船舶，不满300总吨的，其海事赔偿限额依照本规定第三条规定的赔偿限额的50%计算；300总吨以上的，其海事赔偿限额依照《中华人民共和国海商法》第二百一十条第一款规定的赔偿限额的50%计算。"},{"i":5,"n":"第五条","txt":"同一事故中的当事船舶的海事赔偿限额，有适用《中华人民共和国海商法》第二百一十条或者本规定第三条规定的，其他当事船舶的海事赔偿限额应当同样适用。"},{"i":6,"n":"第六条","txt":"本规定由中华人民共和国交通部负责解释。"},{"i":7,"n":"第七条","txt":"本规定自一九九四年一月一日起施行。"}],"guanyujunminheyongjichangshiyongguanlideruoganzanxf42849":[{"i":1,"n":"第一条","txt":"为加强军民合用机场（以下简称机场）的统一使用管理，确保飞行安全，充分发挥现有机场的使用效率，从国家整体利益出发，既利于民用航空事业的发展，又保证军队战备、训练顺利进行，特制定本规定。"},{"i":2,"n":"第二条","txt":"机场的使用管理，原则上由机场产权单位负责，可根据双方需要和实际情况，划分区域，分区管理。场区建设，由产权单位统一规划，军民航专用设施应尽量分开修建，自成体系，自行管理。非产权单位在机场内（不含自征土地）修（扩）建永久性设施，应征得产权单位同意。非产权单位在机场内（不含自征土地）的一切固定建筑设施如不再使用时，可按质作价移交给机场产权单位使用（专用设备除外），但不得出租、转借或转让给与本场飞行业务无直接关系的单位。机场的土地属国家所有，由机场产权单位统一规划使用，任何单位不得擅自处理。"},{"i":3,"n":"第三条","txt":"机场允许起降的机型，应根据机场道面的承载能力，按国内有关规定并参照国际有关标准，由军民航双方商定。对符合条件的飞机，产权单位应允许使用。对超出道面承载能力的飞机，非紧急特殊情况，不准使用。"},{"i":4,"n":"第四条","txt":"机场场道的翻修和维护，原则上由产权单位负责。因超过道面承载能力或其它意外原因造成机场损坏，进行修复所需的经费、材料，由造成损坏的单位负责。"},{"i":5,"n":"第五条","txt":"机场扩建、翻修的设计和施工由产权单位统一规划，投资单位组织招标。机场扩建、翻修后，产权不变，但应保证投资单位使用，不收取场道工程折旧费。"},{"i":6,"n":"第六条","txt":"机场使用和管理细则，由产权单位牵头，与有关单位共同制定，各方均应严格遵守。"},{"i":7,"n":"第七条","txt":"军民双方应签订机场合用协议，明确合用项目、设施和规模等，实行经济核算，合理收费。收费的范围、标准、方法，由财政部、总后勤部联合制定。"},{"i":8,"n":"第八条","txt":"凡经批准开放的机场，可采用国际民航组织和国内现行标准所规定的地面导航标志和夜航灯光设施，由使用单位投资装设。"},{"i":9,"n":"第九条","txt":"凡需新辟军民合用机场，按国办发（1985）49号文件规定办理。"},{"i":10,"n":"第十条","txt":"本规定由总参谋部、国家经委负责解释。"},{"i":11,"n":"第十一条","txt":"本规定自发布之日起施行。"}],"guanyuguojiajiguangongzuorenyuanfulifeizhangguanshb4f71b":[],"guanyuwaiguorenzaiwoguolvxingguanlideguiding":[],"guanyushixingzhuanyejishuzhiwupinrenzhidudeguiding":[],"guanyugongzizongezuchengdeguiding":[{"i":1,"n":"第一条","txt":"为了统一工资总额的计算范围，保证国家对工资进行统一的统计核算和会计核算，有利于编制、检查计划和进行工资管理以及正确地反映职工的工资收入，制定本规定。"},{"i":2,"n":"第二条","txt":"全民所有制和集体所有制企业、事业单位，各种合营单位，各级国家机关、政党机关和社会团体，在计划、统计、会计上有关工资总额范围的计算，均应遵守本规定。"},{"i":3,"n":"第三条","txt":"工资总额是指各单位在一定时期内直接支付给本单位全部职工的劳动报酬总额。"},{"i":4,"n":"第四条","txt":"工资总额由下列6个部分组成："},{"i":5,"n":"第五条","txt":"计时工资是指按计时工资标准（包括地区生活费补贴）和工作时间支付给个人的劳动报酬。包括："},{"i":6,"n":"第六条","txt":"计件工资是指对已做工作按计件单价支付的劳动报酬。包括："},{"i":7,"n":"第七条","txt":"奖金是指支付给职工的超额劳动报酬和增收节支的劳动报酬。包括："},{"i":8,"n":"第八条","txt":"津贴和补贴是指为了补偿职工特殊或额外的劳动消耗和因其他特殊原因支付给职工的津贴，以及为了保证职工工资水平不受物价影响支付给职工的物价补贴。"},{"i":9,"n":"第九条","txt":"加班加点工资是指按规定支付的加班工资和加点工资。"},{"i":10,"n":"第十条","txt":"特殊情况下支付的工资。包括："},{"i":11,"n":"第十一条","txt":"下列各项不列入工资总额的范围："},{"i":12,"n":"第十二条","txt":"前条所列各项按照国家规定另行统计。"},{"i":13,"n":"第十三条","txt":"中华人民共和国境内的私营单位、华侨及港、澳、台工商业者经营单位和外商经营单位有关工资总额范围的计算，参照本规定执行。"},{"i":14,"n":"第十四条","txt":"本规定由国家统计局负责解释。"},{"i":15,"n":"第十五条","txt":"各地区、各部门可依据本规定制定有关工资总额组成的具体范围的规定。"},{"i":16,"n":"第十六条","txt":"本规定自发布之日起施行。国务院1955年5月21日批准颁发的《关于工资总额组成的暂行规定》同时废止。"}],"guanyutongjibaobiaoguanlidezanxingguiding":[],"guanyupiangouwaihuifeifataohuitaohuifeifamaimaiwaibdbe23":[{"i":1,"n":"第一条","txt":"为了维护国家外汇管理秩序，惩处违反外汇管理规定的行为，防范金融风险，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于国家公务员以及经批准经营外汇业务的金融机构、国有外经贸企业的工作人员。"},{"i":3,"n":"第三条","txt":"有本规定所列违反外汇管理规定的行为的，除依法给予行政处罚外，对有关责任人员依照本规定给予行政处分或者纪律处分；构成犯罪的，依法追究刑事责任。"},{"i":4,"n":"第四条","txt":"经批准经营外汇业务的金融机构、国有外经贸企业的工作人员，有下列骗购外汇行为之一，数额不满10万美元的，给予留用察看处分；数额在10万美元以上的，给予开除处分。"},{"i":5,"n":"第五条","txt":"经批准经营外汇业务的金融机构、国有外经贸企业的工作人员，有下列非法套汇行为之一，数额不满10万美元的，给予警告、记过或者记大过处分；数额在10万美元以上不满100万美元的，给予降级或者撤职处分；数额在100万美元以上的，给予留用察看或者开除处分。"},{"i":6,"n":"第六条","txt":"经批准经营外汇业务的金融机构、国有外经贸企业的工作人员，有下列逃汇行为之一，数额不满10万美元的，给予撤职处分；数额在10万美元以上不满100万美元的，给予留用察看处分；数额在100万美元以上的，给予开除处分。"},{"i":7,"n":"第七条","txt":"经批准经营外汇业务的金融机构、国有外经贸企业的工作人员，以营利为目的，在国家规定的交易场所以外非法买卖外汇，数额不满5万美元或者违法所得不满1万元人民币的，给予撤职处分；数额在5万美元以上不满10万美元或者违法所得在1万元人民币以上不满3万元人民币的，给予留用察看处分；数额在10万美元以上或者违法所得在3万元人民币以上的，给予开除处分。"},{"i":8,"n":"第八条","txt":"国有外经贸企业在代理进口业务中，因过失导致他人骗购外汇或者非法套汇，对负有直接责任的主管人员和其他直接责任人员给予纪律处分，数额不满10万美元的，给予警告、记过或者记大过处分；数额在10万美元以上不满100万美元的，给予降级或者撤职处分；数额在100万美元以上的，给予留用察看或者开除处分。"},{"i":9,"n":"第九条","txt":"经批准经营外汇业务的金融机构在办理结汇、售汇、付汇和开户业务中，因过失导致他人骗购外汇、非法套汇或者逃汇，对负有直接责任的主管人员和其他直接责任人员给予纪律处分，数额不满10万美元的，给予警告、记过或者记大过处分；数额在10万美元以上不满100万美元的，给予降级或者撤职处分；数额在100万美元以上的，给予留用察看或者开除处分。"},{"i":10,"n":"第十条","txt":"国家公务员有本规定所列骗购外汇、非法套汇、逃汇或者非法买卖外汇等违反外汇管理规定行为之一的，给予降级、撤职或者开除处分。"},{"i":11,"n":"第十一条","txt":"海关、外汇管理等部门的国家公务员与骗购外汇、非法套汇、逃汇或者非法买卖外汇的行为人通谋，为其提供便利，或者明知是伪造、变造的凭证和单据而为其提供服务，或者有其他滥用职权、徇私舞弊行为造成他人骗购外汇、非法套汇或者逃汇后果的，给予开除处分。"},{"i":12,"n":"第十二条","txt":"对本单位发生的违反外汇管理规定行为不制止、不查处，情节较重的，对负有直接责任的主管人员给予警告、记过或者记大过处分；情节严重的，给予降级或者撤职处分。"},{"i":13,"n":"第十三条","txt":"国家公务员利用职权，包庇违反外汇管理规定行为，或者有其他妨碍外汇管理执法监督、检查行为的，给予撤职或者开除处分。"},{"i":14,"n":"第十四条","txt":"主动交代违反外汇管理规定行为，并退出外汇和违法所得，或者主动采取措施避免损失，或者有立功表现的，可以从轻、减轻或者免予行政处分或者纪律处分。"},{"i":15,"n":"第十五条","txt":"自营进出口的国有事业单位及其工作人员有本规定所列违反外汇管理规定行为的，参照本规定执行。"},{"i":16,"n":"第十六条","txt":"本规定自发布之日起施行。1996年4月1日《中华人民共和国外汇管理条例》施行后、本规定施行前发生的违反外汇管理规定的行为，尚未处理的，适用本规定。"}],"zhizhimouqubaolidezanxingguiding":[{"i":1,"n":"第一条","txt":"为了维护社会主义市场经济秩序，制止牟取暴利，保护消费者的合法权益，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于对国民经济和社会发展有重大影响的和与居民生活有密切关系的商品和服务（以下简称商品和服务）。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事生产经营和提供有偿服务的公民、法人和其他组织（以下简称生产经营者）必须遵守本规定。"},{"i":4,"n":"第四条","txt":"生产经营者的价格行为应当遵循公开、公平和诚实信用的原则，执行国家关于商品和服务实行明码标价的规定。"},{"i":5,"n":"第五条","txt":"商品的价格和服务的收费标准（以下统称价格），应当符合下列要求："},{"i":6,"n":"第六条","txt":"商品或者服务的市场平均价格、平均差价率、平均利润率以其社会平均成本为基础测定。"},{"i":7,"n":"第七条","txt":"商品和服务的市场平均价格、平均差价率、平均利润率及其合理幅度，由省、自治区、直辖市的人民政府价格管理部门会同有关业务主管部门，按照国务院价格主管部门的规定测定和规定，并予以公布；省、自治区、直辖市人民政府价格管理部门也可以根据需要，授权市、县人民政府价格管理部门测定和规定与居民生活有密切关系的部分商品和服务的市场平均价格、平均差价率、平均利润率及其合理幅度，并予以公布。"},{"i":8,"n":"第八条","txt":"生产经营者不得违反本规定，以下列手段非法牟利："},{"i":9,"n":"第九条","txt":"价格监督检查人员依法执行职务，生产经营者不得拒绝、阻碍。"},{"i":10,"n":"第十条","txt":"对生产经营者牟取暴利的行为，任何单位和个人都有权向价格监督检查机构投诉或者举报。"},{"i":11,"n":"第十一条","txt":"违反本规定第五条规定的，由价格监督检查机构责令改正；拒不改正的，予以警告、没收违法所得，可以并处违法所得5倍以下的罚款。"},{"i":12,"n":"第十二条","txt":"违反本规定第八条规定的，由价格监督检查机构予以警告，责令其向遭受损害的一方退还违法所得，违法所得不能退还的，予以没收，可以并处违法所得5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"以暴力、威胁方法阻碍价格监督检查人员依法执行职务的，依法追究刑事责任；拒绝、阻碍价格监督检查人员依法执行职务，未使用暴力、威胁方法，构成违反治安管理行为的，由公安机关依照治安管理处罚法的有关规定予以处罚。"},{"i":14,"n":"第十四条","txt":"价格监督检查人员玩忽职守、徇私舞弊，或者包庇、纵容牟取暴利的行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"工商行政管理、审计、财政、税务、公安、技术监督等部门，应当在各自的职责范围内，配合价格监督检查机构查处牟取暴利的行为。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市人民政府，可以结合本地方的实际情况，根据本规定制定实施办法。"},{"i":17,"n":"第十七条","txt":"本规定由国务院价格主管部门组织实施。"},{"i":18,"n":"第十八条","txt":"本规定自发布之日起施行。"}],"jiaqiangduiwaihezuochubanguanlidezanxingguiding":[],"laodongjiuyefuwuqiyeguanliguiding":[{"i":1,"n":"第一条","txt":"为巩固和发展劳动就业服务企业，保障其合法权益，加强管理，促进城镇劳动就业工作的开展，制定本规定。"},{"i":2,"n":"第二条","txt":"劳动就业服务企业是承担安置城镇待业人员任务、由国家和社会扶持、进行生产经营自救的集体所有制经济组织。"},{"i":3,"n":"第三条","txt":"国家对劳动就业服务企业实行扶持政策，鼓励社会各方面依法扶持兴办各种形式的劳动就业服务企业。"},{"i":4,"n":"第四条","txt":"国家对劳动就业服务企业给予下列税收优惠："},{"i":5,"n":"第五条","txt":"国家在开办条件、物资供应、固定资产和流动资金贷款等方面对劳动就业服务企业予以支持和照顾。"},{"i":6,"n":"第六条","txt":"国家保护劳动就业服务企业的合法权益。禁止任何机关和单位非法改变劳动就业服务企业的集体所有制性质、干预企业自主权和向企业平调或者摊派人力、物力和财力。"},{"i":7,"n":"第七条","txt":"劳动就业服务企业必须贯彻执行国家的方针、政策和法律、法规，坚持社会主义方向，坚持以安置待业人员为主、安置效益和经济效益相结合的原则。"},{"i":8,"n":"第八条","txt":"开办劳动就业服务企业，须经审批机关批准，并经同级工商行政管理机关核准登记，领取《企业法人营业执照》或者《营业执照》后始得经营。"},{"i":9,"n":"第九条","txt":"各级人民政府的劳动部门对本地区劳动就业服务企业的职责是："},{"i":10,"n":"第十条","txt":"各行业主管部门对本部门劳动就业服务企业的职责是："},{"i":11,"n":"第十一条","txt":"企业、事业单位、机关、团体、部队等主办或者扶持单位（简称主办或者扶持单位，下同）对所主办或者扶持开办的劳动就业服务企业的职责是："},{"i":12,"n":"第十二条","txt":"主办或者扶持单位应当按照国家有关规定积极支持本单位职工到劳动就业服务企业担任生产经营和技术等方面的管理职务。"},{"i":13,"n":"第十三条","txt":"全民所有制的主办或者扶持单位的职工被劳动就业服务企业聘用后，仍保留其在原单位的全民所有制职工的身份和待遇。"},{"i":14,"n":"第十四条","txt":"主办或者扶持单位对支持劳动就业服务企业的资金、设备等，应当坚持有偿使用原则："},{"i":15,"n":"第十五条","txt":"劳动就业服务企业实行民主管理。除下列情况外，劳动就业服务企业的内部管理按国家有关城镇集体所有制企业的法律、法规的规定执行："},{"i":16,"n":"第十六条","txt":"劳动就业服务企业可以实行多种形式的生产经营责任制，但任何一种生产经营责任制均应当以安置待业人员作为责任制的一项重要内容。"},{"i":17,"n":"第十七条","txt":"劳动就业服务企业应当按照灵活方便、合同管理、骨干稳定、合理流动的原则，自主选择用工形式。"},{"i":18,"n":"第十八条","txt":"劳动就业服务企业根据自身情况可以有条件地适当安排全民所有制主办单位的富余人员在本企业就业。安置富余人员应当由劳动就业服务企业同全民所有制主办单位双方签订安置合同，合同内容由双方商定。"},{"i":19,"n":"第十九条","txt":"劳动就业服务企业可以根据国家有关规定和企业经济效益，自主地确定适合本企业具体情况的工资和奖金的分配形式和办法。"},{"i":20,"n":"第二十条","txt":"劳动就业服务企业对职工个人出资可以实行付息或者分红的办法。企业盈利，按一定比例付息或者分红；企业亏损，在弥补亏损之前，不得付息或者分红。付息或者分红的比例不得超过国家规定的最高限额。"},{"i":21,"n":"第二十一条","txt":"由待业人员自筹资金开办的劳动就业服务企业，在企业具备偿还能力时，可以逐步偿还个人出资。"},{"i":22,"n":"第二十二条","txt":"劳动就业服务企业应当建立养老保险制度并逐步建立待业保险制度。保险基金提取办法和保险项目按国家有关规定执行。"},{"i":23,"n":"第二十三条","txt":"劳动就业服务企业应当执行国家有关财务制度和财经纪律，健全财务管理，接受国家有关主管部门的指导和监督。"},{"i":24,"n":"第二十四条","txt":"违反本规定第八条的规定，以劳动就业服务企业名义进行活动的，由工商行政管理机关根据国家有关规定给予行政处罚。"},{"i":25,"n":"第二十五条","txt":"任何机关和单位违反本规定第六条的规定，非法改变劳动就业服务企业的集体所有制性质，干预企业自主权的，其上级主管部门应当予以纠正；向劳动就业服务企业平调或者摊派人力、物力、财力的，必须予以赔偿。对负有直接责任的主管人员和其他直接责任人员，由其主管部门根据情节轻重，给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"劳动就业服务企业违反本规定有关企业领导人员的产生、罢免程序规定的，其主管部门应当予以纠正，并追究直接责任人员的行政责任。"},{"i":27,"n":"第二十七条","txt":"除本规定有明文规定者外，劳动就业服务企业均应当执行国家有关城镇集体所有制企业的政策和法规。"},{"i":28,"n":"第二十八条","txt":"省、自治区、直辖市人民政府和国务院各行业主管部门可以根据本规定并结合本地区、本部门的具体情况制定实施办法。"},{"i":29,"n":"第二十九条","txt":"本规定由劳动部负责解释。"},{"i":30,"n":"第三十条","txt":"本规定从发布之日起施行。"}],"weixingdianshiguangbodimianjieshousheshiguanliguid83a4b0":[{"i":1,"n":"第一条","txt":"为了加强对卫星电视广播地面接收设施的管理，促进社会主义精神文明建设，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称卫星电视广播地面接收设施（以下简称卫星地面接收设施），是指接收卫星传送的电视节目的天线、高频头、接收机及编码、解码器等设施。"},{"i":3,"n":"第三条","txt":"国家对卫星地面接收设施的生产、进口、销售、安装和使用实行许可制度。"},{"i":4,"n":"第四条","txt":"工业产品生产许可证主管部门许可的生产企业，应当将卫星地面接收设施销售给依法设立的安装服务机构。其他任何单位和个人不得销售。"},{"i":5,"n":"第五条","txt":"进口卫星地面接收设施必须持国务院广播电视行政管理部门开具的证明，进口卫星地面接收设施的专用元部件必须持国务院电子工业行政部门开具的证明，到国务院机电产品进出口行政部门办理审批手续，海关凭审查批准文件放行。"},{"i":6,"n":"第六条","txt":"卫星地面接收设施的质量认证证书和认证标志，由国务院产品质量监督管理部门或者国务院产品质量监督管理部门授权的部门认可的认证机构按照有关质量认证的法律、法规的规定认证合格后发放；未经质量认证的，不得销售和使用。"},{"i":7,"n":"第七条","txt":"单位设置卫星地面接收设施的，必须向当地县、市人民政府广播电视行政管理部门提出申请，报省、自治区、直辖市人民政府广播电视行政管理部门审批，凭审批机关开具的证明购买卫星地面接收设施。卫星地面接收设施安装完毕，由审批机关发给《接收卫星传送的电视节目许可证》。"},{"i":8,"n":"第八条","txt":"个人不得安装和使用卫星地面接收设施。"},{"i":9,"n":"第九条","txt":"本规定发布前未经批准设置卫星地面接收设施的，必须自本规定发布之日起6个月内依照本规定办理审批手续。"},{"i":10,"n":"第十条","txt":"违反本规定，擅自生产卫星地面接收设施或者生产企业未按照规定销售给依法设立的安装服务机构的，由工业产品生产许可证主管部门责令停止生产、销售。"},{"i":11,"n":"第十一条","txt":"当事人对处罚决定不服的，可以依照有关法律、行政法规的规定，申请行政复议或者提起行政诉讼。"},{"i":12,"n":"第十二条","txt":"本规定的实施细则由国务院广播电视行政管理部门商有关行政部门制定。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。"}],"guowuyuanzhongyangjunweiguanyubaohutongxinxianlude5e4b18":[{"i":1,"n":"第一条","txt":"通信线路是国家通信网的重要组成部分，担负着党政军民的国内、国际通信任务，在社会主义现代化建设和巩固国防中起着重要作用，为使通信畅通无阻，必须确保通信线路安全。"},{"i":2,"n":"第二条","txt":"邮电、铁路、军队等部门的各种通信线路设备，都适用本规定。通信线路设备包括："},{"i":3,"n":"第三条","txt":"各级人民政府要加强对保护通信线路工作的领导，经常开展保护通信线路的宣传教育工作。必要时，应组织沿线各单位的治安保卫组织和民兵组织进行护线联防。"},{"i":4,"n":"第四条","txt":"各级通信部门及工作人员应加强对通信线路的维护管理，严格执行岗位责任制和各项规章制度，加强巡回检查，经常进行护线宣传，与沿线各单位密切联系，搞好护线联防，协助公安机关侦破破坏通信线路的案件。"},{"i":5,"n":"第五条","txt":"偷盗电杆、电线、电缆等通信线路设备或利用技术手段危害通信安全的，都是犯罪行为。公安、司法机关对反革命分子和其他刑事犯罪分子破坏通信线路的案件，应及时组织侦破，依法进行处理。"},{"i":6,"n":"第六条","txt":"废品回收部门应严格执行国务院一九八〇年275号文件精神，不得收购盗窃分子出售的通信线路器材。发现盗卖、变卖通信线路器材的非法行为或可疑线索，应及时向公安机关或通信部门报告。"},{"i":7,"n":"第七条","txt":"各单位和人民群众都不得损坏通信线路设备或有危害通信安全的行为。"},{"i":8,"n":"第八条","txt":"在通信线路沿线附近建筑施工、筑路、兴修水利、农田建设、植树造林、砍伐树竹、运输超高超大物件、架设线路、敷设管道和进行水下作业等，如有可能危及通信线路安全，应事先取得通信部门同意，并采取技术防范措施以后方可动工。"},{"i":9,"n":"第九条","txt":"通信线路的建设，应考虑线路的安全可靠、经济合理，尽量避免对现有建筑设施构成影响。凡在市、镇、县城和工矿区内新建通信线路，应纳入市镇管线综合规划，尽量和道路及其他管网同步建设。"},{"i":10,"n":"第十条","txt":"通信线路一般不得迁改。其他单位遇有特殊情况必须迁改通信线路时，应先经通信部门同意，迁改工程所需费用和材料由提出迁改的单位负责。"},{"i":11,"n":"第十一条","txt":"任何单位和个人，违反本规定，造成损坏线路、阻断通信的，应责令其承担修复线路的费用并赔偿阻断通信所造成的经济损失，直至依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"对保护通信线路、阻止损坏事故、协助侦破案件、抓获犯罪分子、追回被盗通信器材和协助抢修通信线路成绩显著的单位、集体和个人，由通信部门给予表彰或奖励。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。以前有关规定如与本规定有抵触，以本规定为准。"}],"guowuyuanguanyuchanyeliangongyingliananquandeguidi92bc91":[{"i":1,"n":"第一条","txt":"为了防范产业链供应链安全风险，提升产业链供应链韧性和安全水平，维护经济社会稳定和国家安全，根据《中华人民共和国国家安全法》、《中华人民共和国对外关系法》、《中华人民共和国反外国制裁法》、《中华人民共和国对外贸易法》等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"产业链供应链安全工作贯彻总体国家安全观，统筹发展和安全，统筹国内国际，推进高水平对外开放，促进全球产业链供应链稳定畅通。"},{"i":3,"n":"第三条","txt":"国家建立健全产业链供应链安全工作机制，统筹协调产业链供应链安全工作。"},{"i":4,"n":"第四条","txt":"国家引导产业链供应链合理有序布局，推进产业链供应链数字化、智能化，提升产业链供应链安全可控水平，促进产业链供应链高质量发展。"},{"i":5,"n":"第五条","txt":"国家坚持平等互利、合作共赢原则，加强产业链供应链领域国际合作，积极参与产业链供应链有关国际规则制定。"},{"i":6,"n":"第六条","txt":"国务院有关部门和省、自治区、直辖市人民政府在有关规划制定过程中，应当充分考虑可能对产业链供应链安全产生的影响。"},{"i":7,"n":"第七条","txt":"国家加强关键领域产业链供应链安全保障。国务院有关部门制定关键领域清单并实行动态调整，维护关键领域的原材料、技术、设备、产品等的生产与流通稳定、持续运行。"},{"i":8,"n":"第八条","txt":"国务院有关部门推动关键领域产业链供应链信息共享，强化信息平台支撑，引导行业、企业间加强关键领域产业链供应链信息互联互通，并采取有效措施保障数据安全。"},{"i":9,"n":"第九条","txt":"国家建立健全关键领域产业链供应链安全风险监测预警制度。国务院有关部门对关键领域的原材料、技术、设备、产品等供给渠道稳定情况及其对经济社会稳定和国家安全的影响等，组织开展评估监测，识别产业链供应链安全风险，及时发布预警信息。"},{"i":10,"n":"第十条","txt":"国家建立健全关键领域产业链供应链安全风险防范制度。国务院有关部门组织开展关键领域实物储备和能力储备，加大技术、设备、产品研发力度，提升关键领域产业链供应链抗风险能力。"},{"i":11,"n":"第十一条","txt":"国家建立健全关键领域产业链供应链安全应急管理制度，国务院有关部门制定应急工作预案。出现影响关键领域产业链供应链安全情形，危及经济社会稳定和国家安全的，经国务院或者国务院授权的部门决定，可以采取紧急调度、动用储备以及组织生产、运输、供应等应急处置措施。法律、行政法规另有规定的，依照其规定。"},{"i":12,"n":"第十二条","txt":"鼓励、引导社会资金投入，支持关键领域科学技术研发、核心技术攻关，促进科技成果转化。"},{"i":13,"n":"第十三条","txt":"任何组织、个人违反我国法律、行政法规、部门规章和国家有关规定，在我国境内开展与产业链供应链相关的调查等信息收集活动的，有关部门依法采取相应处理措施。"},{"i":14,"n":"第十四条","txt":"外国国家、地区和国际组织违反国际法和国际关系基本准则，在产业链供应链方面对我国采取歧视性禁止、限制或者其他类似措施，实施或者协助实施损害我国产业链供应链安全行为的，国务院有关部门有权对有关措施或者行为开展产业链供应链安全调查。"},{"i":15,"n":"第十五条","txt":"外国组织、个人违反正常的市场交易原则，中断与我国公民、组织的正常交易，对我国公民、组织采取歧视性措施或者实施其他行为，对我国产业链供应链安全造成实质损害或者产生实质损害威胁的，国务院有关部门有权开展产业链供应链安全调查。"},{"i":16,"n":"第十六条","txt":"我国境内的组织、个人应当执行国务院有关部门依照第十四条、第十五条规定采取的措施。"},{"i":17,"n":"第十七条","txt":"鼓励、支持律师事务所、公证机构等专业服务机构为我国公民、组织提供与产业链供应链安全有关的法律服务。"},{"i":18,"n":"第十八条","txt":"本规定自公布之日起施行。"}],"guowuyuanguanyuchujingrujingguanlideguiding":[{"i":1,"n":"第一条","txt":"为了规范出境入境管理，保障出境入境人员的合法权益，维护国家主权、安全、发展利益，根据《中华人民共和国出境入境管理法》等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"国家建立和完善中国公民出境安全风险防范制度。"},{"i":3,"n":"第三条","txt":"出境入境人员申请出境入境、停留居留的事由应当真实、合法。"},{"i":4,"n":"第四条","txt":"中国公民因骗取出境入境证件、非法出境入境受到行政拘留处罚的，移民管理机构可以根据违法情形和预防违法犯罪的需要，决定自处罚执行完毕之日起6个月至3年以内不准其出境。"},{"i":5,"n":"第五条","txt":"外国人在境外申请办理中国签证或者在口岸申请入境时提供虚假材料、作出虚假陈述的，移民管理机构、签证机关可以决定1年至5年以内不准其入境。"},{"i":6,"n":"第六条","txt":"对依法决定不准出境的人员，决定机关应当按照规定及时通知移民管理机构执行，并向当事人书面告知不准出境的事实、理由、依据和救济途径；有可能影响国家安全、刑事案件侦查等情形的，可以不告知当事人。"},{"i":7,"n":"第七条","txt":"国家对接受出境入境人员委托从事出境入境政策咨询、证件代办、手续办理等中介服务的机构和人员实行备案管理。"},{"i":8,"n":"第八条","txt":"从事出境入境中介服务的机构，应当具备下列条件："},{"i":9,"n":"第九条","txt":"移民管理机构应当会同同级外事、教育、司法行政、人力资源社会保障、商务、文化和旅游、市场监督管理等有关主管部门建立和完善监管制度，按照职责分工加强对从事出境入境中介服务的机构符合条件情况、经营活动等的监督管理，依法公布相关违法信息和不良记录。"},{"i":10,"n":"第十条","txt":"从事出境入境中介服务的机构不得有下列行为："},{"i":11,"n":"第十一条","txt":"通过提供虚假材料、作出虚假陈述等方式弄虚作假骗取签证、停留居留证件、护照等出境入境证件的，由移民管理机构依照《中华人民共和国出境入境管理法》、《中华人民共和国护照法》的规定予以处罚。"},{"i":12,"n":"第十二条","txt":"从事出境入境中介服务的机构违反本规定第七条、第八条规定的，由移民管理机构责令限期改正；拒不改正的，处5000元以上1万元以下罚款，并通报有关主管部门责令暂停相关业务或者停业整顿；情节严重的，处1万元以上5万元以下罚款，并通报有关主管部门吊销相关业务许可证或者吊销营业执照。"},{"i":13,"n":"第十三条","txt":"从事出境入境中介服务的机构违反本规定第十条规定，扰乱出境入境管理秩序的，由移民管理机构责令限期改正；有违法所得的，没收违法所得；违法所得2万元以上的，并处违法所得1倍以上5倍以下罚款；没有违法所得或者违法所得不足2万元的，并处2万元以上5万元以下罚款；拒不改正或者情节严重的，通报有关主管部门责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照；对直接负责的主管人员和其他直接责任人员处1万元以上5万元以下罚款。法律另有规定的，从其规定。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府公安机关出入境管理机构依照本规定处超过5000元罚款、没收违法所得的行政处罚，由其所属的公安机关决定。"},{"i":15,"n":"第十五条","txt":"国务院有关主管部门应当加强在出境入境人员合法权益保障、中国公民出境安全风险防范、出境入境中介服务管理等方面的工作协同。"},{"i":16,"n":"第十六条","txt":"移民管理机构应当畅通对违反出境入境管理行为的举报渠道，依法及时处理有关举报。对不属于本单位职责的举报，应当及时移送有关单位依法处理。"},{"i":17,"n":"第十七条","txt":"违反本规定，构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"本规定所称移民管理机构，是指国家移民管理部门和出入境边防检查机关、县级以上地方人民政府公安机关出入境管理机构。"},{"i":19,"n":"第十九条","txt":"本规定自2026年9月15日起施行。"}],"guowuyuanguanyujiaqiangshipindengchanpinanquanjianc3bacf":[{"i":1,"n":"第一条","txt":"为了加强食品等产品安全监督管理，进一步明确生产经营者、监督管理部门和地方人民政府的责任，加强各监督管理部门的协调、配合，保障人体健康和生命安全，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称产品除食品外，还包括食用农产品、药品等与人体健康和生命安全有关的产品。"},{"i":3,"n":"第三条","txt":"生产经营者应当对其生产、销售的产品安全负责，不得生产、销售不符合法定要求的产品。"},{"i":4,"n":"第四条","txt":"生产者生产产品所使用的原料、辅料、添加剂、农业投入品，应当符合法律、行政法规的规定和国家强制性标准。"},{"i":5,"n":"第五条","txt":"销售者必须建立并执行进货检查验收制度，审验供货商的经营资格，验明产品合格证明和产品标识，并建立产品进货台账，如实记录产品名称、规格、数量、供货商及其联系方式、进货时间等内容。从事产品批发业务的销售企业应当建立产品销售台账，如实记录批发的产品品种、规格、数量、流向等内容。在产品集中交易场所销售自制产品的生产企业应当比照从事产品批发业务的销售企业的规定，履行建立产品销售台账的义务。进货台账和销售台账保存期限不得少于2年。销售者应当向供货商按照产品生产批次索要符合法定条件的检验机构出具的检验报告或者由供货商签字或者盖章的检验报告复印件；不能提供检验报告或者检验报告复印件的产品，不得销售。"},{"i":6,"n":"第六条","txt":"产品集中交易市场的开办企业、产品经营柜台出租企业、产品展销会的举办企业，应当审查入场销售者的经营资格，明确入场销售者的产品安全管理责任，定期对入场销售者的经营环境、条件、内部安全管理制度和经营产品是否符合法定要求进行检查，发现销售不符合法定要求产品或者其他违法行为的，应当及时制止并立即报告所在地工商行政管理部门。"},{"i":7,"n":"第七条","txt":"出口产品的生产经营者应当保证其出口产品符合进口国（地区）的标准或者合同要求。法律规定产品必须经过检验方可出口的，应当经符合法律规定的机构检验合格。"},{"i":8,"n":"第八条","txt":"进口产品应当符合我国国家技术规范的强制性要求以及我国与出口国（地区）签订的协议规定的检验要求。"},{"i":9,"n":"第九条","txt":"生产企业发现其生产的产品存在安全隐患，可能对人体健康和生命安全造成损害的，应当向社会公布有关信息，通知销售者停止销售，告知消费者停止使用，主动召回产品，并向有关监督管理部门报告；销售者应当立即停止销售该产品。销售者发现其销售的产品存在安全隐患，可能对人体健康和生命安全造成损害的，应当立即停止销售该产品，通知生产企业或者供货商，并向有关监督管理部门报告。"},{"i":10,"n":"第十条","txt":"县级以上地方人民政府应当将产品安全监督管理纳入政府工作考核目标，对本行政区域内的产品安全监督管理负总责，统一领导、协调本行政区域内的监督管理工作，建立健全监督管理协调机制，加强对行政执法的协调、监督；统一领导、指挥产品安全突发事件应对工作，依法组织查处产品安全事故；建立监督管理责任制，对各监督管理部门进行评议、考核。质检、工商和药品等监督管理部门应当在所在地同级人民政府的统一协调下，依法做好产品安全监督管理工作。"},{"i":11,"n":"第十一条","txt":"国务院质检、卫生、农业等主管部门在各自职责范围内尽快制定、修改或者起草相关国家标准，加快建立统一管理、协调配套、符合实际、科学合理的产品标准体系。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府及其部门对产品安全实施监督管理，应当按照法定权限和程序履行职责，做到公开、公平、公正。对生产经营者同一违法行为，不得给予2次以上罚款的行政处罚；对涉嫌构成犯罪、依法需要追究刑事责任的，应当依照《行政执法机关移送涉嫌犯罪案件的规定》，向公安机关移送。"},{"i":13,"n":"第十三条","txt":"生产经营者有下列情形之一的，农业、卫生、质检、商务、工商、药品等监督管理部门应当依据各自职责采取措施，纠正违法行为，防止或者减少危害发生，并依照本规定予以处罚："},{"i":14,"n":"第十四条","txt":"农业、卫生、质检、商务、工商、药品等监督管理部门发现违反本规定的行为，属于其他监督管理部门职责的，应当立即书面通知并移交有权处理的监督管理部门处理。有权处理的部门应当立即处理，不得推诿；因不立即处理或者推诿造成后果的，由监察机关或者任免机关对其主要负责人、直接负责的主管人员和其他直接责任人员给予记大过或者降级的处分。"},{"i":15,"n":"第十五条","txt":"农业、卫生、质检、商务、工商、药品等监督管理部门履行各自产品安全监督管理职责，有下列职权："},{"i":16,"n":"第十六条","txt":"农业、卫生、质检、商务、工商、药品等监督管理部门应当建立生产经营者违法行为记录制度，对违法行为的情况予以记录并公布；对有多次违法行为记录的生产经营者，吊销许可证照。"},{"i":17,"n":"第十七条","txt":"检验检测机构出具虚假检验报告，造成严重后果的，由授予其资质的部门吊销其检验检测资质；构成犯罪的，对直接负责的主管人员和其他直接责任人员依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"发生产品安全事故或者其他对社会造成严重影响的产品安全事件时，农业、卫生、质检、商务、工商、药品等监督管理部门必须在各自职责范围内及时作出反应，采取措施，控制事态发展，减少损失，依照国务院规定发布信息，做好有关善后工作。"},{"i":19,"n":"第十九条","txt":"任何组织或者个人对违反本规定的行为有权举报。接到举报的部门应当为举报人保密。举报经调查属实的，受理举报的部门应当给予举报人奖励。"},{"i":20,"n":"第二十条","txt":"本规定自公布之日起施行。"}],"guowuyuanguanyukouankaifangderuoganguiding":[],"guowuyuanguanyuguojiaxingzhengjiguanheqiyeshiyedancc38af":[],"guowuyuanguanyuzaiduiwaigongwuhuodongzhongzengsong709ae6":[{"i":1,"n":"第一条","txt":"为了加强对国家行政机关工作人员在对外公务活动中赠送和接受礼品的管理，严肃外事纪律，保持清廉，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的礼品，是指礼物、礼金、有价证券。"},{"i":3,"n":"第三条","txt":"根据国际惯例和对外工作需要，必要时可以对外赠送礼物。礼物的金额标准另行规定。"},{"i":4,"n":"第四条","txt":"对外赠送礼物必须贯彻节约、从简的原则。礼物应当以具有民族特色的纪念品、传统手工艺品和实用物品为主。"},{"i":5,"n":"第五条","txt":"对来访的外宾，不主动赠送礼物。外宾向我方赠送礼物的，可以适当回赠礼物。"},{"i":6,"n":"第六条","txt":"对外赠送礼物或者回赠礼物，必须经国务院所属部门或者省、自治区、直辖市人民政府批准，或者由其授权的机关批准。审批时，应当从严掌握。"},{"i":7,"n":"第七条","txt":"在对外公务活动中接受的礼物，应当妥善处理。价值按我国市价折合人民币二百元以上的，自接受之日起（在国外接受礼物的，自回国之日起）一个月内填写礼品申报单并将应上缴的礼物上缴礼品管理部门或者受礼人所在单位；不满二百元的，归受礼人本人或者受礼人所在单位。"},{"i":8,"n":"第八条","txt":"在对外公务活动中，不得私相授受礼品，不得以明示或者暗示的方式索取礼品。"},{"i":9,"n":"第九条","txt":"国务院机关事务管理局负责保管、处理国务院各部门上缴的礼品。"},{"i":10,"n":"第十条","txt":"礼品管理部门及有关部门对于收缴的礼品，应当登记造册，妥善保管，及时处理。礼品保管部门应当每年向受礼单位通报礼品处理情况。受礼单位应当将礼品处理情况告知受礼人。"},{"i":11,"n":"第十一条","txt":"国家行政监察机关按照有关规定负责对对外赠送和接受礼品的情况进行监督、检查。"},{"i":12,"n":"第十二条","txt":"国家行政机关工作人员违反本规定的，对负直接责任的机关有关领导人和直接责任人，给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":13,"n":"第十三条","txt":"国家行政机关工作人员在公务活动中向华侨和香港、澳门、台湾地区的居民赠送礼品和接受其礼品，依照本规定执行。"},{"i":14,"n":"第十四条","txt":"本规定由国务院办公厅负责解释。"},{"i":15,"n":"第十五条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyuzaixianzhengwufuwuderuoganguiding":[{"i":1,"n":"第一条","txt":"为了全面提升政务服务规范化、便利化水平，为企业和群众（以下称行政相对人）提供高效、便捷的政务服务，优化营商环境，制定本规定。"},{"i":2,"n":"第二条","txt":"国家加快建设全国一体化在线政务服务平台（以下简称一体化在线平台），推进各地区、各部门政务服务平台规范化、标准化、集约化建设和互联互通，推动实现政务服务事项全国标准统一、全流程网上办理，促进政务服务跨地区、跨部门、跨层级数据共享和业务协同，并依托一体化在线平台推进政务服务线上线下深度融合。"},{"i":3,"n":"第三条","txt":"国务院办公厅负责牵头推进国家政务服务平台建设，推动建设一体化在线平台标准规范体系、安全保障体系和运营管理体系。"},{"i":4,"n":"第四条","txt":"除法律、法规另有规定或者涉及国家秘密等情形外，政务服务事项应当按照国务院确定的步骤，纳入一体化在线平台办理。"},{"i":5,"n":"第五条","txt":"国家政务服务平台基于自然人身份信息、法人单位信息等资源，建设全国统一身份认证系统，为各地区、各部门政务服务平台提供统一身份认证服务，实现一次认证、全网通办。"},{"i":6,"n":"第六条","txt":"行政机关和其他负有政务服务职责的机构（以下统称政务服务机构）应当按照规范化、标准化要求编制办事指南，明确政务服务事项的受理条件、办事材料、办理流程等信息。办事指南应当在政务服务平台公布。"},{"i":7,"n":"第七条","txt":"行政相对人在线办理政务服务事项，应当提交真实、有效的办事材料；政务服务机构通过数据共享能够获得的信息，不得要求行政相对人另行提供。"},{"i":8,"n":"第八条","txt":"政务服务中使用的符合《中华人民共和国电子签名法》规定条件的可靠的电子签名，与手写签名或者盖章具有同等法律效力。"},{"i":9,"n":"第九条","txt":"国家建立权威、规范、可信的统一电子印章系统。国务院有关部门、地方人民政府及其有关部门使用国家统一电子印章系统制发的电子印章。"},{"i":10,"n":"第十条","txt":"国家建立电子证照共享服务系统，实现电子证照跨地区、跨部门共享和全国范围内互信互认。"},{"i":11,"n":"第十一条","txt":"除法律、行政法规另有规定外，电子证照和加盖电子印章的电子材料可以作为办理政务服务事项的依据。"},{"i":12,"n":"第十二条","txt":"政务服务机构应当对履行职责过程中形成的电子文件进行规范管理，按照档案管理要求及时以电子形式归档并向档案部门移交。除法律、行政法规另有规定外，电子文件不再以纸质形式归档和移交。"},{"i":13,"n":"第十三条","txt":"电子签名、电子印章、电子证照以及政务服务数据安全涉及电子认证、密码应用的，按照法律、行政法规和国家有关规定执行。"},{"i":14,"n":"第十四条","txt":"政务服务机构及其工作人员泄露、出售或者非法向他人提供履行职责过程中知悉的个人信息、隐私和商业秘密，或者不依法履行职责，玩忽职守、滥用职权、徇私舞弊的，依法追究法律责任。"},{"i":15,"n":"第十五条","txt":"本规定下列用语的含义："},{"i":16,"n":"第十六条","txt":"本规定自公布之日起施行。"}],"guowuyuanguanyuzaixianggangtebiexingzhengqutongshi757909":[],"guowuyuanguanyuchuliguojiajiguangongzuorenyuantuiz149ae7":[],"guowuyuanguanyuduiwaitouzideguiding":[{"i":1,"n":"第一条","txt":"为了推进高水平对外开放，促进对外投资高质量发展，有效实施对外投资管理，保护投资者及其对外投资合法权益，维护国家主权、安全、发展利益，根据《中华人民共和国对外关系法》、《中华人民共和国对外贸易法》等法律，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内（以下简称中国境内）投资者对外投资，适用本规定。"},{"i":3,"n":"第三条","txt":"对外投资工作坚持对外开放的基本国策，贯彻总体国家安全观，统筹发展和安全，统筹国内国际，健全对外投资管理服务体系，提升对外投资质量与水平，促进开放合作、互利共赢。"},{"i":4,"n":"第四条","txt":"国家主动对接国际高标准经济贸易规则，推进高质量共建“一带一路”，推进多双边投资合作机制建设，积极参与国际投资规则制定，推动产业链供应链国际合作，反对单边主义和保护主义，推动建设开放型世界经济。"},{"i":5,"n":"第五条","txt":"国家支持投资者按照市场化原则开展对外投资活动，积极参与国际合作竞争。投资者依法享有对外投资自主权，自主决策、自担风险、自负盈亏。"},{"i":6,"n":"第六条","txt":"国家健全海外综合服务体系，促进贸易投资一体化，完善公共平台与服务，统筹外事、法律、财税、金融、经贸、物流、出境入境、海关、贸促等领域服务资源，为投资者提供服务保障。"},{"i":7,"n":"第七条","txt":"支持咨询评估、法律服务、会计审计、信用评级、调解仲裁、知识产权等专业服务机构拓展海外服务网络，提高国际化服务能力和水平，为投资者及其对外投资提供高质量专业服务。"},{"i":8,"n":"第八条","txt":"银行业金融机构应当立足职能定位，遵循市场化、法治化、商业可持续和风险可控原则，在业务范围内为投资者对外投资提供融资等金融服务。鼓励政策性保险机构为投资者对外投资提供海外投资保险等服务。"},{"i":9,"n":"第九条","txt":"有关行业协会商会应当依照法律、法规和章程，加强行业自律，提升服务投资者及其对外投资的能力和水平，及时反映行业诉求。"},{"i":10,"n":"第十条","txt":"国家健全对外投资管理体系，完善调控措施，分类分级实施全过程监管，加强风险防控，提高对外投资的科学性、安全性，推动投资便利化和有效防范风险相结合。"},{"i":11,"n":"第十一条","txt":"国务院投资主管部门、商务主管部门会同国务院其他有关部门根据国民经济和社会发展需要、有关国家（地区）投资环境变化和风险程度等，制定、调整和实施对外投资政策，明确鼓励、限制、禁止的对外投资，加强对外投资监管，指导、监督投资者规范投资经营行为。"},{"i":12,"n":"第十二条","txt":"投资者开展对外投资活动依法需要履行核准备案、信息报告、跨境资金登记等手续的，应当依照国家有关规定办理，如实提交有关材料，并配合有关主管部门的监督检查。"},{"i":13,"n":"第十三条","txt":"投资者开展对外投资活动，不得出口、使用国家禁止出口的货物、技术、服务及相关数据，或者未经许可出口、使用国家限制出口的货物、技术、服务及相关数据；不得以跨境派遣技术人员、组织人员赴其他国家（地区）工作、跨境提供技术指导、安排人员跨境培训等方式向其他国家（地区）转移国家禁止出口的货物、技术、服务及相关数据，或者未经许可向其他国家（地区）转移国家限制出口的货物、技术、服务及相关数据。"},{"i":14,"n":"第十四条","txt":"对外投资涉及资金汇兑、货物与技术进出口、跨境服务贸易、跨境数据流动、人员出境入境的管理以及经营者集中审查、出口管制、网络安全监管、税收征收管理、国有资产监管等，依照有关法律、行政法规和国家有关规定执行。"},{"i":15,"n":"第十五条","txt":"国家健全境外投资安全审查制度，国务院投资主管部门、商务主管部门会同国务院其他有关部门对影响或者可能影响国家安全的境外投资及相关资产、权益等的转让、处分进行安全审查。有关组织、个人应当予以协助、配合，不得拒绝、阻碍，并应当遵守境外投资安全审查决定。"},{"i":16,"n":"第十六条","txt":"投资者及其在其他国家（地区）投资的企业应当完善治理结构，建立健全合规经营、内部控制、安全生产、突发事件处置等制度，加强风险识别和防范处置，投入必要的人员、资金、设备等资源，保障其员工和资产安全。"},{"i":17,"n":"第十七条","txt":"投资者应当规范投资经营行为，不得损害其他投资者的商业信誉、商品声誉，侵犯他人商业秘密，没有正当理由低价倾销商品，通过贿赂、欺诈等手段牟取不正当利益，扰乱对外投资市场秩序。"},{"i":18,"n":"第十八条","txt":"国务院有关部门加强对外投资监测预警和风险评估，及时发布有关国家（地区）安全状况，提示投资风险，指导和帮助投资者做好安全风险防范，维护国家海外利益和投资者合法权益。"},{"i":19,"n":"第十九条","txt":"中华人民共和国根据缔结或者参加的国际条约、协定，或者按照平等互惠原则，与其他国家（地区）、国际组织等开展执法领域合作与交流，保护在其他国家（地区）的投资者及其投资的企业、项目所属员工和资产等的安全以及有关组织、个人的正当权益。"},{"i":20,"n":"第二十条","txt":"国家依法为在其他国家（地区）投资的中国公民、组织及其在该国家（地区）投资的企业、项目所属中国籍员工提供领事保护与协助，维护其正当权益。"},{"i":21,"n":"第二十一条","txt":"鼓励投资者通过协商、调解、仲裁、诉讼等多种方式化解对外投资有关矛盾纠纷，维护自身合法权益。"},{"i":22,"n":"第二十二条","txt":"中国境内组织、个人参与对外投资相关仲裁、诉讼或者受到境外司法、执法机构相关调查，需要向境外提供证据或者相关材料的，应当遵守保守国家秘密、数据安全、个人信息保护、技术出口管理、出口管制、司法协助等法律、行政法规和国家有关规定。依法须经主管机关准许的，应当履行相关法律程序。"},{"i":23,"n":"第二十三条","txt":"投资者在投资目的国家（地区）遭遇与贸易有关的投资壁垒或者其他投资经营障碍的，国务院商务主管部门可以自行或者会同国务院其他有关部门组织开展调查，有关组织、个人应当予以协助、配合。根据调查结果，国务院有关部门可以采取调整有关国别投资政策，禁止或者限制有关货物、技术进出口或者国际服务贸易等措施。"},{"i":24,"n":"第二十四条","txt":"任何国家（地区）、国际组织违反国际法和国际关系基本准则，在投资经营等方面对中华人民共和国采取歧视性禁止、限制或者其他类似措施，中国政府及其有关部门可以根据实际情况采取相应的措施，保护投资者及其对外投资的安全和正当权益，保护国家的海外利益不受威胁和侵害。"},{"i":25,"n":"第二十五条","txt":"外国组织、个人危害中国国家主权、安全、发展利益，违反正常的市场交易原则中断与中国企业、其他组织或者个人的正常交易，或者对投资者及其对外投资采取歧视性措施，不合理剥夺或者限制投资者及其对外投资正当权益的，国务院有关部门可以采取禁止或者限制其从事与我国有关的进出口活动，禁止或者限制其在中国境内投资，禁止或者限制中国境内的组织、个人与其进行有关交易、合作等活动，禁止或者限制相关人员、产品、交通运输工具等入境，取消或者限制相关人员在中国境内工作、停留或者居留资格等措施。有关措施可以适用于外国组织、个人实际控制或者参与设立、运营的组织。"},{"i":26,"n":"第二十六条","txt":"公职人员对在履行对外投资管理服务相关职责中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息等应当依法予以保密，不得泄露或者非法向他人提供。"},{"i":27,"n":"第二十七条","txt":"投资者投资国家禁止的对外投资的，由国务院投资主管部门、商务主管部门按照职责分工责令停止该投资活动，限期处分股份、资产，没收违法所得；拒不执行的，处投资额5‰以上10‰以下的罚款；对直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款。"},{"i":28,"n":"第二十八条","txt":"违反本规定第十五条规定，拒不配合境外投资安全审查，提供虚假材料或者隐瞒有关信息，或者不遵守境外投资安全审查决定的，由国务院有关部门责令改正，没收违法所得，处以罚款；危害国家安全的，责令其采取必要措施消除对国家安全的影响，可以禁止其在1年以上3年以下的期限内从事对外投资活动；已经投资的，可以责令其停止该投资活动，限期处分股份、资产。"},{"i":29,"n":"第二十九条","txt":"投资者违反本规定第十七条规定的，国务院投资主管部门、商务主管部门按照职责分工可以责令限期改正；造成危害后果的，可以禁止其在1年以上3年以下的期限内从事对外投资活动。"},{"i":30,"n":"第三十条","txt":"投资者开展对外投资活动，违反本规定，造成人身损害、财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"公职人员在对外投资工作中滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供所知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"对投资者在香港特别行政区、澳门特别行政区、台湾地区投资的管理，参照本规定执行；法律、行政法规或者国务院另有规定的，依照其规定。"},{"i":33,"n":"第三十三条","txt":"对投资者以自有资金、募集资金及其他受托资金在中国境外金融市场投资的管理，依照本规定和国家其他有关规定执行。"},{"i":34,"n":"第三十四条","txt":"本规定自2026年7月1日起施行。"}],"guowuyuanguanyushewaizhishichanquanjiufenchulidegue28cdd":[{"i":1,"n":"第一条","txt":"为了加强知识产权保护，促进公民、组织依法处理涉外知识产权纠纷，维护公民、组织的合法权益，推进高水平对外开放，推动经济高质量发展，制定本规定。"},{"i":2,"n":"第二条","txt":"国务院负责商标、专利、著作权等知识产权管理工作的部门（以下称知识产权管理部门）以及商务主管部门，加强对公民、组织处理涉外知识产权纠纷的指导和服务，国务院其他有关部门按照职责分工做好相关工作。"},{"i":3,"n":"第三条","txt":"县级以上地方人民政府及其有关部门结合本地区实际情况，做好涉外知识产权纠纷处理相关工作。"},{"i":4,"n":"第四条","txt":"国务院知识产权管理部门以及商务、司法行政等有关部门按照职责分工及时收集和发布国外知识产权法律制度信息，完善知识产权信息公共服务体系，为公众提供国外知识产权信息查询服务。"},{"i":5,"n":"第五条","txt":"国务院知识产权管理部门、商务主管部门按照职责分工对国外知识产权法律制度变化等重点信息加强跟踪了解，开展典型案例分析研究，及时发布风险提示，为公众提供涉外知识产权预警。"},{"i":6,"n":"第六条","txt":"国务院知识产权管理部门、商务主管部门按照职责分工健全涉外知识产权纠纷处理指导工作机构和工作规程，为公民、组织处理涉外知识产权纠纷提供应对指导和维权援助。"},{"i":7,"n":"第七条","txt":"支持商事调解组织、仲裁机构参与涉外知识产权纠纷解决，为公民、组织提供高效便捷的涉外知识产权纠纷解决途径，鼓励、引导公民、组织通过和解、调解、仲裁等方式快速解决涉外知识产权纠纷。"},{"i":8,"n":"第八条","txt":"鼓励律师事务所、知识产权服务机构等提高涉外知识产权服务能力，通过设立分支机构、联合经营等方式在国外设立执业机构，为公民、组织提供优质高效的涉外知识产权相关服务。"},{"i":9,"n":"第九条","txt":"支持企业设立涉外知识产权保护维权互助基金，鼓励保险机构按照市场化原则开展涉外知识产权相关保险业务，降低企业维权成本。"},{"i":10,"n":"第十条","txt":"鼓励商会、行业协会、跨境电商平台等组织搭建涉外知识产权维权援助平台，开通服务热线，提供咨询、培训等公益服务。"},{"i":11,"n":"第十一条","txt":"企业应当增强法治意识，建立健全内部规章制度，加强知识产权人才储备，强化知识产权保护和运用；进入国外市场，应当主动了解所在国家或者地区的法律制度、知识产权保护状况，依法开展生产经营活动，积极维护自身合法权益。"},{"i":12,"n":"第十二条","txt":"在我国境内送达文书、调查取证应当依照我国缔结或者参加的国际条约以及《中华人民共和国民事诉讼法》、《中华人民共和国国际刑事司法协助法》等法律规定办理。任何组织和个人均不得违反我国法律规定，在我国境内送达文书、调查取证。"},{"i":13,"n":"第十三条","txt":"我国境内的组织、个人参与境外知识产权相关诉讼或者受到境外司法或执法机构相关调查，需要向境外提供证据或者相关材料的，应当遵守保守国家秘密、数据安全、个人信息保护、技术出口管理、司法协助等法律、行政法规规定。依法须经主管机关准许的，应当履行相关法律程序。"},{"i":14,"n":"第十四条","txt":"国务院商务主管部门可以依照《中华人民共和国对外贸易法》对下列事项进行调查并采取必要的措施："},{"i":15,"n":"第十五条","txt":"外国国家违反国际法和国际关系基本准则，以知识产权纠纷为借口对我国进行遏制、打压，对我国公民、组织采取歧视性限制措施，干涉我国内政的，国务院有关部门可以依照《中华人民共和国对外关系法》、《中华人民共和国反外国制裁法》等法律将直接或者间接参与制定、决定、实施歧视性限制措施的组织、个人列入反制清单，采取相应反制和限制措施。"},{"i":16,"n":"第十六条","txt":"任何组织和个人均不得执行或者协助执行外国国家以知识产权纠纷为借口对我国公民、组织采取的歧视性限制措施。"},{"i":17,"n":"第十七条","txt":"国务院有关部门加强协调配合，对利用知识产权纠纷危害我国主权、安全、发展利益的，依照《中华人民共和国国家安全法》、《中华人民共和国对外关系法》、《中华人民共和国反外国制裁法》等法律采取相应措施；对滥用知识产权排除、限制竞争或者实施不正当竞争等行为的，依照《中华人民共和国反垄断法》、《中华人民共和国反不正当竞争法》等法律予以处理。"},{"i":18,"n":"第十八条","txt":"本规定自2025年5月1日起施行。"}],"guowuyuanguanyutedaanquanshiguxingzhengzerenzhuiji2a3c1e":[{"i":1,"n":"第一条","txt":"为了有效地防范特大安全事故的发生，严肃追究特大安全事故的行政责任，保障人民群众生命、财产安全，制定本规定。"},{"i":2,"n":"第二条","txt":"地方人民政府主要领导人和政府有关部门正职负责人对下列特大安全事故的防范、发生，依照法律、行政法规和本规定的规定有失职、渎职情形或者负有领导责任的，依照本规定给予行政处分；构成玩忽职守罪或者其他罪的，依法追究刑事责任："},{"i":3,"n":"第三条","txt":"特大安全事故的具体标准，按照国家有关规定执行。"},{"i":4,"n":"第四条","txt":"地方各级人民政府及政府有关部门应当依照有关法律、法规和规章的规定，采取行政措施，对本地区实施安全监督管理，保障本地区人民群众生命、财产安全，对本地区或者职责范围内防范特大安全事故的发生、特大安全事故发生后的迅速和妥善处理负责。"},{"i":5,"n":"第五条","txt":"地方各级人民政府应当每个季度至少召开一次防范特大安全事故工作会议，由政府主要领导人或者政府主要领导人委托政府分管领导人召集有关部门正职负责人参加，分析、布置、督促、检查本地区防范特大安全事故的工作。会议应当作出决定并形成纪要，会议确定的各项防范措施必须严格实施。"},{"i":6,"n":"第六条","txt":"市（地、州）、县（市、区）人民政府应当组织有关部门按照职责分工对本地区容易发生特大安全事故的单位、设施和场所安全事故的防范明确责任、采取措施，并组织有关部门对上述单位、设施和场所进行严格检查。"},{"i":7,"n":"第七条","txt":"市（地、州）、县（市、区）人民政府必须制定本地区特大安全事故应急处理预案。本地区特大安全事故应急处理预案经政府主要领导人签署后，报上一级人民政府备案。"},{"i":8,"n":"第八条","txt":"市（地、州）、县（市、区）人民政府应当组织有关部门对本规定第二条所列各类特大安全事故的隐患进行查处；发现特大安全事故隐患的，责令立即排除；特大安全事故隐患排除前或者排除过程中，无法保证安全的，责令暂时停产、停业或者停止使用。法律、行政法规对查处机关另有规定的，依照其规定。"},{"i":9,"n":"第九条","txt":"市（地、州）、县（市、区）人民政府及其有关部门对本地区存在的特大安全事故隐患，超出其管辖或者职责范围的，应当立即向有管辖权或者负有职责的上级人民政府或者政府有关部门报告；情况紧急的，可以立即采取包括责令暂时停产、停业在内的紧急措施，同时报告；有关上级人民政府或者政府有关部门接到报告后，应当立即组织查处。"},{"i":10,"n":"第十条","txt":"中小学校对学生进行劳动技能教育以及组织学生参加公益劳动等社会实践活动，必须确保学生安全。严禁以任何形式、名义组织学生从事接触易燃、易爆、有毒、有害等危险品的劳动或者其他危险性劳动。严禁将学校场地出租作为从事易燃、易爆、有毒、有害等危险品的生产、经营场所。"},{"i":11,"n":"第十一条","txt":"依法对涉及安全生产事项负责行政审批（包括批准、核准、许可、注册、认证、颁发证照、竣工验收等，下同）的政府部门或者机构，必须严格依照法律、法规和规章规定的安全条件和程序进行审查；不符合法律、法规和规章规定的安全条件的，不得批准；不符合法律、法规和规章规定的安全条件，弄虚作假，骗取批准或者勾结串通行政审批工作人员取得批准的，负责行政审批的政府部门或者机构除必须立即撤销原批准外，应当对弄虚作假骗取批准或者勾结串通行政审批工作人员的当事人依法给予行政处罚；构成行贿罪或者其他罪的，依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"对依照本规定第十一条第一款的规定取得批准的单位和个人，负责行政审批的政府部门或者机构必须对其实施严格监督检查；发现其不再具备安全条件的，必须立即撤销原批准。"},{"i":13,"n":"第十三条","txt":"对未依法取得批准，擅自从事有关活动的，负责行政审批的政府部门或者机构发现或者接到举报后，应当立即予以查封、取缔，并依法给予行政处罚；属于经营单位的，由工商行政管理部门依法相应吊销营业执照。"},{"i":14,"n":"第十四条","txt":"市（地、州）、县（市、区）人民政府依照本规定应当履行职责而未履行，或者未按照规定的职责和程序履行，本地区发生特大安全事故的，对政府主要领导人，根据情节轻重，给予降级或者撤职的行政处分；构成玩忽职守罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"发生特大安全事故，社会影响特别恶劣或者性质特别严重的，由国务院对负有领导责任的省长、自治区主席、直辖市市长和国务院有关部门正职负责人给予行政处分。"},{"i":16,"n":"第十六条","txt":"特大安全事故发生后，有关县（市、区）、市（地、州）和省、自治区、直辖市人民政府及政府有关部门应当按照国家规定的程序和时限立即上报，不得隐瞒不报、谎报或者拖延报告，并应当配合、协助事故调查，不得以任何方式阻碍、干涉事故调查。"},{"i":17,"n":"第十七条","txt":"特大安全事故发生后，有关地方人民政府应当迅速组织救助，有关部门应当服从指挥、调度，参加或者配合救助，将事故损失降到最低限度。"},{"i":18,"n":"第十八条","txt":"特大安全事故发生后，省、自治区、直辖市人民政府应当按照国家有关规定迅速、如实发布事故消息。"},{"i":19,"n":"第十九条","txt":"特大安全事故发生后，按照国家有关规定组织调查组对事故进行调查。事故调查工作应当自事故发生之日起60日内完成，并由调查组提出调查报告；遇有特殊情况的，经调查组提出并报国家安全生产监督管理机构批准后，可以适当延长时间。调查报告应当包括依照本规定对有关责任人员追究行政责任或者其他法律责任的意见。"},{"i":20,"n":"第二十条","txt":"地方人民政府或者政府部门阻挠、干涉对特大安全事故有关责任人员追究行政责任的，对该地方人民政府主要领导人或者政府部门正职负责人，根据情节轻重，给予降级或者撤职的行政处分。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人均有权向有关地方人民政府或者政府部门报告特大安全事故隐患，有权向上级人民政府或者政府部门举报地方人民政府或者政府部门不履行安全监督管理职责或者不按照规定履行职责的情况。接到报告或者举报的有关人民政府或者政府部门，应当立即组织对事故隐患进行查处，或者对举报的不履行、不按照规定履行安全监督管理职责的情况进行调查处理。"},{"i":22,"n":"第二十二条","txt":"监察机关依照行政监察法的规定，对地方各级人民政府和政府部门及其工作人员履行安全监督管理职责实施监察。"},{"i":23,"n":"第二十三条","txt":"对特大安全事故以外的其他安全事故的防范、发生追究行政责任的办法，由省、自治区、直辖市人民政府参照本规定制定。"},{"i":24,"n":"第二十四条","txt":"本规定自公布之日起施行。"}],"guowuyuanguanyujinzhizaishichangjingjihuodongzhong26bc2e":[{"i":1,"n":"第一条","txt":"为了建立和完善全国统一、公平竞争、规范有序的市场体系，禁止市场经济活动中的地区封锁行为，破除地方保护，维护社会主义市场经济秩序，制定本规定。"},{"i":2,"n":"第二条","txt":"各级人民政府及其所属部门负有消除地区封锁、保护公平竞争的责任，应当为建立和完善全国统一、公平竞争、规范有序的市场体系创造良好的环境和条件。"},{"i":3,"n":"第三条","txt":"禁止各种形式的地区封锁行为。"},{"i":4,"n":"第四条","txt":"地方各级人民政府及其所属部门（包括被授权或者委托行使行政权的组织，下同）不得违反法律、行政法规和国务院的规定，实行下列地区封锁行为："},{"i":5,"n":"第五条","txt":"任何地方不得制定实行地区封锁或者含有地区封锁内容的规定，妨碍建立和完善全国统一、公平竞争、规范有序的市场体系，损害公平竞争环境。"},{"i":6,"n":"第六条","txt":"地方各级人民政府所属部门的规定属于实行地区封锁或者含有地区封锁内容的，由本级人民政府改变或者撤销；本级人民政府不予改变或者撤销的，由上一级人民政府改变或者撤销。"},{"i":7,"n":"第七条","txt":"省、自治区、直辖市以下地方各级人民政府的规定属于实行地区封锁或者含有地区封锁内容的，由上一级人民政府改变或者撤销；上一级人民政府不予改变或者撤销的，由省、自治区、直辖市人民政府改变或者撤销。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市人民政府的规定属于实行地区封锁或者含有地区封锁内容的，由国务院改变或者撤销。"},{"i":9,"n":"第九条","txt":"地方各级人民政府或者其所属部门设置地区封锁的规定或者含有地区封锁内容的规定，是以国务院所属部门不适当的规定为依据的，由国务院改变或者撤销该部门不适当的规定。"},{"i":10,"n":"第十条","txt":"以任何方式限定、变相限定单位或者个人只能经营、购买、使用本地生产的产品或者只能接受本地企业、指定企业、其他经济组织或者个人提供的服务的，由省、自治区、直辖市人民政府组织经济贸易管理部门、工商行政管理部门查处，撤销限定措施。"},{"i":11,"n":"第十一条","txt":"在道路、车站、港口、航空港或者在本行政区域边界设置关卡，阻碍外地产品进入和本地产品运出的，由省、自治区、直辖市人民政府组织经济贸易管理部门、公安部门和交通部门查处，撤销关卡。"},{"i":12,"n":"第十二条","txt":"对外地产品或者服务设定歧视性收费项目、规定歧视性价格，或者实行歧视性收费标准的，由省、自治区、直辖市人民政府组织财政部门和价格部门查处，撤销歧视性收费项目、价格或者收费标准。"},{"i":13,"n":"第十三条","txt":"对外地产品或者服务采取和本地同类产品或者服务不同的技术要求、检验标准，或者对外地产品或者服务采取重复检验、重复认证等歧视性技术措施，限制外地产品或者服务进入本地市场的，由省、自治区、直辖市人民政府组织质量技术监督部门查处，撤销歧视性技术措施。"},{"i":14,"n":"第十四条","txt":"采取专门针对外地产品或者服务的专营、专卖、审批、许可等手段，实行歧视性待遇，限制外地产品或者服务进入本地市场的，由省、自治区、直辖市人民政府组织经济贸易管理部门、工商行政管理部门、质量技术监督部门和其他有关主管部门查处，撤销歧视性待遇。"},{"i":15,"n":"第十五条","txt":"通过设定歧视性资质要求、评审标准或者不依法发布信息等方式，限制或者排斥外地企业、其他经济组织或者个人参加本地的招投标活动的，由省、自治区、直辖市人民政府组织有关主管部门查处，消除障碍。"},{"i":16,"n":"第十六条","txt":"以采取同本地企业、其他经济组织或者个人不平等的待遇等方式，限制或者排斥外地企业、其他经济组织或者个人在本地投资或者设立分支机构，或者对外地企业、其他经济组织或者个人在本地的投资或者设立的分支机构实行歧视性待遇的，由省、自治区、直辖市人民政府组织经济贸易管理部门、工商行政管理部门查处，消除障碍。"},{"i":17,"n":"第十七条","txt":"实行本规定第四条第（一）项至第（七）项所列行为以外的其他地区封锁行为的，由省、自治区、直辖市人民政府组织经济贸易管理部门、工商行政管理部门、质量技术监督部门和其他有关主管部门查处，消除地区封锁。"},{"i":18,"n":"第十八条","txt":"省、自治区、直辖市人民政府依照本规定第十条至第十七条的规定组织所属有关部门对地区封锁行为进行查处，处理决定由省、自治区、直辖市人民政府作出；必要时，国务院经济贸易管理部门、国务院工商行政管理部门、国务院质量监督检验检疫部门或者国务院其他有关部门可以对涉及省、自治区、直辖市人民政府的地区封锁行为进行查处。"},{"i":19,"n":"第十九条","txt":"地区封锁行为属于根据地方人民政府或者其所属部门的规定实行的，除依照本规定第十条至第十七条的规定查处、消除地区封锁外，并应当依照本规定第六条至第九条的规定，对有关规定予以改变或者撤销。"},{"i":20,"n":"第二十条","txt":"任何单位和个人均有权对地区封锁行为进行抵制，并向有关省、自治区、直辖市人民政府或者其经济贸易管理部门、工商行政管理部门、质量技术监督部门或者其他有关部门直至国务院经济贸易管理部门、国务院工商行政管理部门、国务院质量监督检验检疫部门或者国务院其他有关部门检举。"},{"i":21,"n":"第二十一条","txt":"对地方人民政府或者其所属部门违反本规定，实行地区封锁的，纵容、包庇地区封锁的，或者阻挠、干预查处地区封锁的，由省、自治区、直辖市人民政府给予通报批评；省、自治区、直辖市人民政府违反本规定，实行地区封锁的，纵容、包庇地区封锁的，或者阻挠、干预查处地区封锁的，由国务院给予通报批评。对直接负责的主管人员和其他直接责任人员，按照法定程序，根据情节轻重，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"地方人民政府或者其所属部门违反本规定，制定实行地区封锁或者含有地区封锁内容的规定的，除依照本规定第六条至第九条的规定对有关规定予以改变或者撤销外，对该地方人民政府或者其所属部门的主要负责人和签署该规定的负责人，按照法定程序，根据情节轻重，给予降级或者撤职的行政处分。"},{"i":23,"n":"第二十三条","txt":"接到检举地区封锁行为的政府或者有关部门，不在规定期限内进行调查、处理或者泄露检举人情况的，对直接负责的主管人员和其他直接责任人员，按照法定程序，根据情节轻重，给予降级、撤职直至开除公职的行政处分。"},{"i":24,"n":"第二十四条","txt":"采取暴力、威胁等手段，欺行霸市、强买强卖，阻碍外地产品或者服务进入本地市场，构成违反治安管理行为的，由公安机关依照《中华人民共和国治安管理处罚法》的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"地方人民政府或者其所属部门滥用行政权力，实行地区封锁所收取的费用及其他不正当收入，应当返还有关企业、其他经济组织或者个人；无法返还的，由上一级人民政府财政部门予以收缴。"},{"i":26,"n":"第二十六条","txt":"地方人民政府或者其所属部门的工作人员对检举地区封锁行为的单位或者个人进行报复陷害的，按照法定程序，根据情节轻重，给予降级、撤职直至开除公职的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"监察机关依照行政监察法的规定，对行政机关及其工作人员的地区封锁行为实施监察。"},{"i":28,"n":"第二十八条","txt":"本规定自公布之日起施行。"}],"guowuyuanguanyukexuejishubokuanguanlidezanxingguid7f73ad":[{"i":1,"n":"第一条","txt":"为了加强科技经费的宏观管理，合理和有效地使用科技拨款，推动科学技术工作面向经济建设，搞好科学研究的纵深配置，保证国家科学技术规划的实施，特制定本规定。"},{"i":2,"n":"第二条","txt":"从第七个五年计划（以下简称“七五”计划）开始，由财政部会同国家计委，按照科技经费拨款的增长高于财政经常性收入增长速度的原则，安排中央财政支出的科技三项费用（中间试验、新产品试制、重大科研项目补助费，下同）和科研事业费的预算拨款额度。"},{"i":3,"n":"第三条","txt":"列入国家计划的重大科技项目的经费，按下列规定管理："},{"i":4,"n":"第四条","txt":"国务院各部门科研事业费，以一九八五年度调整预算数（扣除一次性拨款，不扣除因进行改革试点而减发的拨款），加上一九八五年因工资改革按规定应由财政负担的经费为基数，连同增长的额度，自一九八六年度起，由财政部全部拨交国家科委统一管理。"},{"i":5,"n":"第五条","txt":"各类科研单位的科研事业费，按下列规定管理："},{"i":6,"n":"第六条","txt":"各类科研单位的基本建设投资，按照国家基本建设管理规定办理。"},{"i":7,"n":"第七条","txt":"各类科研单位离、退休人员的离、退休金由科研事业费开支，不予减少。完全停拨科研事业费的单位，离、退休金仍应当照拨。"},{"i":8,"n":"第八条","txt":"企业委托科研单位和高等院校承担的科技任务，其费用由企业支付。"},{"i":9,"n":"第九条","txt":"国家自然科学基金的拨款办法，另行规定。"},{"i":10,"n":"第十条","txt":"国防科技拨款管理办法，由国防科工委另行制订。"},{"i":11,"n":"第十一条","txt":"本规定由国家科委负责解释。"},{"i":12,"n":"第十二条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyujingyingzhejizhongshenbaobiaozhunde116731":[{"i":1,"n":"第一条","txt":"为了明确经营者集中的申报标准，根据《中华人民共和国反垄断法》，制定本规定。"},{"i":2,"n":"第二条","txt":"经营者集中是指下列情形："},{"i":3,"n":"第三条","txt":"经营者集中达到下列标准之一的，经营者应当事先向国务院反垄断执法机构申报，未申报的不得实施集中："},{"i":4,"n":"第四条","txt":"经营者集中未达到本规定第三条规定的申报标准，但有证据证明该经营者集中具有或者可能具有排除、限制竞争效果的，国务院反垄断执法机构可以要求经营者申报。"},{"i":5,"n":"第五条","txt":"经营者未依照本规定第三条和第四条规定进行申报的，国务院反垄断执法机构应当依法进行调查。"},{"i":6,"n":"第六条","txt":"国务院反垄断执法机构应当根据经济发展情况，对本规定确定的申报标准的实施情况进行评估。"},{"i":7,"n":"第七条","txt":"本规定自公布之日起施行。"}],"guowuyuanguanyuzhigonggongzuoshijiandeguiding":[{"i":1,"n":"第一条","txt":"为了合理安排职工的工作和休息时间，维护职工的休息权利，调动职工的积极性，促进社会主义现代化建设事业的发展，根据宪法有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国境内的国家机关、社会团体、企业事业单位以及其他组织的职工。"},{"i":3,"n":"第三条","txt":"职工每日工作8小时，每周工作40小时。"},{"i":4,"n":"第四条","txt":"在特殊条件下从事劳动和有特殊情况，需要适当缩短工作时间的，按照国家有关规定执行。"},{"i":5,"n":"第五条","txt":"因工作性质或者生产特点的限制，不能实行每日工作8小时、每周工作40小时标准工时制度的，按照国家有关规定，可以实行其他工作和休息办法。"},{"i":6,"n":"第六条","txt":"任何单位和个人不得擅自延长职工工作时间。因特殊情况和紧急任务确需延长工作时间的，按照国家有关规定执行。"},{"i":7,"n":"第七条","txt":"国家机关、事业单位实行统一的工作时间，星期六和星期日为周休息日。"},{"i":8,"n":"第八条","txt":"本规定由劳动部、人事部负责解释；实施办法由劳动部、人事部制定。"},{"i":9,"n":"第九条","txt":"本规定自1995年5月1日起施行。1995年5月1日施行有困难的企业、事业单位，可以适当延期；但是，事业单位最迟应当自1996年1月1日起施行，企业最迟应当自1997年5月1日起施行。"}],"guowuyuanguanyugufenyouxiangongsijingneishangshiwa2d4038":[{"i":1,"n":"第一条","txt":"为了规范股份有限公司境内上市外资股的发行及交易，保护投资人的合法权益，根据《中华人民共和国公司法》（以下简称《公司法》）的有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"经国务院证券委员会批准，股份有限公司（以下简称公司）可以发行境内上市外资股；但是，拟发行境内上市外资股的面值总额超过3000万美元的，国务院证券委员会应当报国务院批准。"},{"i":3,"n":"第三条","txt":"公司发行的境内上市外资股，采取记名股票形式，以人民币标明面值，以外币认购、买卖，在境内证券交易所上市交易。"},{"i":4,"n":"第四条","txt":"境内上市外资股投资人限于："},{"i":5,"n":"第五条","txt":"持有同一种类股份的境内上市外资股股东与内资股股东，依照《公司法》享有同等权利和履行同等义务。"},{"i":6,"n":"第六条","txt":"公司章程对公司及其股东、董事、监事、经理和其他高级管理人员具有约束力。"},{"i":7,"n":"第七条","txt":"国务院证券委员会及其监督管理执行机构中国证券监督管理委员会（以下简称中国证监会），依照法律、行政法规的规定，对境内上市外资股的发行、交易及相关活动实施管理和监督。"},{"i":8,"n":"第八条","txt":"以募集方式设立公司，申请发行境内上市外资股的，应当符合下列条件："},{"i":9,"n":"第九条","txt":"公司增加资本，申请发行境内上市外资股的，除应当符合本规定第八条第（一）、（二）、（三）项的规定外，还应当符合下列条件："},{"i":10,"n":"第十条","txt":"申请发行境内上市外资股，按照下列程序办理："},{"i":11,"n":"第十一条","txt":"以募集方式设立公司，申请发行境内上市外资股的，应当向中国证监会报送下列文件："},{"i":12,"n":"第十二条","txt":"公司增加资本，申请发行境内上市外资股的，应当向中国证监会报送下列文件："},{"i":13,"n":"第十三条","txt":"公司发行境内上市外资股与发行内资股的间隔时间可以少于12个月。"},{"i":14,"n":"第十四条","txt":"公司应当聘用符合国家规定的注册会计师及其所在事务所，对其财务报告进行审计或者复核。"},{"i":15,"n":"第十五条","txt":"公司应当按照国家有关规定进行会计核算和编制财务报告。"},{"i":16,"n":"第十六条","txt":"发行境内上市外资股的公司应当依法向社会公众披露信息，并在其公司章程中对信息披露的地点、方式等事宜作出具体规定。"},{"i":17,"n":"第十七条","txt":"发行境内上市外资股的公司的信息披露文件，以中文制作；需要提供外文译本的，应当提供一种通用的外国语言文本。中文文本、外文文本发生歧义时，以中文文本为准。"},{"i":18,"n":"第十八条","txt":"公司发行境内上市外资股，应当委托中国人民银行依法批准设立并经中国证监会认可的境内证券经营机构作为主承销商或者主承销商之一。"},{"i":19,"n":"第十九条","txt":"发行境内上市外资股的公司，应当在具有经营外汇业务资格的境内银行开立外汇帐户。公司开立外汇帐户应当按照国家有关外汇管理的规定办理。"},{"i":20,"n":"第二十条","txt":"境内上市外资股股票的代理买卖业务，应当由中国人民银行依法批准设立并经中国证监会认可的证券经营机构办理。"},{"i":21,"n":"第二十一条","txt":"境内上市外资股股东可以委托代理人代为行使其股东权利；代理人代行股东权利时，应当提供证明其代理资格的有效文件。"},{"i":22,"n":"第二十二条","txt":"境内上市外资股的权益拥有人，可以将其股份登记在名义持有人名下。"},{"i":23,"n":"第二十三条","txt":"境内上市外资股的交易、保管、清算交割、过户和登记，应当遵守法律、行政法规以及国务院证券委员会的有关规定。"},{"i":24,"n":"第二十四条","txt":"经国务院证券委员会批准，境内上市外资股或者其派生形式可以在境外流通转让。"},{"i":25,"n":"第二十五条","txt":"公司向境内上市外资股股东支付股利及其他款项，以人民币计价和宣布，以外币支付。公司所筹集的外币资本金的管理和公司支付股利及其他款项所需的外币，按照国家有关外汇管理的规定办理。"},{"i":26,"n":"第二十六条","txt":"境内上市外资股的股利和其他收益依法纳税后，可以汇出境外。"},{"i":27,"n":"第二十七条","txt":"国务院证券委员会可以根据本规定制定实施细则。"},{"i":28,"n":"第二十八条","txt":"本规定自发布之日起施行。中国人民银行、上海市人民政府1991年11月22日发布的《上海市人民币特种股票管理办法》，中国人民银行、深圳市人民政府1991年12月5日发布的《深圳市人民币特种股票管理暂行办法》同时废止。"}],"guowuyuanguanyuguifanzhongjiejigouweigongsigongkai3778f3":[{"i":1,"n":"第一条","txt":"为了规范中介机构为公司公开发行股票提供服务行为，提高上市公司质量，保护投资者合法权益，促进资本市场健康稳定发展，制定本规定。"},{"i":2,"n":"第二条","txt":"证券公司、会计师事务所、律师事务所等机构（以下统称中介机构）为公司在中华人民共和国境内公开发行股票提供服务收取费用等相关活动，适用本规定。"},{"i":3,"n":"第三条","txt":"中介机构为公司公开发行股票提供服务，应当遵循诚实守信、勤勉尽责、独立客观的原则，同时配备具有相应专业能力和资质的从业人员，建立有效的利益冲突审查等风险控制制度。"},{"i":4,"n":"第四条","txt":"中介机构为公司公开发行股票提供服务，不得有配合公司实施财务造假、欺诈发行、违规信息披露等违法违规行为，制作、出具的文件不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":5,"n":"第五条","txt":"中介机构应当遵循市场化原则，根据工作量、所需资源投入等因素合理确定收费标准，并与发行人在合同中约定收费安排。"},{"i":6,"n":"第六条","txt":"证券公司从事保荐业务，可以按照工作进度分阶段收取服务费用，但是收费与否以及收费多少不得以股票公开发行上市结果作为条件。"},{"i":7,"n":"第七条","txt":"会计师事务所执行审计业务，可以按照工作进度分阶段收取服务费用，但是收费与否以及收费多少不得以审计结果或者股票公开发行上市结果作为条件。"},{"i":8,"n":"第八条","txt":"律师事务所为公司公开发行股票提供服务，应当由律师事务所统一收费，并符合国务院司法行政等部门关于律师服务收费的相关规定。"},{"i":9,"n":"第九条","txt":"中介机构及其从业人员不得存在以下情形："},{"i":10,"n":"第十条","txt":"地方各级人民政府不得以股票公开发行上市结果为条件，给予发行人或者中介机构奖励。"},{"i":11,"n":"第十一条","txt":"发行人申请公开发行股票时，应当在所报送的招股说明书或者其他相关信息披露文件中详细列明各类中介服务收费标准、金额以及发行人付费安排等信息。"},{"i":12,"n":"第十二条","txt":"证券监督管理、财政、司法行政等部门应当加强信息沟通和协调配合，按照职责分工，依法对中介机构执业行为加强监管；必要时可以采取联合现场检查等措施，依法查处违法违规行为。"},{"i":13,"n":"第十三条","txt":"中介机构违反本规定的，由证券监督管理、财政、司法行政、市场监督管理等部门按照职责分工责令改正，给予警告，没收违法所得，可以并处违法所得1倍以上10倍以下罚款；没有违法所得或者违法所得不足10万元的，可以并处10万元以上100万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，可以并处10万元以上100万元以下罚款。法律另有规定的，从其规定。"},{"i":14,"n":"第十四条","txt":"发行人违反本规定第十一条规定的，由证券监督管理机构责令改正，给予警告，可以并处10万元以上100万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，可以并处10万元以上100万元以下罚款。发行人的控股股东、实际控制人组织、指使从事上述违法行为，或者隐瞒相关事项导致发生上述情形的，处10万元以上100万元以下罚款；对直接负责的主管人员和其他直接责任人员给予警告，并处10万元以上100万元以下罚款。"},{"i":15,"n":"第十五条","txt":"国务院证券监督管理机构依法将中介机构遵守本规定的情况纳入证券市场诚信档案。"},{"i":16,"n":"第十六条","txt":"自本规定施行之日起，地方各级人民政府违反本规定第十条规定，给予发行人或者中介机构奖励的，应当追回，并由有关机关对负有责任的领导人员和直接责任人员依法给予处分。"},{"i":17,"n":"第十七条","txt":"中介机构为公司公开发行存托凭证、可转换为股票的公司债券提供服务的，参照适用本规定。"},{"i":18,"n":"第十八条","txt":"国务院证券监督管理、财政、司法行政等部门可以根据本规定制定实施办法。"},{"i":19,"n":"第十九条","txt":"本规定自2025年2月15日起施行。"}],"guowuyuanguanyujinyibuwanshanwenhuajingjizhengcede610e56":[],"guowuyuanguanyugaojizhuanjialixiutuixiuruoganwenti894484":[{"i":1,"n":"第一条","txt":"本规定所称高级专家，系指：正副教授、正副研究员、高级工程师、高级农艺师、正副主任医师、正副编审、正副译审、正副研究馆员、高级经济师、高级统计师、高级会计师、特级记者、高级记者、高级工艺美术师，以及文艺六级以上的专家。"},{"i":2,"n":"第二条","txt":"高级专家离休退休年龄，一般应按国家统一规定执行。对其中少数高级专家，确因工作需要，身体能够坚持正常工作，征得本人同意，经下述机关批准，其离休退休年龄可以适当延长："},{"i":3,"n":"第三条","txt":"延长离休退休年龄的高级专家中，担任行政领导职务或管理职务的，在达到国家统一规定的离休退休年龄时，应当免去其行政领导职务或管理职务，使他们集中精力继续从事科学技术或文化艺术等工作。特殊情况经过任免机关批准的除外。"},{"i":4,"n":"第四条","txt":"高级专家离休退休的待遇，按国家统一规定办理。符合以下情况的，退休费标准可以适当提高："},{"i":5,"n":"第五条","txt":"高级专家离休退休后，如身体尚好，可以接受部门或单位的聘请，担任科学技术或文化艺术顾问，也可以直接承担业务工作。聘请离休退休高级专家应签订聘请合同，聘请条件和受聘人员待遇按国家有关规定办理。"},{"i":6,"n":"第六条","txt":"各单位和各部门要认真执行国务院关于干部离休退休后政治、生活待遇的有关规定，对离休退休的高级专家应体贴关怀，热情爱护；要积极主动地帮助他们继续进行科学研究、资料整理、著书立说等工作，为他们的业务活动提供必要的方便。"},{"i":7,"n":"第七条","txt":"本规定自发布之日起施行。本规定发布以前，已经离休退休的高级专家，不再复职。"},{"i":8,"n":"第八条","txt":"本规定由劳动人事部负责解释。"}],"guowuyuanguanyugaojizhuanjiatuixiuwentidebuchonggu23a4cd":[],"guowuyuanguanyugulihuaqiaohexianggangaomentongbaot69165e":[{"i":1,"n":"第一条","txt":"为促进我国经济发展，鼓励华侨和香港澳门同胞（以下统称华侨、港澳投资者）在境内投资，制定本规定。"},{"i":2,"n":"第二条","txt":"华侨、港澳投资者可以在境内各省、自治区、直辖市、经济特区投资。"},{"i":3,"n":"第三条","txt":"华侨、港澳投资者在境内可以下列形式进行投资："},{"i":4,"n":"第四条","txt":"华侨、港澳投资者可以在境内的工业、农业、服务业以及其他符合社会和经济发展方向的行业投资。华侨、港澳投资者可以从各地方人民政府有关部门公布的项目中选择投资项目，也可以自行提出投资项目意向，向拟投资地区对外经济贸易部门或者地方人民政府指定的审批机关申请。"},{"i":5,"n":"第五条","txt":"华侨、港澳投资者在境内投资举办拥有全部资本的企业、合资经营企业和合作经营企业（以下统称华侨、港澳同胞投资企业），除适用本规定外，参照执行国家有关涉外经济法律、法规的规定，享受相应的外商投资企业待遇。"},{"i":6,"n":"第六条","txt":"华侨、港澳投资者可以用可自由兑换货币、机器设备或者其他实物、工业产权、专有技术等作为投资。"},{"i":7,"n":"第七条","txt":"华侨、港澳投资者在境内的投资、购置的资产、工业产权、投资所得利润和其他合法权益受国家法律保护，并可以依法转让和继承。"},{"i":8,"n":"第八条","txt":"国家对华侨、港澳投资者的投资和其他资产不实行国有化。"},{"i":9,"n":"第九条","txt":"国家根据社会公共利益的需要，对华侨、港澳同胞投资企业实行征收时，依照法律程序进行并给予相应的补偿。"},{"i":10,"n":"第十条","txt":"华侨、港澳投资者投资获得的合法利润，其他合法收入和清算后的资金，可以依法汇往境外。"},{"i":11,"n":"第十一条","txt":"华侨、港澳同胞投资企业在其投资总额内进口本企业所需的机器设备、生产用车辆和办公设备，以及华侨、港澳同胞个人在企业工作期间运进自用的、合理数量的生活用品和交通工具，免缴进口关税、工商统一税，免领进口许可证。"},{"i":12,"n":"第十二条","txt":"华侨、港澳同胞投资企业可以向境内的金融机构借款，也可以向境外的金融机构借款，并可以本企业资产和权益抵押、担保。"},{"i":13,"n":"第十三条","txt":"华侨、港澳投资者拥有全部资本的企业，经营期限由投资者自行确定；合资经营企业和合作经营企业，经营期限由合资或者合作各方协商确定，也可以不规定经营期限。"},{"i":14,"n":"第十四条","txt":"合资经营企业董事会的组成和董事长的委派、合作经营企业董事会或者联合管理机构的组成和董事长或者联合管理机构主任的委派，可以参照出资比例或者合作条件，由合资或者合作各方协商决定。"},{"i":15,"n":"第十五条","txt":"华侨、港澳同胞投资企业依照经批准的合同、章程进行经营管理活动。企业的经营管理自主权不受干涉。"},{"i":16,"n":"第十六条","txt":"在境内投资的华侨、港澳同胞个人以及华侨、港澳同胞投资企业从境外聘请的技术和管理人员，可以申请办理多次入出境的证件。"},{"i":17,"n":"第十七条","txt":"华侨、港澳投资者在境内投资可以委托境内的亲友为其代理人。代理人应当持有具有法律效力的委托书。"},{"i":18,"n":"第十八条","txt":"在华侨、港澳同胞投资企业集中的地区，华侨、港澳投资者可以向当地人民政府申请成立华侨、港澳投资者协会。"},{"i":19,"n":"第十九条","txt":"华侨、港澳投资者在境内投资举办合资经营企业、合作经营企业，由境内的合资、合作方负责申请；举办华侨、港澳投资者拥有全部资本的企业，由华侨、港澳投资者直接申请或者委托在境内的亲友、咨询服务机构等代为申请。华侨、港澳投资者投资举办企业的申请，由当地对外经济贸易部门或者地方人民政府指定的审批机关统一受理。"},{"i":20,"n":"第二十条","txt":"华侨、港澳投资者在境内投资因履行合同发生的或者与合同有关的争议，当事人应当尽可能通过协商或者调解解决。"},{"i":21,"n":"第二十一条","txt":"本规定由对外经济贸易部负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyugulitaiwantongbaotouzideguiding":[{"i":1,"n":"第一条","txt":"为促进大陆和台湾地区的经济技术交流，以利于祖国海峡两岸的共同繁荣，鼓励台湾的公司、企业和个人（以下统称台湾投资者）在大陆投资，制定本规定。"},{"i":2,"n":"第二条","txt":"台湾投资者可以在大陆各省、自治区、直辖市、经济特区投资。"},{"i":3,"n":"第三条","txt":"台湾投资者在大陆可以下列形式进行投资："},{"i":4,"n":"第四条","txt":"台湾投资者可以在大陆的工业、农业、服务业以及其他符合社会和经济发展方向的行业投资。台湾投资者可以从各地方人民政府有关部门公布的项目中选择投资项目，也可以自行提出投资项目意向，向拟投资地区对外经济贸易部门或者地方人民政府指定的审批机关申请。"},{"i":5,"n":"第五条","txt":"台湾投资者在大陆投资举办拥有全部资本的企业、合资经营企业和合作经营企业（以下统称台胞投资企业），除适用本规定外，参照执行国家有关涉外经济法律、法规的规定，享受相应的外商投资企业待遇。"},{"i":6,"n":"第六条","txt":"台湾投资者可以用可自由兑换货币、机器设备或者其他实物、工业产权、专有技术等作为投资。"},{"i":7,"n":"第七条","txt":"台湾投资者在大陆的投资、购置的资产、工业产权、投资所得利润和其他合法权益受国家法律保护，并可以依法转让和继承。"},{"i":8,"n":"第八条","txt":"国家对台湾投资者的投资和其他资产不实行国有化。"},{"i":9,"n":"第九条","txt":"国家根据社会公共利益的需要，对台胞投资企业实行征收时，依照法律程序进行并给予相应的补偿。"},{"i":10,"n":"第十条","txt":"台湾投资者投资获得的合法利润，其他合法收入和清算后的资金，可以依法汇往境外。"},{"i":11,"n":"第十一条","txt":"台胞投资企业在其投资总额内进口本企业所需的机器设备、生产用车辆和办公设备，以及台胞个人在企业工作期间运进自用的、合理数量的生活用品和交通工具，免缴进口关税、工商统一税，免领进口许可证。"},{"i":12,"n":"第十二条","txt":"台胞投资企业可以向大陆的金融机构借款，也可以向境外的金融机构借款，并可以本企业资产和权益抵押、担保。"},{"i":13,"n":"第十三条","txt":"台湾投资者拥有全部资本的企业，经营期限由投资者自行确定；合资经营企业和合作经营企业，经营期限由合资或者合作各方协商确定，也可以不规定经营期限。"},{"i":14,"n":"第十四条","txt":"合资经营企业董事会的组成和董事长的委派、合作经营企业董事会或者联合管理机构的组成和董事长或者联合管理机构主任的委派，可以参照出资比例或者合作条件由合资或者合作各方协商决定。"},{"i":15,"n":"第十五条","txt":"台胞投资企业依照经批准的合同、章程进行经营管理活动。企业的经营管理自主权不受干涉。"},{"i":16,"n":"第十六条","txt":"在大陆投资的台胞个人以及台胞投资企业从境外聘请的技术和管理人员，可以申请办理多次入出境的证件。"},{"i":17,"n":"第十七条","txt":"台湾投资者在大陆投资可以委托大陆的亲友为其代理人。代理人应当持有具有法律效力的委托书。"},{"i":18,"n":"第十八条","txt":"在台胞投资企业集中的地区，台湾投资者可以向当地人民政府申请成立台商协会。"},{"i":19,"n":"第十九条","txt":"台湾投资者在大陆投资举办合资经营企业、合作经营企业，由大陆的合资、合作方负责申请；举办台湾投资者拥有全部资本的企业，由台湾投资者直接申请或者委托在大陆的亲友、咨询服务机构等代为申请。台湾投资者投资举办企业的申请，由当地对外经济贸易部门或者地方人民政府指定的审批机关统一受理。"},{"i":20,"n":"第二十条","txt":"台湾投资者在大陆投资因履行合同发生的或者与合同有关的争议，当事人应当尽可能通过协商或者调解解决。"},{"i":21,"n":"第二十一条","txt":"本规定由对外经济贸易部负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyuguliwaishangtouzideguiding":[{"i":1,"n":"第一条","txt":"为了改善投资环境，更好地吸收外商投资，引进先进技术，提高产品质量，扩大出口创汇，发展国民经济，特制定本规定。"},{"i":2,"n":"第二条","txt":"国家鼓励外国的公司、企业和其他经济组织或者个人（以下简称外国投资者），在中国境内举办中外合资经营企业、中外合作经营企业和外资企业（以下简称外商投资企业）。"},{"i":3,"n":"第三条","txt":"产品出口企业和先进技术企业，除按照国家规定支付或者提取中方职工劳动保险、福利费用和住房补助基金外，免缴国家对职工的各项补贴。"},{"i":4,"n":"第四条","txt":"产品出口企业和先进技术企业的场地使用费，除大城市市区繁华地段外，按下列标准计收："},{"i":5,"n":"第五条","txt":"对产品出口企业和先进技术企业优先提供生产经营所需的水、电、运输条件和通信设施，按照当地国营企业收费标准计收费用。"},{"i":6,"n":"第六条","txt":"产品出口企业和先进技术企业在生产和流通过程中需要借贷的短期周转资金，以及其他必需的信贷资金，经中国银行审核后，优先贷放。"},{"i":7,"n":"第七条","txt":"产品出口企业和先进技术企业的外国投资者，将其从企业分得的利润汇出境外时，免缴汇出额的所得税。"},{"i":8,"n":"第八条","txt":"产品出口企业按照国家规定减免企业所得税期满后，凡当年企业出口产品产值达到当年企业产品产值70%以上的，可以按照现行税率减半缴纳企业所得税。"},{"i":9,"n":"第九条","txt":"先进技术企业按照国家规定减免企业所得税期满后，可以延长三年减半缴纳企业所得税。"},{"i":10,"n":"第十条","txt":"外国投资者将其从企业分得的利润，在中国境内再投资举办、扩建产品出口企业或者先进技术企业，经营期不少于五年的，经申请税务机关核准，全部退还其再投资部分已缴纳的企业所得税税款。经营期不足五年撤出该项投资的，应当缴回已退的企业所得税税款。"},{"i":11,"n":"第十一条","txt":"对外商投资企业的出口产品，除原油、成品油和国家另有规定的产品外，免征工商统一税。"},{"i":12,"n":"第十二条","txt":"外商投资企业可以自行组织其产品出口，也可以按照国家规定委托代理出口。属于需要申领出口许可证的产品，按照企业年度出口计划，每半年申领一次许可证。"},{"i":13,"n":"第十三条","txt":"外商投资企业为履行其产品出口合同，需要进口（包括国家限制进口）的机械设备、生产用的车辆、原材料、燃料、散件、零部件、元器件、配套件，不再报请审批，免领进口许可证，由海关实行监管，凭企业合同或者进出口合同验放。"},{"i":14,"n":"第十四条","txt":"外商投资企业之间，在外汇管理部门监管下，可以相互调剂外汇余缺。"},{"i":15,"n":"第十五条","txt":"各级人民政府和有关主管部门应当保障外商投资企业的自主权，支持外商投资企业按照国际上先进的科学方法管理企业。"},{"i":16,"n":"第十六条","txt":"各地区、各部门必须执行《国务院关于坚决制止向企业乱摊派的通知》，由省级人民政府制定具体办法，加强监督管理。"},{"i":17,"n":"第十七条","txt":"各级人民政府和有关主管部门，应当加强协调工作，提高办事效率，及时审批外商投资企业申报的需要批复和解决的事宜。由国务院主管部门审批的外商投资企业的协议、合同、章程，审批机关必须在收到全部文件之日起三个月以内决定批准或者不批准。"},{"i":18,"n":"第十八条","txt":"本规定所指产品出口企业和先进技术企业，由该企业所在地的对外经济贸易部门会同有关部门根据企业合同确认，并出具证明。"},{"i":19,"n":"第十九条","txt":"本规定除明确规定适用于产品出口企业或者先进技术企业的条款外，其他条款适用于所有外商投资企业。"},{"i":20,"n":"第二十条","txt":"香港、澳门、台湾的公司、企业和其他经济组织或者个人投资举办的企业，参照本规定执行。"},{"i":21,"n":"第二十一条","txt":"本规定由对外经济贸易部负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自发布之日起施行。"}],"guowuyuanguanyugulitouzikaifahainandaodeguiding":[{"i":1,"n":"第一条","txt":"为了吸收境内外投资，加快海南岛的开发建设，特制定本规定。"},{"i":2,"n":"第二条","txt":"国家对海南经济特区实行更加灵活开放的经济政策，授予海南省人民政府更大的自主权。"},{"i":3,"n":"第三条","txt":"国家鼓励境内外的企业、其他经济组织或者个人（以下简称投资者）投资开发海南岛，兴办各项经济和社会事业。"},{"i":4,"n":"第四条","txt":"国家依法保护投资者的合法权益，对投资者的资产不实行国有化和征收，在特殊情况下，为社会公共利益的需要，对投资者的资产可以依照法律程序实行征收，并给予相应的补偿。"},{"i":5,"n":"第五条","txt":"投资者可以下列方式在海南岛投资经营："},{"i":6,"n":"第六条","txt":"海南岛国家所有的土地实行有偿使用。"},{"i":7,"n":"第七条","txt":"海南岛的矿藏资源依法实行有偿开采。国家规定的特定矿藏资源开采应报经国家主管部门批准，其他矿藏资源开采，由海南省人民政府批准。允许投资者以合资经营、合作经营和独资经营的方式进行勘探开采。"},{"i":8,"n":"第八条","txt":"投资者可以合资、合作方式在海南岛投资从事港口、码头、机场、公路、铁路、电站、煤矿、水利等基础设施建设，也可以独资经营专用设施，并可依照国家有关规定投资经营与上述设施相关联的各类企业和服务事业，实行综合经营。"},{"i":9,"n":"第九条","txt":"根据经济发展的需要，经中国人民银行批准，可以在海南岛设立外资银行、中外合资银行或者其他金融机构。"},{"i":10,"n":"第十条","txt":"在海南岛投资兴办各项经济和社会事业，由海南省人民政府审查批准。但投资范围和投资总额超过国家授权海南省人民政府审批范围的，应当按照国家规定程序报批。"},{"i":11,"n":"第十一条","txt":"获准举办的企业作为投资进口的建设物资、生产设备和管理设备，为生产经营进口的原材料、零配件、包装材料和其他物料以及自用的交通工具、办公用品，由海南省人民政府自行审批。"},{"i":12,"n":"第十二条","txt":"在海南岛举办的企业（国家银行和保险公司除外），从事生产、经营所得和其他所得，均按15%的税率征收企业所得税，另按应纳税额附征10%的地方所得税。其中："},{"i":13,"n":"第十三条","txt":"境外投资者在海南岛内没有设立机构而有来源于海南岛的股息、利息、租金、特许权使用费和其他所得，除依法免征所得税者外，均按10%的税率征收所得税。需要给予减征或者免征所得税优惠的，由海南省人民政府决定。"},{"i":14,"n":"第十四条","txt":"在海南岛举办的外商投资企业和外商持有25%以上股份的企业均享有进出口经营权，其他企业经海南省人民政府批准也可以享有进出口经营权，进口本企业生产、经营必需的货物，出口本企业的产品。"},{"i":15,"n":"第十五条","txt":"海南岛内的企业进口本企业建设和生产所必需的机器设备、原材料、零配件、交通运输工具和其他物料，以及办公用品，均免征关税、产品税或增值税。"},{"i":16,"n":"第十六条","txt":"国家鼓励海南岛内的企业生产的产品出口。对企业生产的出口产品免征出口关税，除原油、成品油和国家另有规定的少数产品外，退还已征的产品税或增值税。"},{"i":17,"n":"第十七条","txt":"海南岛内的企业生产的产品在岛内市场销售的，除矿物汕、烟、酒和海南省人民政府规定的其他少数产品减半征收产品税或增值税外，其余免征产品税或增值税。含有进口料件的，按照第十五条的规定，免征或者补征进口料件的关税、产品税或增值税。"},{"i":18,"n":"第十八条","txt":"海南岛内的企业出口产品和从事其他经营活动取得的外汇收入，均可保留现汇，按当地中国人民银行的规定管理。"},{"i":19,"n":"第十九条","txt":"境外投资者从在海南岛投资举办的企业获得的利润，可以从企业的外汇存款帐户自由汇往境外，免缴汇出额的所得税。"},{"i":20,"n":"第二十条","txt":"凡与我国有外交关系或者官方贸易往来的国家或地区的外国人，在海南岛洽谈投资、贸易，进行经济技术交流、探亲、旅游，停留时间不超过十五天的，可临时在海口或三亚口岸办理入境签证手续；如有正当理由需要延长在海南岛内的停留期限或者转往境内其他地区，可按有关规定申请办理签证延期或加签手续。"},{"i":21,"n":"第二十一条","txt":"香港、澳门、台湾同胞和华侨，凡持有国务院主管部门及其授权机关签发的有效护照或其他有效证件，前往海南岛及转往境内其他地区或者出境，无需办理签证。台湾同胞可以直接在海南岛的口岸申领《台湾同胞旅行证明》。"},{"i":22,"n":"第二十二条","txt":"本规定未尽事项，海南省人民政府可按照国家有关经济特区的规定办理。"},{"i":23,"n":"第二十三条","txt":"本规定自发布之日起施行。"}],"guojiajiguangongzuorenyuanbingjiaqijianshenghuodai674a05":[],"guojiaxingzhengjiguanjiqigongzuorenyuanzaiguoneigo7ef108":[{"i":1,"n":"第一条","txt":"为了严肃政纪，保持国家行政机关及其工作人员廉洁，制定本规定。"},{"i":2,"n":"第二条","txt":"国家行政机关及其工作人员在国内公务活动中，不得赠送和接受礼品。"},{"i":3,"n":"第三条","txt":"国家行政机关及其工作人员不得假借名义或者以变相形式赠送和接受礼品："},{"i":4,"n":"第四条","txt":"本规定所称的礼品，是指礼物、礼金、礼券以及以象征性低价收款的物品。"},{"i":5,"n":"第五条","txt":"国家行政机关违反本规定第二、三条的规定，对负直接责任的机关有关领导人和直接责任者，根据数额多少，情节轻重，分别给予警告、记过、记大过、降级直至撤职处分。"},{"i":6,"n":"第六条","txt":"国家行政机关工作人员，违反本规定第二、三条的规定，接受礼品的，根据数额多少，情节轻重，分别给予警告、记过、记大过、降级直至撤职处分。"},{"i":7,"n":"第七条","txt":"国家行政机关及其工作人员违反本规定第二、三条的规定，数额较少、情节轻微，经批评教育表示悔改的，可以免予行政处分。"},{"i":8,"n":"第八条","txt":"国家行政机关及其工作人员为谋取不正当利益而赠送、接受或者索取礼品的，按照国家有关惩治行贿、受贿的法律、法规处理。"},{"i":9,"n":"第九条","txt":"对接收的礼品必须在一个月内交出并上交国库。所收礼品不按期交出的，按贪污论处。"},{"i":10,"n":"第十条","txt":"对国家行政机关工作人员赠送和接受礼品的行政处分，依照国家行政机关工作人员的管理权限和行政处分程序的规定办理。"},{"i":11,"n":"第十一条","txt":"本规定由各级国家行政机关执行，各级监察部门负责监督、检查。"},{"i":12,"n":"第十二条","txt":"各省、自治区、直辖市人民政府可以根据本规定制定实施办法。"},{"i":13,"n":"第十三条","txt":"本规定自发布之日起施行。"}],"guoyouqiyefuyuzhigonganzhiguiding":[{"i":1,"n":"第一条","txt":"为了妥善安置国有企业富余职工，增强企业活力，提高企业经济效益，制定本规定。"},{"i":2,"n":"第二条","txt":"安置国有企业（以下简称企业）中的富余职工，应当遵循企业自行安置为主、社会帮助安置为辅，保障富余职工基本生活的原则。"},{"i":3,"n":"第三条","txt":"企业安置富余职工应当依照本规定采取拓展多种经营、组织劳务活动、发展第三产业、综合利用资源和其它措施。"},{"i":4,"n":"第四条","txt":"企业为安置富余职工而兴办的从事第三产业的独立核算企业，自开业之日起两年免征、三年减半征收企业所得税。"},{"i":5,"n":"第五条","txt":"企业开办的劳动就业服务企业，应当承担安置本企业富余职工的任务。企业应当按照国家有关国有资产管理的规定，在资金、场地、原材料和设备等方面给予扶持。"},{"i":6,"n":"第六条","txt":"企业组织本企业富余职工依法兴办的独立核算企业，可以承担本企业中原由外单位承包的技术改造或者劳务项目。"},{"i":7,"n":"第七条","txt":"企业可以对富余职工实行待岗和转业培训，培训期间的工资待遇由企业自行确定。"},{"i":8,"n":"第八条","txt":"经企业职工代表大会讨论同意并报企业行政主管部门备案，企业可以对职工实行有限期的放假。职工放假期间，由企业发给生活费。"},{"i":9,"n":"第九条","txt":"职工距退休年龄不到五年的，经本人申请，企业领导批准，可以退出工作岗位休养。职工退出工作岗位休养期间，由企业发给生活费。已经实行退休费用统筹的地方，企业和退出工作岗位休养的职工应当按照有关规定缴纳基本养老保险费。职工退出工作岗位休养期间达到国家规定的退休年龄时，按照规定办理退休手续。职工退出工作岗位休养期间视为工龄，与其以前的工龄合并计算。"},{"i":10,"n":"第十条","txt":"职工可以申请辞职。经企业批准辞职的职工，在办理辞职手续时，企业应当按照国家有关规定发给一次性生活补助费。"},{"i":11,"n":"第十一条","txt":"按照本规定第八条、第九条规定发放的生活费在企业工资基金中列支，生活费标准由企业自主确定，但是不得低于省、自治区、直辖市人民政府规定的最低标准。"},{"i":12,"n":"第十二条","txt":"企业因生产经营发生重大变化，必须裁减职工的，对劳动合同制职工，经企业职工代表大会讨论同意，可以提前解除劳动合同，但是应当按照合同约定履行义务；合同没有约定的，企业对被提前解除劳动合同的职工，按照其在本企业工作的年限，工龄每满一年，发给相当于本人一个月标准工资的补偿费。"},{"i":13,"n":"第十三条","txt":"各级劳动行政主管部门和企业行政主管部门应当做好富余职工的社会安置和调剂工作，鼓励和帮助富余职工组织起来就业和自谋职业。企业之间调剂职工，可以正式调动，也可以临时借调；临时借调的，借调期间的工资和福利待遇由双方企业在协议中商定。"},{"i":14,"n":"第十四条","txt":"富余职工由企业自行安置有困难到社会待业的，在待业期间，依法享受待业保险待遇。劳动行政主管部门和有关行政主管部门应当创造条件，帮助职工再就业。"},{"i":15,"n":"第十五条","txt":"企业依照本规定兴办的独立核算企业安置的职工，按照国家有关规定纳入新办企业的职工人数和经济指标的统计范围。"},{"i":16,"n":"第十六条","txt":"省、自治区、直辖市人民政府可以根据本规定制定实施办法。"},{"i":17,"n":"第十七条","txt":"本规定由国务院劳动行政主管部门负责解释。"},{"i":18,"n":"第十八条","txt":"本规定自发布之日起施行。"}],"guojiyoulunzaigangkoukaogangbujideguiding":[{"i":1,"n":"第一条","txt":"为了提升国际邮轮在中华人民共和国港口靠港补给便利化水平，推动邮轮经济高质量发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称国际邮轮，是指航行国际航线的外国籍邮轮和中华人民共和国国籍邮轮。"},{"i":3,"n":"第三条","txt":"国家建立健全适应国际邮轮靠港补给的制度规范，鼓励国际邮轮在中华人民共和国港口靠港补给，保护国际邮轮经营者、靠港补给物资及相关服务提供者的合法权益，营造稳定公平透明可预期的营商环境。"},{"i":4,"n":"第四条","txt":"国务院有关部门和有关县级以上地方人民政府应当贯彻落实党和国家路线方针政策、决策部署，坚持总体国家安全观，加强国际邮轮靠港补给工作的信息共享、协同配合、服务保障。"},{"i":5,"n":"第五条","txt":"国务院有关部门和有关县级以上地方人民政府结合实际情况，综合运用大数据、人工智能等技术手段对靠港补给物资实行分类管理，完善不同种类物资的通关、仓储等管理措施，推动国际邮轮物资供应保障中心建设。"},{"i":6,"n":"第六条","txt":"船舶供油企业应当依照国家有关规定开展保税油供应业务，提升保障供应能力，为靠港补给的国际邮轮提供便捷、高效的服务。"},{"i":7,"n":"第七条","txt":"港口经营人、岸电供电企业、国际邮轮经营者建立健全协作机制，完善岸电供受电设施管理、使用、维护保养制度和操作规程等，确保靠港补给的国际邮轮依照有关规定安全规范使用岸电。"},{"i":8,"n":"第八条","txt":"国际邮轮靠港补给物资及相关服务提供者依照有关法律法规规定和合同约定，供应国际邮轮运营所需的食品、日常生活用品、药品、医疗器械、应急救援物资、船舶备件等物资，提供相关服务。"},{"i":9,"n":"第九条","txt":"国际邮轮需要自中华人民共和国境内采购的药品、医疗器械，由具备药品、医疗器械经营资质的企业供应。"},{"i":10,"n":"第十条","txt":"国际邮轮需要自中华人民共和国境内采购的免税烟草制品，由具备免税烟草制品经营资质的企业供应。免税烟草制品经营企业应当依照国家有关规定，供应国际邮轮工作人员和旅客在国际邮轮上自用且数量合理的免税烟草制品。"},{"i":11,"n":"第十一条","txt":"国际邮轮停靠港口所在地省、自治区、直辖市人民政府在征求港口所在地城市人民政府意见的基础上，制定国际邮轮靠港补给常用低危物资清单，明确允许在本行政区域内港口补给与国际邮轮运营相关的常用低危物资种类和数量。"},{"i":12,"n":"第十二条","txt":"境内物资供应国际邮轮的，可以按照一般贸易方式出口或者作为进出境运输工具物料出口，并依照国家有关规定办理出口退税。"},{"i":13,"n":"第十三条","txt":"国际邮轮靠港补给所需物资，可以依照海关有关规定集中存放在海关特殊监管区域或者保税场所内。海关应当为相关物资仓储、分拨、转运、配送、装卸等提供便利条件。"},{"i":14,"n":"第十四条","txt":"除国家另有规定外，国际邮轮靠港补给境外物资的，不实行关税配额、许可证管理。"},{"i":15,"n":"第十五条","txt":"国际邮轮经营者、靠港补给物资及相关服务提供者不得危害中国国家安全、损害社会公共利益，在靠港补给活动中应当遵守中国法律法规；违反本规定的，依法追究法律责任。"},{"i":16,"n":"第十六条","txt":"本规定自2024年6月1日起施行。"}],"difangkouanguanlijigouzhizefanweizanxingguiding":[],"chengshijieyueyongshuiguanliguiding":[{"i":1,"n":"第一条","txt":"为加强城市节约用水管理，保护和合理利用水资源，促进国民经济和社会发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于城市规划区内节约用水的管理工作。"},{"i":3,"n":"第三条","txt":"城市实行计划用水和节约用水。"},{"i":4,"n":"第四条","txt":"国家鼓励城市节约用水科学技术研究，推广先进技术，提高城市节约用水科学技术水平。"},{"i":5,"n":"第五条","txt":"国务院城市建设行政主管部门主管全国的城市节约用水工作，业务上受国务院水行政主管部门指导。"},{"i":6,"n":"第六条","txt":"城市人民政府应当在制定城市供水发展规划的同时，制定节约用水发展规划，并根据节约用水发展规划制定节约用水年度计划。"},{"i":7,"n":"第七条","txt":"工业用水重复利用率低于40%（不包括热电厂用水）的城市，新建供水工程时，未经上一级城市建设行政主管部门的同意，不得新增工业用水量。"},{"i":8,"n":"第八条","txt":"单位自建供水设施取用地下水，必须经城市建设行政主管部门核准后，依照国家规定申请取水许可。"},{"i":9,"n":"第九条","txt":"城市的新建、扩建和改建工程项目，应当配套建设节约用水设施。城市建设行政主管部门应当参加节约用水设施的竣工验收。"},{"i":10,"n":"第十条","txt":"城市建设行政主管部门应当会同有关行业行政主管部门制定行业综合用水定额和单项用水定额。"},{"i":11,"n":"第十一条","txt":"城市用水计划由城市建设行政主管部门根据水资源统筹规划和水长期供求计划制定，并下达执行。"},{"i":12,"n":"第十二条","txt":"生活用水按户计量收费。新建住宅应当安装分户计量水表；现有住户未装分户计量水表的，应当限期安装。"},{"i":13,"n":"第十三条","txt":"各用水单位应当在用水设备上安装计量水表，进行用水单耗考核，降低单位产品用水量；应当采取循环用水、一水多用等措施，在保证用水质量标准的前提下，提高水的重复利用率。"},{"i":14,"n":"第十四条","txt":"水资源紧缺城市，应当在保证用水质量标准的前提下，采取措施提高城市污水利用率。"},{"i":15,"n":"第十五条","txt":"城市供水企业、自建供水设施的单位应当加强供水设施的维修管理，减少水的漏损量。"},{"i":16,"n":"第十六条","txt":"各级统计部门、城市建设行政主管部门应当做好城市节约用水统计工作。"},{"i":17,"n":"第十七条","txt":"城市的新建、扩建和改建工程项目未按规定配套建设节约用水设施或者节约用水设施经验收不合格的，由城市建设行政主管部门限制其用水量，并责令其限期完善节约用水设施，可以并处罚款。"},{"i":18,"n":"第十八条","txt":"超计划用水加价水费必须按规定的期限缴纳。逾期不缴纳的，城市建设行政主管部门除限期缴纳外，并按日加收超计划用水加价水费50‰的滞纳金。"},{"i":19,"n":"第十九条","txt":"拒不安装生活用水分户计量水表的，城市建设行政主管部门应当责令其限期安装；逾期仍不安装的，由城市建设行政主管部门限制其用水量，可以并处罚款。"},{"i":20,"n":"第二十条","txt":"当事人对行政处罚决定不服的，可以在接到处罚通知次日起十五日内，向作出处罚决定的机关的上一级机关申请复议；对复议决定不服的，可以在接到复议通知次日起十五日内向人民法院起诉。逾期不申请复议或者不向人民法院起诉又不履行处罚决定的，由作出处罚决定的机关申请人民法院强制执行。"},{"i":21,"n":"第二十一条","txt":"城市建设行政主管部门的工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管部门给予行政处分；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"各省、自治区、直辖市人民政府可以根据本规定制定实施办法。"},{"i":23,"n":"第二十三条","txt":"本规定由国务院城市建设行政主管部门负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自1989年1月1日起施行。"}],"waizhaitongjijiancezanxingguiding":[{"i":1,"n":"第一条","txt":"为了准确、及时、全面地集中全国的外债信息，有效地控制对外借款规模，提高利用国外资金的效益，促进国民经济的发展，特制定本规定。"},{"i":2,"n":"第二条","txt":"国家对外债实行登记管理制度。"},{"i":3,"n":"第三条","txt":"本规定所称的外债是指中国境内的机关、团体、企业、事业单位、金融机构或者其他机构（以下统称借款单位）对中国境外的国际金融组织、外国政府、金融机构、企业或者其他机构用外国货币承担的具有契约性偿还义务的全部债务，包括："},{"i":4,"n":"第四条","txt":"外债登记分为逐笔登记和定期登记。"},{"i":5,"n":"第五条","txt":"外商投资企业的对外借款，借款单位应当在正式签订借款合同后15天内，持借款合同副本向所在地外汇管理局办理登记手续并领取逐笔登记的《外债登记证》。"},{"i":6,"n":"第六条","txt":"借款单位调入国外借款时，凭《外债登记证》在中国银行或者经国家外汇管理局批准的其他银行（以下简称银行）开立外债专用现汇账户。经批准将借款存放境外的借款单位以及其他非调入形式的外债的借款单位，凭《外债登记证》在银行开立还本付息外债专用现汇账户。"},{"i":7,"n":"第七条","txt":"实行逐笔登记的借款单位还本付息时，开户银行应当凭借款单位提供的外汇管理局的核准证件和《外债登记证》，通过外债专用现汇账户或者还本付息外债专用现汇账户办理收付。借款单位应当按照银行的收付凭证，将收付款项记入《外债变动反馈表》并将该表的副本报送签发《外债登记证》的外汇管理局。"},{"i":8,"n":"第八条","txt":"借款单位全部偿清《外债登记证》所载明的外债后，银行应即注销其外债专用现汇账户或者还本付息外债专用现汇账户，借款单位应当在15天内向发证的外汇管理局缴销《外债登记证》。"},{"i":9,"n":"第九条","txt":"凡违反本规定有下列行为之一的，所在地外汇管理局可根据情节处以最高不超过所涉及外债金额3%的罚款："},{"i":10,"n":"第十条","txt":"本规定由国家外汇管理局负责解释。"},{"i":11,"n":"第十一条","txt":"本规定自发布之日起施行。"}],"waishangtouzidianxinqiyeguanliguiding":[{"i":1,"n":"第一条","txt":"为了适应电信业对外开放的需要，促进电信业的发展，根据有关外商投资的法律、行政法规和《中华人民共和国电信条例》（以下简称电信条例），制定本规定。"},{"i":2,"n":"第二条","txt":"外商投资电信企业，是指外国投资者依法在中华人民共和国境内设立的经营电信业务的企业。"},{"i":3,"n":"第三条","txt":"外商投资电信企业从事电信业务经营活动，除必须遵守本规定外，还必须遵守电信条例和其他有关法律、行政法规的规定。"},{"i":4,"n":"第四条","txt":"外商投资电信企业可以经营基础电信业务、增值电信业务，具体业务分类依照电信条例的规定执行。"},{"i":5,"n":"第五条","txt":"外商投资电信企业的注册资本应当符合下列规定："},{"i":6,"n":"第六条","txt":"经营基础电信业务（无线寻呼业务除外）的外商投资电信企业的外方投资者在企业中的出资比例，最终不得超过49%，国家另有规定的除外。"},{"i":7,"n":"第七条","txt":"外商投资电信企业经营电信业务，除应当符合本规定第四条、第五条、第六条规定的条件外，还应当符合电信条例规定的经营基础电信业务或者经营增值电信业务应当具备的条件。"},{"i":8,"n":"第八条","txt":"经营基础电信业务的外商投资电信企业的中方主要投资者应当符合下列条件："},{"i":9,"n":"第九条","txt":"经营基础电信业务的外商投资电信企业的外方主要投资者应当符合下列条件："},{"i":10,"n":"第十条","txt":"外商投资电信企业，经依法办理市场主体登记后，向国务院工业和信息化主管部门申请电信业务经营许可并报送下列文件："},{"i":11,"n":"第十一条","txt":"外商投资电信企业投资者情况说明书的主要内容包括：投资者的名称和基本情况、各方出资比例、外方投资者对外商投资电信企业的控制情况等。"},{"i":12,"n":"第十二条","txt":"外商投资电信企业经营跨境电信业务，必须经国务院工业和信息化主管部门批准，并通过国务院工业和信息化主管部门批准设立的国际电信出入口局进行。"},{"i":13,"n":"第十三条","txt":"违反本规定第六条规定的，由国务院工业和信息化主管部门责令限期改正，并处10万元以上50万元以下的罚款；逾期不改正的，吊销《电信业务经营许可证》。"},{"i":14,"n":"第十四条","txt":"申请设立外商投资电信企业，提供虚假、伪造的资格证明或者确认文件骗取批准的，批准无效，由国务院工业和信息化主管部门处20万元以上100万元以下的罚款，吊销《电信业务经营许可证》。"},{"i":15,"n":"第十五条","txt":"外商投资电信企业经营电信业务，违反电信条例和其他有关法律、行政法规规定的，由有关机关依法给予处罚。"},{"i":16,"n":"第十六条","txt":"香港特别行政区、澳门特别行政区和台湾地区的公司、企业在内地投资经营电信业务，比照适用本规定。"},{"i":17,"n":"第十七条","txt":"本规定自2002年1月1日起施行。"}],"waiguoshanghuiguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为了促进国际贸易和经济技术交往，加强对外国商会的管理，保障其合法权益，制定本规定。"},{"i":2,"n":"第二条","txt":"外国商会是指外国在中国境内的商业机构及人员依照本规定在中国境内成立，不从事任何商业活动的非营利性团体。"},{"i":3,"n":"第三条","txt":"外国商会必须遵守中华人民共和国法律、法规的规定，不得损害中国的国家安全和社会公共利益。"},{"i":4,"n":"第四条","txt":"成立外国商会，应当具备下列条件："},{"i":5,"n":"第五条","txt":"外国商会应当按照国别成立，可以有团体会员和个人会员。"},{"i":6,"n":"第六条","txt":"外国商会的名称应当冠其本国国名加上“中国”二字。"},{"i":7,"n":"第七条","txt":"成立外国商会，应当向中华人民共和国民政部（以下称登记管理机关）提出书面申请，依法办理登记。登记管理机关应当自收到本规定第八条规定的全部文件之日起60日内作出是否准予登记的决定，准予登记的，签发登记证书；不予登记的，书面说明理由。外国商会经核准登记并签发登记证书，即为成立。"},{"i":8,"n":"第八条","txt":"成立外国商会的书面申请，应当由外国商会主要筹办人签署，并附具下列文件："},{"i":9,"n":"第九条","txt":"外国商会应当在其办公地点设置会计账簿。会员缴纳的会费及按照外国商会章程规定取得的其他经费，应当用于该外国商会章程规定的各项开支，不得以任何名义付给会员或者汇出中国境外。"},{"i":10,"n":"第十条","txt":"外国商会应当于每年1月向登记管理机关提交上一年度的活动情况报告。"},{"i":11,"n":"第十一条","txt":"外国商会需要修改其章程，更换会长、副会长以及常务干事或者改变办公地址时，应当依照本规定第七条、第八条规定的程序办理变更登记。"},{"i":12,"n":"第十二条","txt":"外国商会应当接受中国有关主管机关的监督。"},{"i":13,"n":"第十三条","txt":"外国商会解散，应当持该外国商会会长签署的申请注销登记报告和清理债务完结的证明，向登记管理机关办理注销登记。"},{"i":14,"n":"第十四条","txt":"本规定自1989年7月1日起施行。"}],"waiguozaihuachangzhurenyuanxiedaijinjingwupinjinkoacf2ec":[{"i":1,"n":"第一条","txt":"为了贯彻对外开放政策、加强对外交流、促进对外经济贸易的发展，特制定本规定。"},{"i":2,"n":"第二条","txt":"经中华人民共和国主管部门批准的境外企业、新闻、经贸机构、文化团体及境外法人在我国境内设立的常驻机构（以下简称“常驻机构”），其获准进境并在我国境内居留一年以上的外国公民、华侨和港、澳、台居民（包括与其共同生活的配偶及未成年子女）等常驻人员（以下简称“常住人员”），进口的自用物品，适用于本规定。这些人员具体是指："},{"i":3,"n":"第三条","txt":"上述六类常住人员在华居住一年以上者（即：工作或留学签证有效期超过一年的），在签证有效期内初次来华携带进境的个人自用的家用摄像机、照相机、便携式收录机、便携式激光唱机、便携式计算机，报经所在地主管海关审核，在每个品种一台的数量限制内，予以免征进口税，超出部分照章征税。"},{"i":4,"n":"第四条","txt":"对符合第二条规定的外籍专家（含港、澳、台地区专家）或华侨专家携运进境的图书资料、科研仪器、工具、样品、试剂等教学、科研物品，在自用合理数量范围内，免征进口税。"},{"i":5,"n":"第五条","txt":"以上外国人员在华生活、学习、工作期间携带进境的第三条、第四条规定以外的行李物品，按《中华人民共和国海关对进出境旅客行李物品监管办法》执行。"},{"i":6,"n":"第六条","txt":"以上规定进口的免税物品，按海关对免税进口物品的有关规定接受海关监管。"},{"i":7,"n":"第七条","txt":"外国（包括地区）驻华使（领）馆、联合国专门机构及国际组织常驻（代表）机构的常驻人员（包括与其同行来华居驻的配偶及未成年子女）携带进境的物品，仍按现行有关规定执行。"},{"i":8,"n":"第八条","txt":"此前的有关政策、规定，凡与本规定不符的，按本规定执行。"},{"i":9,"n":"第九条","txt":"中华人民共和国海关总署依据本规定，制定实施细则。"},{"i":10,"n":"第十条","txt":"本规定自1999年4月1日起执行。"}],"nvzhigonglaodongbaohutebieguiding":[{"i":1,"n":"第一条","txt":"为了减少和解决女职工在劳动中因生理特点造成的特殊困难，保护女职工健康，制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的国家机关、企业、事业单位、社会团体、个体经济组织以及其他社会组织等用人单位及其女职工，适用本规定。"},{"i":3,"n":"第三条","txt":"用人单位应当加强女职工劳动保护，采取措施改善女职工劳动安全卫生条件，对女职工进行劳动安全卫生知识培训。"},{"i":4,"n":"第四条","txt":"用人单位应当遵守女职工禁忌从事的劳动范围的规定。用人单位应当将本单位属于女职工禁忌从事的劳动范围的岗位书面告知女职工。"},{"i":5,"n":"第五条","txt":"用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。"},{"i":6,"n":"第六条","txt":"女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。"},{"i":7,"n":"第七条","txt":"女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。"},{"i":8,"n":"第八条","txt":"女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。"},{"i":9,"n":"第九条","txt":"对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。"},{"i":10,"n":"第十条","txt":"女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。"},{"i":11,"n":"第十一条","txt":"在劳动场所，用人单位应当预防和制止对女职工的性骚扰。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府人力资源社会保障行政部门、安全生产监督管理部门按照各自职责负责对用人单位遵守本规定的情况进行监督检查。"},{"i":13,"n":"第十三条","txt":"用人单位违反本规定第六条第二款、第七条、第九条第一款规定的，由县级以上人民政府人力资源社会保障行政部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。"},{"i":14,"n":"第十四条","txt":"用人单位违反本规定，侵害女职工合法权益的，女职工可以依法投诉、举报、申诉，依法向劳动人事争议调解仲裁机构申请调解仲裁，对仲裁裁决不服的，依法向人民法院提起诉讼。"},{"i":15,"n":"第十五条","txt":"用人单位违反本规定，侵害女职工合法权益，造成女职工损害的，依法给予赔偿；用人单位及其直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本规定自公布之日起施行。1988年7月21日国务院发布的《女职工劳动保护规定》同时废止。"}],"shishiguojizhuzuoquantiaoyuedeguiding":[{"i":1,"n":"第一条","txt":"为实施国际著作权条约，保护外国作品著作权人的合法权益，制定本规定。"},{"i":2,"n":"第二条","txt":"对外国作品的保护，适用《中华人民共和国著作权法》（以下称著作权法）、《中华人民共和国著作权法实施条例》、《计算机软件保护条例》和本规定。"},{"i":3,"n":"第三条","txt":"本规定所称国际著作权条约，是指中华人民共和国（以下称中国）参加的《伯尔尼保护文学和艺术作品公约》（以下称伯尔尼公约）和与外国签订的有关著作权的双边协定。"},{"i":4,"n":"第四条","txt":"本规定所称外国作品，包括："},{"i":5,"n":"第五条","txt":"对未发表的外国作品的保护期，适用著作权法第二十条、第二十一条的规定。"},{"i":6,"n":"第六条","txt":"对外国实用艺术作品的保护期，为自该作品完成起二十五年。"},{"i":7,"n":"第七条","txt":"外国计算机程序作为文学作品保护，可以不履行登记手续，保护期为自该程序首次发表之年年底起五十年。"},{"i":8,"n":"第八条","txt":"外国作品是由不受保护的材料编辑而成，但是在材料的选取或者编排上有独创性的，依照著作权法第十四条的规定予以保护。此种保护不排斥他人利用同样的材料进行编辑。"},{"i":9,"n":"第九条","txt":"外国录像制品根据国际著作权条约构成电影作品的，作为电影作品保护。"},{"i":10,"n":"第十条","txt":"将外国人已经发表的以汉族文字创作的作品，翻译成少数民族文字出版发行的，应当事先取得著作权人的授权。"},{"i":11,"n":"第十一条","txt":"外国作品著作权人，可以授权他人以任何方式、手段公开表演其作品或者公开传播对其作品的表演。"},{"i":12,"n":"第十二条","txt":"外国电影、电视和录像作品的著作权人可以授权他人公开表演其作品。"},{"i":13,"n":"第十三条","txt":"报刊转载外国作品，应当事先取得著作权人的授权；但是，转载有关政治、经济等社会问题的时事文章除外。"},{"i":14,"n":"第十四条","txt":"外国作品的著作权人在授权他人发行其作品的复制品后，可以授权或者禁止出租其作品的复制品。"},{"i":15,"n":"第十五条","txt":"外国作品的著作权人有权禁止进口其作品的下列复制品："},{"i":16,"n":"第十六条","txt":"表演、录音或者广播外国作品，适用伯尔尼公约的规定；有集体管理组织的，应当事先取得该组织的授权。"},{"i":17,"n":"第十七条","txt":"国际著作权条约在中国生效之日尚未在起源国进入公有领域的外国作品，按照著作权法和本规定规定的保护期受保护，到期满为止。"},{"i":18,"n":"第十八条","txt":"本规定第五条、第十二条、第十四条、第十五条、第十七条适用于录音制品。"},{"i":19,"n":"第十九条","txt":"本规定施行前，有关著作权的行政法规与本规定有不同规定的，适用本规定。本规定与国际著作权条约有不同规定的，适用国际著作权条约。"},{"i":20,"n":"第二十条","txt":"国家版权局负责国际著作权条约在中国的实施。"},{"i":21,"n":"第二十一条","txt":"本规定由国家版权局负责解释。"},{"i":22,"n":"第二十二条","txt":"本规定自一九九二年九月三十日起施行。"}],"zhengshoujiaoyufeifujiadezanxingguiding":[{"i":1,"n":"第一条","txt":"为贯彻落实《中共中央关于教育体制改革的决定》，加快发展地方教育事业，扩大地方教育经费的资金来源，特制定本规定。"},{"i":2,"n":"第二条","txt":"凡缴纳消费税、增值税、营业税的单位和个人，除按照《国务院关于筹措农村学校办学经费的通知》（国发〔1984〕174号文）的规定，缴纳农村教育事业费附加的单位外，都应当依照本规定缴纳教育费附加。"},{"i":3,"n":"第三条","txt":"教育费附加，以各单位和个人实际缴纳的增值税、营业税、消费税的税额为计征依据，教育费附加率为3%，分别与增值税、营业税、消费税同时缴纳。"},{"i":4,"n":"第四条","txt":"依照现行有关规定，除铁道系统、中国人民银行总行、各专业银行总行、保险总公司的教育附加随同营业税上缴中央财政外，其余单位和个人的教育费附加，均就地上缴地方财政。"},{"i":5,"n":"第五条","txt":"教育费附加由税务机关负责征收。"},{"i":6,"n":"第六条","txt":"教育费附加的征收管理，按照消费税、增值税、营业税的有关规定办理。"},{"i":7,"n":"第七条","txt":"企业缴纳的教育费附加，一律在销售收入（或营业收入）中支付。"},{"i":8,"n":"第八条","txt":"地方征收的教育费附加，按专项资金管理，由教育部门统筹安排，提出分配方案，商同级财政部门同意后，用于改善中小学教学设施和办学条件，不得用于职工福利和发放奖金。"},{"i":9,"n":"第九条","txt":"地方各级教育部门每年应定期向当地人民政府、上级主管部门和财政部门，报告教育费附加的收支情况。"},{"i":10,"n":"第十条","txt":"凡办有职工子弟学校的单位，应当先按本规定缴纳教育费附加；教育部门可根据它们办学的情况酌情返还给办学单位，作为对所办学校经费的补贴。办学单位不得借口缴纳教育费附加而撤并学校，或者缩小办学规模。"},{"i":11,"n":"第十一条","txt":"征收教育费附加以后，地方各级教育部门和学校，不准以任何名目向学生家长和单位集资，或者变相集资，不准以任何借口不让学生入学。"},{"i":12,"n":"第十二条","txt":"本规定由财政部负责解释。各省、自治区、直辖市人民政府可结合当地实际情况制定实施办法。"},{"i":13,"n":"第十三条","txt":"本规定从1986年7月1日起施行。"}],"zhidaowaishangtouzifangxiangguiding":[{"i":1,"n":"第一条","txt":"为了指导外商投资方向，使外商投资方向与我国国民经济和社会发展规划相适应，并有利于保护投资者的合法权益，根据国家有关外商投资的法律规定和产业政策要求，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在我国境内投资举办中外合资经营企业、中外合作经营企业和外资企业（以下简称外商投资企业）的项目以及其他形式的外商投资项目（以下简称外商投资项目）。"},{"i":3,"n":"第三条","txt":"《外商投资产业指导目录》和《中西部地区外商投资优势产业目录》由国家发展计划委员会、国家经济贸易委员会、对外贸易经济合作部会同国务院有关部门制订，经国务院批准后公布；根据实际情况，需要对《外商投资产业指导目录》和《中西部地区外商投资优势产业目录》进行部分调整时，由国家经济贸易委员会、国家发展计划委员会、对外贸易经济合作部会同国务院有关部门适时修订并公布。"},{"i":4,"n":"第四条","txt":"外商投资项目分为鼓励、允许、限制和禁止四类。"},{"i":5,"n":"第五条","txt":"属于下列情形之一的，列为鼓励类外商投资项目："},{"i":6,"n":"第六条","txt":"属于下列情形之一的，列为限制类外商投资项目："},{"i":7,"n":"第七条","txt":"属于下列情形之一的，列为禁止类外商投资项目："},{"i":8,"n":"第八条","txt":"《外商投资产业指导目录》可以对外商投资项目规定“限于合资、合作”、“中方控股”或者“中方相对控股”。"},{"i":9,"n":"第九条","txt":"鼓励类外商投资项目，除依照有关法律、行政法规的规定享受优惠待遇外，从事投资额大、回收期长的能源、交通、城市基础设施（煤炭、石油、天然气、电力、铁路、公路、港口、机场、城市道路、污水处理、垃圾处理等）建设、经营的，经批准，可以扩大与其相关的经营范围。"},{"i":10,"n":"第十条","txt":"产品全部直接出口的允许类外商投资项目，视为鼓励类外商投资项目；产品出口销售额占其产品销售总额70%以上的限制类外商投资项目，经省、自治区、直辖市及计划单列市人民政府或者国务院主管部门批准，可以视为允许类外商投资项目。"},{"i":11,"n":"第十一条","txt":"对于确能发挥中西部地区优势的允许类和限制类外商投资项目，可以适当放宽条件；其中，列入《中西部地区外商投资优势产业目录》的，可以享受鼓励类外商投资项目优惠政策。"},{"i":12,"n":"第十二条","txt":"根据现行审批权限，外商投资项目按照项目性质分别由发展计划部门和经贸部门审批、备案；外商投资企业的合同、章程由外经贸部门审批、备案。其中，限制类限额以下的外商投资项目由省、自治区、直辖市及计划单列市人民政府的相应主管部门审批，同时报上级主管部门和行业主管部门备案，此类项目的审批权不得下放。属于服务贸易领域逐步开放的外商投资项目，按照国家有关规定审批。"},{"i":13,"n":"第十三条","txt":"对违反本规定审批的外商投资项目，上级审批机关应当自收到该项目的备案文件之日起30个工作日内予以撤销，其合同、章程无效，企业登记机关不予注册登记，海关不予办理进出口手续。"},{"i":14,"n":"第十四条","txt":"外商投资项目申请人以欺骗等不正当手段，骗取项目批准的，根据情节轻重，依法追究法律责任；审批机关应当撤销对该项目的批准，并由有关主管机关依法作出相应的处理。"},{"i":15,"n":"第十五条","txt":"审批机关工作人员滥用职权、玩忽职守的，依照刑法关于滥用职权罪、玩忽职守罪的规定，依法追究刑事责任；尚不够刑事处罚的，依法给予记大过以上的行政处分。"},{"i":16,"n":"第十六条","txt":"华侨和香港特别行政区、澳门特别行政区、台湾地区的投资者举办的投资项目，比照本规定执行。"},{"i":17,"n":"第十七条","txt":"本规定自2002年4月1日起施行。1995年6月7日国务院批准，1995年6月20日国家计划委员会、国家经济贸易委员会、对外贸易经济合作部发布的《指导外商投资方向暂行规定》同时废止。"}],"kongzhiduiqiyejinxingjingjijianchadeguiding":[{"i":1,"n":"第一条","txt":"为了规范行政机关对企业进行经济检查的行为，减轻企业负担，维护社会主义市场经济秩序，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称经济检查，是指行政机关对企业生产、经营活动遵守法律、法规情况进行的检查。"},{"i":3,"n":"第三条","txt":"除法律、法规明确规定外，任何行政机关不得擅自对企业进行经济检查。"},{"i":4,"n":"第四条","txt":"行政机关依照法律、法规对企业进行经济检查，应当统筹安排、注重效率、保证质量、避免重复。"},{"i":5,"n":"第五条","txt":"行政机关对企业进行经济检查，应当事先拟订检查计划。检查计划应当包括检查依据、检查时间、检查对象、检查事项等内容。"},{"i":6,"n":"第六条","txt":"同一行政机关对同一企业的经济检查每年一般不得超过一次；法律、行政法规和本规定另有规定的除外。"},{"i":7,"n":"第七条","txt":"税务机关对企业进行税务检查，应当按照归口管理、统一检查的原则，由国税机关、地税机关按照检查计划联合组织实施，省（自治区、直辖市）、市（州、盟）、县（旗）三级统筹协调。税务机关对同一企业的税务检查，每年不得超过两次。"},{"i":8,"n":"第八条","txt":"行政机关对企业进行经济检查时，应当出具检查通知书。检查通知书应当包括下列内容："},{"i":9,"n":"第九条","txt":"行政机关在对企业进行经济检查结束后，应当及时提出客观、真实、明确的检查报告，并报指定部门或者上级部门备案。指定部门或者上级部门应当根据情况，将检查报告抄送有关行政机关。"},{"i":10,"n":"第十条","txt":"行政机关对企业进行经济检查，除法律、法规、国务院及财政部、国家计委以及省、自治区、直辖市人民政府规定的收费项目外，不得向企业收取任何费用，也不得以任何形式将检查费用转嫁给企业。"},{"i":11,"n":"第十一条","txt":"行政机关的工作人员对企业进行经济检查时，不得接受被检查企业的任何馈赠、报酬、福利待遇，不得在被检查企业报销任何费用，不得参加被检查企业提供的宴请、娱乐、旅游等活动，不得通过检查工作为本人、亲友或者他人谋取利益。"},{"i":12,"n":"第十二条","txt":"行政机关有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予行政处分："},{"i":13,"n":"第十三条","txt":"行政机关的工作人员有下列行为之一的，依法给予警告直至开除的行政处分："},{"i":14,"n":"第十四条","txt":"对违反本规定对企业的经济检查，企业有权抵制，任何单位和个人有权向监察等有关部门检举。收到检举的部门应当负责保密并及时处理。"},{"i":15,"n":"第十五条","txt":"行政机关的工作人员对检举人进行报复陷害，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":16,"n":"第十六条","txt":"行政机关有理由认为企业存在违法行为或者违法嫌疑，依法进行调查的，不受本规定第四条、第五条、第六条、第七条、第八条、第九条的限制。"},{"i":17,"n":"第十七条","txt":"国务院决定、国务院有关部门经国务院批准决定或者省、自治区、直辖市人民政府决定进行的专项检查，分别按照国务院或者省、自治区、直辖市人民政府确定的专项检查的范围、内容、时限和程序进行。"},{"i":18,"n":"第十八条","txt":"各省、自治区、直辖市人民政府可以根据本规定制定实施办法。"},{"i":19,"n":"第十九条","txt":"其他行政机关对企业的检查，参照本规定执行。"},{"i":20,"n":"第二十条","txt":"本规定自发布之日起施行。"}],"canjirenzhuanyongpinmianzhengjinkoushuishouzanxing98388d":[{"i":1,"n":"第一条","txt":"为了支持残疾人康复工作，有利于残疾人专用品进口，制定本规定。"},{"i":2,"n":"第二条","txt":"进口下列残疾人专用品，免征进口关税和进口环节增值税、消费税："},{"i":3,"n":"第三条","txt":"有关单位进口的国内不能生产的下列残疾人专用品，按隶属关系经民政部或者中国残疾人联合会批准，并报海关总署审核后，免征进口关税和进口环节增值税、消费税："},{"i":4,"n":"第四条","txt":"本规定第三条规定的有关单位，是指："},{"i":5,"n":"第五条","txt":"依据本规定免税进口的残疾人专用品，不得擅自移作他用。"},{"i":6,"n":"第六条","txt":"海关总署根据本规定制定实施办法。"},{"i":7,"n":"第七条","txt":"本规定自发布之日起施行。"}],"minyonghangkongyunshubudingqifeixingguanlizanxinggf25f73":[{"i":1,"n":"第一条","txt":"为了维护国家航空权益，保证航空运输安全，促进民用航空运输的发展，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国领域内以及中华人民共和国和外国之间，从事运送旅客、行李、货物和邮件的中国和外国民用航空器的不定期飞行。"},{"i":3,"n":"第三条","txt":"本规定所称不定期飞行，是指不属于定期航班的民用航空运输飞行。"},{"i":4,"n":"第四条","txt":"从事不定期飞行，必须向国务院民用航空主管部门申请，经批准后方可飞行。申请和批准程序由国务院民用航空主管部门制定。"},{"i":5,"n":"第五条","txt":"从事不定期飞行，必须遵守国务院民用航空主管部门制定的运输规则，并不得影响定期航班的正常经营。"},{"i":6,"n":"第六条","txt":"从事不定期飞行的空勤人员和航空器，必须符合国务院民用航空主管部门规定的条件或技术标准，具备机组人员执照、航空器登记证、航空器适航证和按照有关规定应当携带的其他证件和文件。"},{"i":7,"n":"第七条","txt":"外国民用航空运输企业经营飞入或飞出中华人民共和国领域运输业务的不定期飞行，按照中华人民共和国政府和该外国政府签订的航空运输协定中有关规定办理。"},{"i":8,"n":"第八条","txt":"外国民用航空运输企业不得经营中华人民共和国领域内任何两点之间不定期飞行的运输业务。"},{"i":9,"n":"第九条","txt":"对外国民用航空运输企业经营取酬运输业务的不定期飞行，中国方面有权收取航空业务权补偿费。"},{"i":10,"n":"第十条","txt":"不定期民用航空运输价格实行市场调节价，由航空运输企业自主制定。"},{"i":11,"n":"第十一条","txt":"除经国务院民用航空主管部门特准者外，从事非取酬的不定期飞行的外国航空器，只能飞抵中华人民共和国领域内的一个指定地点，并不得载运非该航空器的原载人员或者原载货物飞出中华人民共和国领域，也不得将原载人员或者原载货物留在中华人民共和国领域内。"},{"i":12,"n":"第十二条","txt":"从事国际运输的不定期飞行的航空器，必须按照中华人民共和国有关规定办理边防、海关、卫生检疫和安全检查等项手续，并按规定缴付费用。"},{"i":13,"n":"第十三条","txt":"从事不定期飞行的外国航空器及其机组成员和所载旅客、行李、货物和邮件进出中华人民共和国领域和在中华人民共和国领域内，必须遵守中华人民共和国有关法律、法规和规章，并按规定缴付各项费用。"},{"i":14,"n":"第十四条","txt":"从事不定期飞行的外国航空器的经营人，必须投保该航空器在中华人民共和国领域内飞行时对地面第三者造成损害的责任险；如果从事运送旅客、行李、货物和邮件的不定期飞行，还必须投保法定责任险。"},{"i":15,"n":"第十五条","txt":"对违反本规定的单位或者个人，国务院民用航空主管部门有权给予警告、罚款、勒令中止飞行或者吊销有关证件的处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本规定自发布之日起施行。"}],"faguihuibianbianjichubanguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对法规汇编编辑出版工作的管理，提高法规汇编编辑出版质量，维护社会主义法制的统一和尊严，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称法规汇编，是指将依照法定程序发布的法律、行政法规、国务院部门规章（下称部门规章）、地方性法规和地方政府规章，按照一定的顺序或者分类汇编成册的公开出版物。"},{"i":3,"n":"第三条","txt":"除法律、行政法规另有规定外，编辑出版法规汇编（包括法规选编、类编、大全等）应当遵守本规定。"},{"i":4,"n":"第四条","txt":"编辑法规汇编，遵守下列分工："},{"i":5,"n":"第五条","txt":"根据工作、学习、教学、研究需要，有关机关、团体、企业事业组织可以自行或者委托精通法律的专业人员编印供内部使用的法规汇集；需要正式出版的，应当经出版行政管理部门核准。"},{"i":6,"n":"第六条","txt":"编辑法规汇编，应当做到："},{"i":7,"n":"第七条","txt":"出版法规汇编，国家出版行政管理部门根据出版专业分工规定的原则，依照下列分工予以审核批准："},{"i":8,"n":"第八条","txt":"国家出版的民族文版和外文版的法律汇编，由全国人民代表大会常务委员会法制工作委员会组织或者协助审定。"},{"i":9,"n":"第九条","txt":"符合第七条规定的出版社应当制定法规汇编的出版选题计划，分别报有权编辑法规汇编的机关和出版行政管理部门备案。"},{"i":10,"n":"第十条","txt":"按照本规定第四条编辑的法规汇编，可以在汇编封面上加印国徽；按照本规定第五条第一款编印的法规汇集，不得在汇集封面上加印国徽。"},{"i":11,"n":"第十一条","txt":"出版法规汇编，必须保证印制质量。质量标准要符合国家有关规定。"},{"i":12,"n":"第十二条","txt":"法规汇编的发行，由新华书店负责，各地新华书店应当认真做好征订工作。"},{"i":13,"n":"第十三条","txt":"违反本规定，擅自出版法规汇编的，根据不同情况出版行政管理部门或者工商行政管理部门依照职权划分可以给予当事人下列行政处罚："},{"i":14,"n":"第十四条","txt":"当事人对出版行政管理部门或者工商行政管理部门的处罚决定不服的，可以在收到处罚通知书之日起十五日内，向上一级出版行政管理部门或者工商行政管理部门申请复议。对复议决定仍然不服的，可以自收到复议决定通知书之日起十五日内向人民法院提起诉讼。当事人也可以自收到处罚通知书之日起十五日内，直接向人民法院提起诉讼。逾期不申请复议也不提起诉讼又不履行处罚决定的，作出处罚决定的机关可以申请人民法院强制执行。"},{"i":15,"n":"第十五条","txt":"与境外出版机构合作出版法规汇编事宜，参照本规定办理。"},{"i":16,"n":"第十六条","txt":"法规文件信息化处理的开发、应用，参照本规定管理。"},{"i":17,"n":"第十七条","txt":"本规定自发布之日起施行。"}],"haiguangongzuorenyuanshiyongwuqihejingxiedeguiding":[{"i":1,"n":"第一条","txt":"为保证海关工作人员依法使用武器和警械，履行职责，根据《中华人民共和国海关法》第六条的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"海关工作人员使用的武器和警械，经当地公安机关同意后由海关总署统一配发。海关工作人员执行缉私任务时，应当依照本规定使用武器和警械。"},{"i":3,"n":"第三条","txt":"配发给海关的武器和警械一律公用，不配发个人专用的武器和警械。"},{"i":4,"n":"第四条","txt":"海关工作人员执行缉私任务，遇有下列情形之一的，可以开枪射击："},{"i":5,"n":"第五条","txt":"海关工作人员执行缉私任务，遇有下列情形之一的，可以使用警械："},{"i":6,"n":"第六条","txt":"海关工作人员使用武器或者警械时，应当以制服对方为限度。海关工作人员依照本规定第四条的规定开枪射击时，除特别紧迫的情况外，应当先口头警告或者鸣枪警告，对方一有畏服表现，应当立即停止射击。开枪射击造成人员伤亡的，应当保护现场，并立即向上级海关和当地公安机关报告。"},{"i":7,"n":"第七条","txt":"海关工作人员违反本规定，滥用武器或者警械的，应当根据情节，依法追究有关人员的责任。"},{"i":8,"n":"第八条","txt":"本规定自发布之日起施行。"}],"shiyoudizhenkantansunhaibuchangguiding":[{"i":1,"n":"第一条","txt":"为了做好石油地震勘探损害补偿工作，正确处理国家、集体、个人三者利益关系，确保石油勘探工作的顺利进行，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国陆地（包括岛屿、海滩、水深五米的浅海在内）石油地震勘探作业和作业地震波的损害补偿。"},{"i":3,"n":"第三条","txt":"石油地震勘探是沿一定测线通过式作业，在测线每个观测点上通过时间不超过四十八小时，在特殊情况下不超过九十六小时的，免于办理临时用地手续。"},{"i":4,"n":"第四条","txt":"石油地震勘探按照实际损害程度由地震作业队给予受损害的个人或者单位一次性补偿，补偿费用应当及时支付。任何单位或者个人不得截留、回扣补偿费用，或者向地震作业队索要补偿费用之外的费用或者实物。"},{"i":5,"n":"第五条","txt":"地震作业队的主管部门，应当在开工前三十日内将本年度的石油地震勘探施工设计和作业计划向作业区所在地的县级人民政府有关主管部门报告，取得支持和帮助。县级人民政府有关主管部门应当在地震作业队作业前将作业区的地面、地下设施、农田作物等有关资料提供给地震作业队主管部门。"},{"i":6,"n":"第六条","txt":"地震作业队的作业，应当按照国家有关规定在城市区、工矿区、居民点、车站、码头、港口、铁路、军用基地、人防工程、大中型桥涵、水利工程、电力设施、输油输气管线、国家测量标志、重点文物、通讯设施、广播设施的安全距离之外放炮。特殊情况下，如需在上述安全距离内放炮作业，地震作业队应当征得有关部门同意，采取安全措施后，方可施工。"},{"i":7,"n":"第七条","txt":"当事人双方对石油地震勘探损害补偿问题发生纠纷时，首先应当协商解决，协商不成的，提请当地县级人民政府及其指定的部门调解处理；对调解处理决定不服的，任何一方可在接到处理决定之日起十五日内向所在地人民法院起诉，但在调解和诉讼期间，应当保证地震作业队正常作业。"},{"i":8,"n":"第八条","txt":"石油地震勘探作业（以下简称地震作业）车辆沿测线通过农田，对粮食作物和其他经济作物造成损害的，作物受害量以当地县级人民政府统计部门前三年上报国家产量的年平均数、实际损害面积和实际损害程度计算；作物补偿价格按国家规定的价格和当地市场价格的加权平均值计算，其加权平均值参照定购合同等因素，由双方协商确定，作业车辆损害农田面积以实际碾压宽度和长度计算。"},{"i":9,"n":"第九条","txt":"地震作业车辆沿测线通过造成的农田地面设施损害，根据实际损害程度，由双方协商，给予适当补偿。"},{"i":10,"n":"第十条","txt":"地震作业对封冻期的青苗损害的补偿标准，按作业车辆实际碾压损害程度确定，一般不超过对该地非封冻期作物损害补偿标准的百分之三十，但个别地方青苗碾压严重的，经当事人双方认定，可酌情提高补偿标准。封冻期的具体期限由当地省级以上人民政府确定。"},{"i":11,"n":"第十一条","txt":"地震作业对无封冻期的已耕待种地造成损害的，应按照作业车辆实际碾压面积，参照当地劳务费用和机耕费用的标准补偿复耕费。"},{"i":12,"n":"第十二条","txt":"地震作业对牧区人工种植的草场造成损害的，应按照草场实际损害面积和亩产量，及当地省级人民政府规定的牧草收购价格，予以补偿。"},{"i":13,"n":"第十三条","txt":"地震作业对竹木造成损害的，应对实际损害株数逐株计算，进行补偿。竹木补偿标准由当地省级人民政府确定，被损竹木归原竹木所有者。"},{"i":14,"n":"第十四条","txt":"地震作业后的炮眼，应当由地震作业队负责回填。地震作业队不回填的，应按照当地省级人民政府规定的标准，支付炮眼回填劳务费。"},{"i":15,"n":"第十五条","txt":"地震作业队井中放炮，对其地震作业地震波（以下简称地震波）造成损害的补偿范围规定如下："},{"i":16,"n":"第十六条","txt":"在地震波损害的补偿范围内的地面设施，根据地震作业放炮后所造成的损害的程度，参考原造价和使用年限计算补偿费用，予以补偿。"},{"i":17,"n":"第十七条","txt":"对地震波损害补偿范围内的机井的损害补偿，由当事人双方共同核实损害程度，并参照当地县级人民政府有关部门提供的机井档案资料、造价、使用年限，计算补偿费用予以补偿。"},{"i":18,"n":"第十八条","txt":"在海滩和浅海区进行地震作业，应当采用非炸药震源；在陆地进行地震作业，应当尽量避开鱼塘或养殖场。"},{"i":19,"n":"第十九条","txt":"地震作业队在没有种植农作物的荒岭、荒坡、荒地、荒漠，以及封冻期的无种植耕地、草原进行石油勘探地震作业的，不予补偿，但对作业区的耕地应当负责复垦，恢复利用。"},{"i":20,"n":"第二十条","txt":"地震作业队在国家和集体所有的闲置地，没有承包的沙滩、沙漠、河滩、湖滩、海滩、森林中的空地进行地震作业的，不予补偿。"},{"i":21,"n":"第二十一条","txt":"地震作业队主管部门向地震作业区所在地人民政府提交作业计划后，任何单位和个人故意在作业线上抢种作物、苗木和突击设置地面设施的，其在地震作业后受到损害的，地震作业队不予补偿。"},{"i":22,"n":"第二十二条","txt":"地震作业队违反第六条规定，擅自在安全距离内放炮的，应当根据国家有关法律、法规由有关部门对地震作业队责任人员追究行政责任或民事责任；对情节严重构成犯罪的，依法追究其刑事责任。"},{"i":23,"n":"第二十三条","txt":"有下列行为之一的单位和个人，视其情节轻重，由当地人民政府有关部门依法给予行政处罚，并责令其赔偿造成的损失；构成犯罪的，由司法部门依法追究刑事责任："},{"i":24,"n":"第二十四条","txt":"违反第四条规定，截留、回扣补偿费用的单位和个人，由监察部门责令其退回被截留、回扣的补偿费用，并可予以行政处罚。"},{"i":25,"n":"第二十五条","txt":"其它行业和部门因地震勘探作业所造成的损害，可参照本规定进行补偿。"},{"i":26,"n":"第二十六条","txt":"本规定由国务院石油工业主管部门负责解释。"},{"i":27,"n":"第二十七条","txt":"本规定自发布之日起施行。"}],"jinzhishiyongtonggongguiding":[{"i":1,"n":"第一条","txt":"为保护未成年人的身心健康，促进义务教育制度的实施，维护未成年人的合法权益，根据宪法和劳动法、未成年人保护法，制定本规定。"},{"i":2,"n":"第二条","txt":"国家机关、社会团体、企业事业单位、民办非企业单位或者个体工商户（以下统称用人单位）均不得招用不满16周岁的未成年人（招用不满16周岁的未成年人，以下统称使用童工）。"},{"i":3,"n":"第三条","txt":"不满16周岁的未成年人的父母或者其他监护人应当保护其身心健康，保障其接受义务教育的权利，不得允许其被用人单位非法招用。"},{"i":4,"n":"第四条","txt":"用人单位招用人员时，必须核查被招用人员的身份证；对不满16周岁的未成年人，一律不得录用。用人单位录用人员的录用登记、核查材料应当妥善保管。"},{"i":5,"n":"第五条","txt":"县级以上各级人民政府劳动保障行政部门负责本规定执行情况的监督检查。"},{"i":6,"n":"第六条","txt":"用人单位使用童工的，由劳动保障行政部门按照每使用一名童工每月处5000元罚款的标准给予处罚；在使用有毒物品的作业场所使用童工的，按照《使用有毒物品作业场所劳动保护条例》规定的罚款幅度，或者按照每使用一名童工每月处5000元罚款的标准，从重处罚。劳动保障行政部门并应当责令用人单位限期将童工送回原居住地交其父母或者其他监护人，所需交通和食宿费用全部由用人单位承担。"},{"i":7,"n":"第七条","txt":"单位或者个人为不满16周岁的未成年人介绍就业的，由劳动保障行政部门按照每介绍一人处5000元罚款的标准给予处罚；职业中介机构为不满16周岁的未成年人介绍就业的，并由劳动保障行政部门吊销其职业介绍许可证。"},{"i":8,"n":"第八条","txt":"用人单位未按照本规定第四条的规定保存录用登记材料，或者伪造录用登记材料的，由劳动保障行政部门处1万元的罚款。"},{"i":9,"n":"第九条","txt":"无营业执照、被依法吊销营业执照的单位以及未依法登记、备案的单位使用童工或者介绍童工就业的，依照本规定第六条、第七条、第八条规定的标准加一倍罚款，该非法单位由有关的行政主管部门予以取缔。"},{"i":10,"n":"第十条","txt":"童工患病或者受伤的，用人单位应当负责送到医疗机构治疗，并负担治疗期间的全部医疗和生活费用。"},{"i":11,"n":"第十一条","txt":"拐骗童工，强迫童工劳动，使用童工从事高空、井下、放射性、高毒、易燃易爆以及国家规定的第四级体力劳动强度的劳动，使用不满14周岁的童工，或者造成童工死亡或者严重伤残的，依照刑法关于拐卖儿童罪、强迫劳动罪或者其他罪的规定，依法追究刑事责任。"},{"i":12,"n":"第十二条","txt":"国家行政机关工作人员有下列行为之一的，依法给予记大过或者降级的行政处分；情节严重的，依法给予撤职或者开除的行政处分；构成犯罪的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任："},{"i":13,"n":"第十三条","txt":"文艺、体育单位经未成年人的父母或者其他监护人同意，可以招用不满16周岁的专业文艺工作者、运动员。用人单位应当保障被招用的不满16周岁的未成年人的身心健康，保障其接受义务教育的权利。文艺、体育单位招用不满16周岁的专业文艺工作者、运动员的办法，由国务院劳动保障行政部门会同国务院文化、体育行政部门制定。"},{"i":14,"n":"第十四条","txt":"本规定自2002年12月1日起施行。1991年4月15日国务院发布的《禁止使用童工规定》同时废止。"}],"jiehuishouhuijifuhuiguanliguiding":[{"i":1,"n":"第一条","txt":"为规范结汇、售汇及付汇行为，实现人民币在经常项目下可兑换，特制定本规定。"},{"i":2,"n":"第二条","txt":"经营外汇业务的银行应当按照本规定和中国人民银行、国家外汇管理局批准的业务范围办理结汇、售汇、开立外汇账户及对外支付业务。"},{"i":3,"n":"第三条","txt":"境内机构外汇收入，除国家另有规定外应当及时调回境内。"},{"i":4,"n":"第四条","txt":"境内机构、居民个人、驻华机构及来华人员应当按照本规定办理结汇、购汇、开立外汇账户及对外支付。"},{"i":5,"n":"第五条","txt":"境内机构和居民个人通过经营外汇业务的银行办理对外收支时，应当按照《国际收支统计申报办法》及有关规定办理国际收支统计申报。"},{"i":6,"n":"第六条","txt":"除本规定第七条、第八条、第十条限定的范围和数量外，境内机构取得的下列外汇应当结汇："},{"i":7,"n":"第七条","txt":"境内机构（不含外商投资企业）的下列外汇，可以向国家外汇管理局及其分支局（以下简称“外汇局”）申请，在经营外汇业务的银行开立外汇账户，按照规定办理结汇："},{"i":8,"n":"第八条","txt":"捐赠、资助及援助合同规定用于境外支付的外汇，经外汇局批准后方可保留。"},{"i":9,"n":"第九条","txt":"下列范围的外汇，可以保留："},{"i":10,"n":"第十条","txt":"外商投资企业经常项目下外汇收入可在外汇局核定的最高金额以内保留外汇，超出部分应当卖给外汇指定银行，或者通过外汇调剂中心卖出。"},{"i":11,"n":"第十一条","txt":"超过等值1万美元的现钞结汇，结汇人应当向外汇指定银行提供真实的身份证明和外汇来源证明，外汇指定银行予以结汇登记后报外汇局备案。"},{"i":12,"n":"第十二条","txt":"本规定第七、八、九、十条允许开立外汇账户的境内机构和居民个人、驻华机构及来华人员，应当按照外汇账户管理的有关规定，到经营外汇业务的银行办理开户手续。"},{"i":13,"n":"第十三条","txt":"境内机构下列贸易及非贸易经营性对外支付用汇，持与支付方式相应的有效商业单据和所列有效凭证从其外汇账户中支付或者到外汇指定银行兑付："},{"i":14,"n":"第十四条","txt":"境内机构下列贸易及非贸易经营性对外支付，经营外汇业务的银行凭用户提供的支付清单先从其外汇账户中支付或者兑付，事后核查："},{"i":15,"n":"第十五条","txt":"境内机构下列对外支付用汇，由外汇局审核其真实性后，从其外汇账户中支付或者到外汇指定银行兑付："},{"i":16,"n":"第十六条","txt":"境内机构偿还境内中资金融机构外汇贷款利息，持《外汇（转）贷款登记证》、借贷合同及债权人的付息通知单，从其外汇账户中支付或者到外汇指定银行兑付。"},{"i":17,"n":"第十七条","txt":"财政预算内的机关、事业单位和社会团体的非贸易非经营性用汇，按照《非贸易非经营性外汇财务管理暂行规定》办理。"},{"i":18,"n":"第十八条","txt":"财政预算外的境内机构下列非经营性用汇，持所列有效凭证从其外汇账户中支付或者到外汇指定银行兑付："},{"i":19,"n":"第十九条","txt":"居民个人的因私用汇，按照《境内居民因私兑换外汇办法》和《境内居民外汇存款汇出境外的规定》办理。"},{"i":20,"n":"第二十条","txt":"居民个人移居出境后，下列合法人民币收益，持本人身份证明和所列有效凭证到外汇局授权的外汇指定银行兑付："},{"i":21,"n":"第二十一条","txt":"外商投资企业外方投资者依法纳税后的利润、红利的汇出，持董事会利润分配决议书，从其外汇账户中支付或者到外汇指定银行兑付。"},{"i":22,"n":"第二十二条","txt":"按照规定应当以外币支付的股息，依法纳税后持董事会利润分配决议书从其外汇账户中支付或者到外汇指定银行兑付。"},{"i":23,"n":"第二十三条","txt":"驻华机构及来华人员的合法人民币收入，需汇出境外时，持证明材料和收费清单到外汇局授权的外汇指定银行兑付。"},{"i":24,"n":"第二十四条","txt":"驻华机构及来华人员从境外携入或者在境内购买的自用物品、设备、用具等，出售后所得人民币款项，需汇出境外时，持工商登记证或者本人身份证明和出售凭证到外汇局授权的外汇指定银行兑付。"},{"i":25,"n":"第二十五条","txt":"临时来华的外国人、华侨、港澳台同胞出境时未用完的人民币，可以凭本人护照、原兑换水单（有效期为6个月）兑回外汇，携出境外。"},{"i":26,"n":"第二十六条","txt":"境内机构资本项目下的外汇应当在经营外汇业务的银行开立外汇账户。"},{"i":27,"n":"第二十七条","txt":"境内机构下列范围内的外汇，未经外汇局批准，不得结汇："},{"i":28,"n":"第二十八条","txt":"境内机构向境外出售房地产及其他资产收入的外汇，除本规定第十条限定的数额外应当卖给外汇指定银行。"},{"i":29,"n":"第二十九条","txt":"境内机构偿还境内中资金融机构外汇贷款本金，持《外汇（转）贷款登记证》、借贷合同及债权机构的还本通知单，从其外汇账户中支付或者到外汇指定银行兑付。"},{"i":30,"n":"第三十条","txt":"境内机构资本项目下的下列用汇，持所列有效凭证向外汇局申请，凭外汇局的核准件从其外汇账户中支付或者到外汇指定银行兑付："},{"i":31,"n":"第三十一条","txt":"外商投资企业的外汇资本金的增加、转让或者以其他方式处置，持董事会决议，经外汇局核准后，从其外汇账户中支付或者持外汇局核发的售汇通知单到外汇指定银行兑付。"},{"i":32,"n":"第三十二条","txt":"外商投资企业可以在外汇指定银行办理结汇和售汇，也可以在外汇调剂中心买卖外汇，其他境内机构、居民个人、驻华机构及来华人员只能在外汇指定银行办理结汇和售汇。"},{"i":33,"n":"第三十三条","txt":"从外汇账户中对外支付时，经营外汇业务的银行应当根据规定的外汇账户收支范围及本规定第二、三章相应的规定进行审核，办理支付。"},{"i":34,"n":"第三十四条","txt":"外汇指定银行办理售汇和付汇后，应当在相应的有效凭证和有效商业单据上签章后留存备查。"},{"i":35,"n":"第三十五条","txt":"外汇指定银行应当根据中国人民银行每日公布的人民币汇率中间价和规定的买卖差价幅度，确定对客户的外汇买卖价格，办理结汇和售汇业务。"},{"i":36,"n":"第三十六条","txt":"从外汇账户中支付或者购汇支付，应当在有关结算方式或者合同规定的日期办理，不得提前对外付款；除用于还本付息的外汇和信用证/保函保证金外，不得提前购汇。"},{"i":37,"n":"第三十七条","txt":"为使有远期支付合同或者偿债协议的用汇单位避免汇率风险，外汇指定银行可以按照有关规定为其办理人民币与外币的远期买卖及其他保值业务。"},{"i":38,"n":"第三十八条","txt":"易货贸易项下进口，未经外汇局批准，不得购汇或者从外汇账户支付。"},{"i":39,"n":"第三十九条","txt":"经营外汇业务的银行应当按照规定向外汇局报送结汇、售汇及付汇情况报表。"},{"i":40,"n":"第四十条","txt":"境内机构应当在其注册地选择经营外汇业务的银行开立外汇账户、按照本规定办理结汇、购汇、付汇业务。境内机构在异地和境外开立外汇账户，应当向外汇局申请。"},{"i":41,"n":"第四十一条","txt":"经营外汇业务的银行和有结汇、购汇、付汇业务的境内机构，应当无条件接受外汇局的监督、检查，并出示、提供有关材料。对违反本规定的，外汇局可对其处以警告、没收违法所得、罚款的处罚；对违反本规定，情节严重的经营外汇业务的银行，外汇局可对其处以暂停结售汇业务的处罚。"},{"i":42,"n":"第四十二条","txt":"本规定由国家外汇管理局负责解释。"},{"i":43,"n":"第四十三条","txt":"本规定自1996年7月1日起施行。1994年3月26日发布的《结汇、售汇及付汇管理暂行规定》同时废止。其他规定与本规定相抵触的，以本规定为准。"}],"xingzhengzhifajiguanyisongshexianfanzuianjiandegui919a5e":[{"i":1,"n":"第一条","txt":"为了保证行政执法机关向公安机关及时移送涉嫌犯罪案件，依法惩罚破坏社会主义市场经济秩序罪、妨害社会管理秩序罪以及其他罪，保障社会主义建设事业顺利进行，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称行政执法机关，是指依照法律、法规或者规章的规定，对破坏社会主义市场经济秩序、妨害社会管理秩序以及其他违法行为具有行政处罚权的行政机关，以及法律、法规授权的具有管理公共事务职能、在法定授权范围内实施行政处罚的组织。"},{"i":3,"n":"第三条","txt":"行政执法机关在依法查处违法行为过程中，发现违法事实涉及的金额、违法事实的情节、违法事实造成的后果等，根据刑法关于破坏社会主义市场经济秩序罪、妨害社会管理秩序罪等罪的规定和最高人民法院、最高人民检察院关于破坏社会主义市场经济秩序罪、妨害社会管理秩序罪等罪的司法解释以及最高人民检察院、公安部关于经济犯罪案件的追诉标准等规定，涉嫌构成犯罪，依法需要追究刑事责任的，必须依照本规定向公安机关移送。"},{"i":4,"n":"第四条","txt":"行政执法机关在查处违法行为过程中，必须妥善保存所收集的与违法行为有关的证据。"},{"i":5,"n":"第五条","txt":"行政执法机关对应当向公安机关移送的涉嫌犯罪案件，应当立即指定2名或者2名以上行政执法人员组成专案组专门负责，核实情况后提出移送涉嫌犯罪案件的书面报告，报经本机关正职负责人或者主持工作的负责人审批。"},{"i":6,"n":"第六条","txt":"行政执法机关向公安机关移送涉嫌犯罪案件，应当附有下列材料："},{"i":7,"n":"第七条","txt":"公安机关对行政执法机关移送的涉嫌犯罪案件，应当在涉嫌犯罪案件移送书的回执上签字；其中，不属于本机关管辖的，应当在24小时内转送有管辖权的机关，并书面告知移送案件的行政执法机关。"},{"i":8,"n":"第八条","txt":"公安机关应当自接受行政执法机关移送的涉嫌犯罪案件之日起3日内，依照刑法、刑事诉讼法以及最高人民法院、最高人民检察院关于立案标准和公安部关于公安机关办理刑事案件程序的规定，对所移送的案件进行审查。认为有犯罪事实，需要追究刑事责任，依法决定立案的，应当书面通知移送案件的行政执法机关；认为没有犯罪事实，或者犯罪事实显著轻微，不需要追究刑事责任，依法不予立案的，应当说明理由，并书面通知移送案件的行政执法机关，相应退回案卷材料。"},{"i":9,"n":"第九条","txt":"行政执法机关接到公安机关不予立案的通知书后，认为依法应当由公安机关决定立案的，可以自接到不予立案通知书之日起3日内，提请作出不予立案决定的公安机关复议，也可以建议人民检察院依法进行立案监督。"},{"i":10,"n":"第十条","txt":"行政执法机关对公安机关决定不予立案的案件，应当依法作出处理；其中，依照有关法律、法规或者规章的规定应当给予行政处罚的，应当依法实施行政处罚。"},{"i":11,"n":"第十一条","txt":"行政执法机关对应当向公安机关移送的涉嫌犯罪案件，不得以行政处罚代替移送。"},{"i":12,"n":"第十二条","txt":"行政执法机关对公安机关决定立案的案件，应当自接到立案通知书之日起3日内将涉案物品以及与案件有关的其他材料移交公安机关，并办结交接手续；法律、行政法规另有规定的，依照其规定。"},{"i":13,"n":"第十三条","txt":"公安机关对发现的违法行为，经审查，没有犯罪事实，或者立案侦查后认为犯罪事实显著轻微，不需要追究刑事责任，但依法应当追究行政责任的，应当及时将案件移送同级行政执法机关，有关行政执法机关应当依法作出处理。"},{"i":14,"n":"第十四条","txt":"行政执法机关移送涉嫌犯罪案件，应当接受人民检察院和监察机关依法实施的监督。"},{"i":15,"n":"第十五条","txt":"行政执法机关违反本规定，隐匿、私分、销毁涉案物品的，由本级或者上级人民政府，或者实行垂直管理的上级行政执法机关，对其正职负责人根据情节轻重，给予降级以上的处分；构成犯罪的，依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"行政执法机关违反本规定，逾期不将案件移送公安机关的，由本级或者上级人民政府，或者实行垂直管理的上级行政执法机关，责令限期移送，并对其正职负责人或者主持工作的负责人根据情节轻重，给予记过以上的处分；构成犯罪的，依法追究刑事责任。"},{"i":17,"n":"第十七条","txt":"公安机关违反本规定，不接受行政执法机关移送的涉嫌犯罪案件，或者逾期不作出立案或者不予立案的决定的，除由人民检察院依法实施立案监督外，由本级或者上级人民政府责令改正，对其正职负责人根据情节轻重，给予记过以上的处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"有关机关存在本规定第十五条、第十六条、第十七条所列违法行为，需要由监察机关依法给予违法的公职人员政务处分的，该机关及其上级主管机关或者有关人民政府应当依照有关规定将相关案件线索移送监察机关处理。"},{"i":19,"n":"第十九条","txt":"行政执法机关在依法查处违法行为过程中，发现公职人员有贪污贿赂、失职渎职或者利用职权侵犯公民人身权利和民主权利等违法行为，涉嫌构成职务犯罪的，应当依照刑法、刑事诉讼法、监察法等法律规定及时将案件线索移送监察机关或者人民检察院处理。"},{"i":20,"n":"第二十条","txt":"本规定自公布之日起施行。"}],"weifanxingzhengshiyexingshoufeihefamoshourushouzhi4fb49f":[{"i":1,"n":"第一条","txt":"为了严肃财经纪律，加强廉政建设，落实行政事业性收费和罚没收入“收支两条线”管理，促进依法行政，根据法律、行政法规和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"国家公务员和法律、行政法规授权行使行政事业性收费或者罚没职能的事业单位的工作人员有违反“收支两条线”管理规定行为的，依照本规定给予行政处分。"},{"i":3,"n":"第三条","txt":"本规定所称“行政事业性收费”，是指下列属于财政性资金的收入："},{"i":4,"n":"第四条","txt":"本规定所称“罚没收入”，是指法律、行政法规授权的执行处罚的部门依法实施处罚取得的罚没款和没收物品的折价收入。"},{"i":5,"n":"第五条","txt":"违反规定，擅自设立行政事业性收费项目或者设置罚没处罚的，对直接负责的主管人员和其他直接责任人员给予降级或者撤职处分。"},{"i":6,"n":"第六条","txt":"违反规定，擅自变更行政事业性收费或者罚没范围、标准的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节严重的，给予降级或者撤职处分。"},{"i":7,"n":"第七条","txt":"对行政事业性收费项目审批机关已经明令取消或者降低标准的收费项目，仍按原定项目或者标准收费的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节严重的，给予降级或者撤职处分。"},{"i":8,"n":"第八条","txt":"下达或者变相下达罚没指标的，对直接负责的主管人员和其他直接责任人员给予降级或者撤职处分。"},{"i":9,"n":"第九条","txt":"违反《收费许可证》规定实施行政事业性收费的，对直接负责的主管人员和其他直接责任人员给予警告处分；情节严重的，给予记过或者记大过处分。"},{"i":10,"n":"第十条","txt":"违反财政票据管理规定实施行政事业性收费、罚没的，对直接负责的主管人员和其他直接责任人员给予降级或者撤职处分；以实施行政事业性收费、罚没的名义收取钱物，不出具任何票据的，给予开除处分。"},{"i":11,"n":"第十一条","txt":"违反罚款决定与罚款收缴分离的规定收缴罚款的，对直接负责的主管人员和其他直接责任人员给予记大过或者降级处分。"},{"i":12,"n":"第十二条","txt":"不履行行政事业性收费、罚没职责，应收不收、应罚不罚，经批评教育仍不改正的，对直接负责的主管人员和其他直接责任人员给予警告处分；情节严重的，给予记过或者记大过处分。"},{"i":13,"n":"第十三条","txt":"不按照规定将行政事业性收费纳入单位财务统一核算、管理的，对直接负责的主管人员和其他直接责任人员给予记过处分；情节严重的，给予记大过或者降级处分。"},{"i":14,"n":"第十四条","txt":"不按照规定将行政事业性收费缴入国库或者预算外资金财政专户的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节严重的，给予降级或者撤职处分。"},{"i":15,"n":"第十五条","txt":"违反规定，擅自开设银行帐户的，对直接负责的主管人员和其他直接责任人员给予降级处分；情节严重的，给予撤职或者开除处分。"},{"i":16,"n":"第十六条","txt":"截留、挪用、坐收坐支行政事业性收费、罚没收入的，对直接负责的主管人员和其他直接责任人员给予降级处分；情节严重的，给予撤职或者开除处分。"},{"i":17,"n":"第十七条","txt":"违反规定，将行政事业性收费、罚没收入用于提高福利补贴标准或者扩大福利补贴范围、滥发奖金实物、挥霍浪费或者有其他超标准支出行为的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节严重的，给予降级或者撤职处分。"},{"i":18,"n":"第十八条","txt":"不按照规定编制预算外资金收支计划、单位财务收支计划和收支决算的，对直接负责的主管人员和其他直接责任人员给予记过处分；情节严重的，给予记大过或者降级处分。"},{"i":19,"n":"第十九条","txt":"不按照预算和批准的收支计划核拨财政资金，贻误核拨对象正常工作的，对直接负责的主管人员和其他直接责任人员给予记过处分；情节严重的，给予记大过或者降级处分。"},{"i":20,"n":"第二十条","txt":"对坚持原则抵制违法违纪的行政事业性收费、罚没行为的单位或者个人打击报复的，给予降级处分；情节严重的，给予撤职或者开除处分。"},{"i":21,"n":"第二十一条","txt":"实施行政处分的权限以及不服行政处分的申诉，按照国家有关规定办理。"},{"i":22,"n":"第二十二条","txt":"违反本规定，构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"本规定自发布之日起施行。"}],"pushehaididianlanguandaoguanliguiding":[{"i":1,"n":"第一条","txt":"为维护中华人民共和国国家主权和权益，合理开发利用海洋，有秩序地铺设和保护海底电缆、管道，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于在中华人民共和国内海、领海及大陆架上铺设海底电缆、管道以及为铺设所进行的路由调查、勘测及其他有关活动。"},{"i":3,"n":"第三条","txt":"在中华人民共和国内海、领海及大陆架上铺设海底电缆、管道以及为铺设所进行的路由调查、勘测及其他有关活动的主管机关是中华人民共和国国家海洋局（以下简称主管机关）。"},{"i":4,"n":"第四条","txt":"中国的企业、事业单位铺设海底电缆、管道，经其上级业务主管部门审批同意后，为铺设所进行的路由调查、勘测等活动，依照本规定执行。"},{"i":5,"n":"第五条","txt":"海底电缆、管道所有者（以下简称所有者），须在为铺设所进行的路由调查、勘测实施60天前，向主管机关提出书面申请。申请书应当包括以下内容："},{"i":6,"n":"第六条","txt":"海底电缆、管道路由调查、勘测完成后，所有者应当在计划铺设施工60天前，将最后确定的海底电缆、管道路由报主管机关审批，并附具以下资料："},{"i":7,"n":"第七条","txt":"铺设施工完毕后，所有者应当将海底电缆、管道的路线图、位置表等说明资料报送主管机关备案，并抄送港监机关。"},{"i":8,"n":"第八条","txt":"海底电缆、管道的铺设和为铺设所进行的路由调查、勘测活动，不得在获准作业区域以外的海域作业，也不得在获准区域内进行未经批准的作业。"},{"i":9,"n":"第九条","txt":"获准施工的海底电缆、管道在施工前或施工中如需变动，所有者应当及时向主管机关报告。如该项变动重大，主管机关可采取相应措施，直至责令其停止施工。"},{"i":10,"n":"第十条","txt":"海底电缆、管道的维修、改造、拆除和废弃，所有者应当提前向主管机关报告。路由变动较大的改造，依照本规定重新办理有关手续。"},{"i":11,"n":"第十一条","txt":"海底电缆、管道的路由调查、勘测和铺设、维修、拆除等施工作业，不得妨害海上正常秩序。"},{"i":12,"n":"第十二条","txt":"铺设海底电缆、管道及其他海上作业，需要移动已铺设的海底电缆、管道时，应当先与所有者协商，并经主管机关批准后方可施工。"},{"i":13,"n":"第十三条","txt":"从事海上各种活动的作业者，必须保护已铺设的海底电缆、管道。造成损害的应当依法赔偿。"},{"i":14,"n":"第十四条","txt":"主管机关有权对海底电缆、管道的铺设、维修、改造、拆除、废弃以及为铺设所进行的路由调查、勘测活动进行监督和检查。对违反本规定的，主管机关可处以警告、罚款直至责令其停止海上作业。"},{"i":15,"n":"第十五条","txt":"为海洋石油开发所铺设的超出石油开发区的海底电缆、管道的路由，应当在油（气）田总体开发方案审批前报主管机关，由主管机关商国家能源主管部门批准。"},{"i":16,"n":"第十六条","txt":"铺设、维修、改造、拆除、废弃海底电缆、管道以及为铺设所进行的路由调查、勘测活动，本规定未作规定的，适用国家其他有关法律、法规的规定。"},{"i":17,"n":"第十七条","txt":"中华人民共和国军用海底电缆、管道的铺设依照本规定执行。军队可以制定具体实施办法。"},{"i":18,"n":"第十八条","txt":"主管机关应当收集海底地形、海上构筑物分布等方面的资料，为海底电缆、管道的铺设及其调查、勘测活动提供咨询服务。"},{"i":19,"n":"第十九条","txt":"本规定中的“电缆”系指通信电缆及电力电缆；“管道”系指输水、输气、输油及输送其他物质的管状输送设施。"},{"i":20,"n":"第二十条","txt":"本规定由中华人民共和国国家海洋局负责解释。"},{"i":21,"n":"第二十一条","txt":"本规定自1989年3月1日起施行。"}],"gaodengjiaoyuguanlizhizezanxingguiding":[]};
